import java.util.Arrays;
 
public class Knapsack {
    public static class Item {
        public String name;
        public int weight;
        public int value;
    }
 
    public static Item[] items = {
        new Item("map", 9, 150),
        new Item("compass", 13, 35),
        new Item("water", 153, 200),
        new Item("sandwich", 50, 160),
        new Item("glucose", 15, 60),
        new Item("tin", 68, 45),
        new Item("banana", 27, 60),
        new Item("apple", 39, 40),
        new Item("cheese", 23, 30),
        new Item("beer", 52, 10),
        new Item("suntan cream", 11, 70),
        new Item("camera", 32, 30),
        new Item("T-shirt", 24, 15),
        new Item("trousers", 48, 10),
        new Item("umbrella", 73, 40),
        new Item("waterproof trousers", 42, 70),
        new Item("waterproof overclothes", 43, 75),
        new Item("note-case", 22, 80),
        new Item("sunglasses", 7, 20),
        new Item("towel", 18, 12),
        new Item("socks", 4, 50),
        new Item("book", 30, 10),
    };
 
    public static int[] knapsack(Item[] items, int n, int w) {
        int i, j, a, b, mm[] = new int[(n + 1) * (w + 1)], m[] = new int[n + 1], s[] = new int[n];
        for (i = 0; i < n + 1; i++) {
            m[i] = i * (w + 1);
        }
        for (i = 1; i <= n; i++) {
            for (j = 0; j <= w; j++) {
                if (items[i - 1].weight > j) {
                    mm[m[i] + j] = mm[m[i - 1] + j];
                }
                else {
                    a = mm[m[i - 1] + j];
                    b = mm[m[i - 1] + j - items[i - 1].weight] + items[i - 1].value;
                    mm[m[i] + j] = a > b? a : b;
                }
            }
        }
        for (i = n, j = w; i > 0; i--) {
            if (mm[m[i] + j] > mm[m[i - 1] + j]) {
                s[i - 1] = 1;
                j -= items[i - 1].weight;
            }
        }
        return s;
    }
 
    public static void main(String[] args) {
        int i, n, tw = 0, tv = 0, s[];
        n = items.length;
        s = knapsack(items, n, 400);
        for (i = 0; i < n; i++) {
            if (s[i] == 1) {
                System.out.printf("%-22s %5d %5d\n", items[i].name, items[i].weight, items[i].value);
                tw += items[i].weight;
                tv += items[i].value;
            }
        }
        System.out.printf("%-22s %5d %5d\n", "totals:", tw, tv);
    }
}

public static boolean prime(int a) {
    return (a < 2 || IntStream.range(2, (int) Math.sqrt(a) + 1).anyMatch(x -> a % x == 0));
}

