import java.awt.*;
import javax.swing.*;
 
class ArchimedeanSpiral extends JPanel {
    public ArchimedeanSpiral() {
        super();
        this.setPreferredSize(new Dimension(640, 640));
        this.setBackground(Color.white);
    }
 
    private void drawGrid(Graphics2D g) {
        g.setColor(new Color(0xEEEEEE));
        g.setStroke(new BasicStroke(2f));
        double angle = Math.toRadians(45.0);
        int w = this.getWidth();
        int center = w / 2;
        int margin = 10;
        int numRings = 8;
        int spacing = (w - 2 * margin) / (numRings * 2);
 
        for (int i = 0; i < numRings; i++) {
            int pos = margin + i * spacing;
            int size = w - (2 * margin + i * 2 * spacing);
            g.drawOval(pos, pos, size, size);
            double ia = i * angle;
            int x2 = center + (int) (Math.cos(ia) * (w - 2 * margin) / 2);
            int y2 = center - (int) (Math.sin(ia) * (w - 2 * margin) / 2);
            g.drawLine(center, center, x2, y2);
        }
    }
 
    private void drawSpiral(Graphics2D g) {
        g.setStroke(new BasicStroke(2f));
        g.setColor(Color.magenta);
        double degrees = Math.toRadians(0.1);
        int center = this.getWidth() / 2;
        double end = 360 * 2 * 10 * degrees;
        double a = 0.0;
        double b = 20.0;
        double c = 1.0;
        double theta = 0.0;
        while (theta < end) {
            double r = a + Math.pow(theta, 1.0 / c) * b;
            int x = (int) (r * Math.cos(theta));
            int y = (int) (r * Math.sin(theta));
            plot(g, center + x, center - y);
            theta += degrees;
        }
    }
 
    private void plot(Graphics2D g, int x, int y) {
        g.drawOval(x, y, 1, 1);
    }
 
    @Override
    public void paintComponent(Graphics gg) {
        super.paintComponent(gg);
        Graphics2D g = (Graphics2D) gg;
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        drawGrid(g);
        drawSpiral(g);
    }
}
 
public class Main {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                JFrame f = new JFrame();
                f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
                f.setTitle("Archimedean Spiral");
                f.setResizable(false);
                f.add(new ArchimedeanSpiral(), BorderLayout.CENTER);
                f.pack();
                f.setLocationRelativeTo(null);
                f.setVisible(true);
            }
        });
    }
}

