public class DigitalRoot {
    public static void main(String[] args) {
        for (int n : new int[] {627615, 39390, 588225, 393900588225, 55}) {
            int[] digitalRoot = digitalRoot(n);
            System.out.printf("%12d has additive persistance %2d and digital root %d.%n", n, digitalRoot[0], digitalRoot[1]);
        }
    }
    public static int[] digitalRoot(int n) {
        int ap = 0;
        n = Math.abs(n);
        while (n >= 10) {
            n = sumDigits(n);
            ap++;
        }
        return new int[] {ap, n};
    }
    public static int sumDigits(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }
}

public class Ackermann {
    public static int ack(int m, int n) {
        if (m == 0) {
            return n + 1;
        } else {
            if (n == 0) {
                return ack(m - 1, 1);
            } else {
                return ack(m - 1, ack(m, n - 1));
            }
        }
    }
}

