import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Consumer;

public class YingYang {
    public static void main(String[] args) {
        Arc[] YingYang = new Arc[]{
                new Arc(0.5, 0.5, 1, 0.5 * Math.PI, 1.5 * Math.PI, "white"),//Half white semi-circle
                new Arc(0.5, 0.5, 1, 1.5 * Math.PI, 0.5 * Math.PI, "black"),//Half black semi-circle
                new Arc(0.5, 0.25,.5, 0, 2 * Math.PI, "black"),//black circle
                new Arc(0.5, 0.75,.5, 0, 2 * Math.PI, "white"),//white circle
                new Arc(0.5, 0.25, 1 / 6, 0, 2 * Math.PI, "white"),//small white circle
                new Arc(0.5, 0.75, 1 / 6, 0, 2 * Math.PI, "black")//small black circle
        };
        Array2D mat = new Array2D(100, 100);
        for (int i = 0; i < mat.height; i++) {
            for (int i2 = 0; i2 < mat.width; i2++) {
                for (Arc arc : YingYang) {
                    if (arc.contains(i, i2)) {
                        mat.array2d[i][i2] = arc.color;
                        break;
                    }
                }
            }
        }
        mat.loop((s, i, i2) -> {
            if (s == null) {
                System.out.print(" ");
            } else {
                System.out.print(s);
            }
            if (i2 == mat.width - 1) {
                System.out.println();
            }
        });
    }

    static class Arc {
        double posX;
        double posY;
        double radius;
        double startAngle;
        double endAngle;
        String color;

        public Arc(double posX, double posY, double radius, double startAngle, double endAngle, String color) {
            this.posX = posX;
            this.posY = posY;
            this.radius = radius;
            this.startAngle = startAngle;
            this.endAngle = endAngle;
            this.color = color;
        }

        public boolean contains(int x, int y) {
            double angle = Math.atan2(y - posY, x - posX);
            if (angle < 0) {
                angle += 2 * Math.PI;
            }
            return angle >= startAngle && angle <= endAngle && Math.sqrt(Math.pow(x - posX, 2) + Math.pow(y - posY, 2)) <= radius;
        }
    }

    static class Array2D {
        int height;
        int width;
        String[][] array2d;

        public Array2D(int width, int height) {
            this.height = height;
            this.width = width;
            this.array2d = new String[height][width];
        }

        public void resize(int width, int height) {
            int nheight = height - this.height, nwidth = width - this.width;
            if (nwidth > 0) {
                for (int i = 0; i < this.height; i++) {
                    if (i < height)
                        Arrays.fill(this.array2d[i], width, width + nwidth, null);
                }
            } else if (nwidth < 0) {
                for (int i = 0; i < this.height; i++) {
                    if (i < height)
                        System.arraycopy(this.array2d[i], width, this.array2d[i], 0, nwidth);
                }
            }
            if (nheight > 0) {
                System.arraycopy(this.array2d, height, this.array2d, 0, nheight);
            } else if (nheight < 0) {
                System.arraycopy(this.array2d, height, this.array2d, 0, nheight);
            }
        }

        public void loop(BiConsumer<String, Integer, Integer> callback) {
            for (int i = 0; i < this.height; i++)
                for (int i2 = 0; i2 < this.width; i2++)
                    callback.accept(this.array2d[i][i2], i, i2);

        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class Donuts {
	public static void main(String[] args) {
		disp(pick(2, new ArrayList<String>(), 0, new String[] { "iced", "jam", "plain" }, true) + " combos");
		disp("pick 3 out of 10: " + pick(3, new ArrayList<String>(), 0, "a123456789".split(""), false) + " combos");
	}

	public static void disp(String x) {
		System.out.println(x);
	}

	public static int pick(int n, List<String> got, int pos, String[] from, boolean show) {
		int cnt = 0;
		if (got.size() == n) {
			if (show) disp(String.join(" ", got));
			return 1;
		}
		for (int i = pos; i < from.length; i++) {
			got.add(from[i]);
			cnt += pick(n, got, i, from, show);
			got.remove(got.size() - 1);
		}
		return cnt;
	}
}

import java.util.Arrays;

public class PythagoreanQuadruples {
    static final int MAX = 2200;
    static final int MAX2 = MAX * MAX * 2;

    public static void main(String[] args) {
        boolean[] found = new boolean[MAX + 1]; // all false by default
        boolean[] a2b2 = new boolean[MAX2 + 1]; // ditto
        int s = 3;

        for(int a = 1; a <= MAX; a++) {
            int a2 = a * a;
            for (int b=a; b<=MAX; b++) {
                a2b2[a2 + b * b] = true;
            }
        }

        for (int c = 1; c <= MAX; c++) {
            int s1 = s;
            s += 2;
            int s2 = s;
            for (int d = c + 1; d <= MAX; d++) {
                if (a2b2[s1]) found[d] = true;
                s1 += s2;
                s2 += 2;
            }
        }

        System.out.println("The values of d <= " + MAX + " which can't be represented:");
        for (int d = 1; d < MAX; d++) {
            if (!found[d]) System.out.print(d + "  ");
        }
        System.out.println();
    }
}

public class CreatePwd {
    public static void main(String[] args) {
        System.out.println(createPwd());
        System.out.println(createPwd(20));
        System.out.println(createPwd(20, 2));
        System.out.println(createPwd(20, 2, false));
    }

    public static String createPwd() {
        return createPwd(5, 1, true);
    }

    public static String createPwd(int len) {
        return createPwd(len, 1, true);
    }

    public static String createPwd(int len, int num) {
        return createPwd(len, num, true);
    }

    public static String createPwd(int len, int num, boolean noSims) {
        String[] out = new String[num];
        String cur;
        int i;

        String[][] chars = {
            "abcdefghijkmnopqrstuvwxyz".split(""),
            "ABCDEFGHJKLMNPQRTUVWXY".split(""),
            "346789".split(""),
            "!\"#$%&()*+,-./:;<=>?@[]^_{|}".split("")
        };

        if (!noSims) {
            chars[0] = Arrays.copyOf(chars[0], chars[0].length + 1);
            chars[0][chars[0].length - 1] = "l";
            chars[1] = Arrays.copyOf(chars[1], chars[1].length + 4);
            chars[1][chars[1].length - 4] = "I";
            chars[1][chars[1].length - 3] = "O";
            chars[1][chars[1].length - 2] = "S";
            chars[1][chars[1].length - 1] = "Z";
            chars[2] = Arrays.copyOf(chars[2], chars[2].length + 4);
            chars[2][chars[2].length - 4] = "1";
            chars[2][chars[2].length - 3] = "2";
            chars[2][chars[2].length - 2] = "5";
            chars[2][chars[2].length - 1] = "0";
        }

        if (len < 4) {
            System.out.println("Password length changed to 4 (minimum)");
            len = 4;
        }

        for (i = 0; i < num; i++) {
            cur = "";
            // basic requirement
            for (int j = 0; j < 4; j++) {
                cur += chars[j][(int) (Math.random() * chars[j].length)];
            }

            while (cur.length() < len) {
                int rnd = (int) (Math.random() * chars.length);
                cur += chars[rnd][(int) (Math.random() * chars[rnd].length)];
            }
            out[i] = cur;
        }

        for (i = 0; i < out.length; i++) {
            out[i] = shuffle(out[i]);
        }

        if (out.length == 1) {
            return out[0];
        }
        return Arrays.toString(out);
    }

    public static String shuffle(String str) {
        char[] chars = str.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            int rnd = (int) (Math.random() * chars.length);
            char tmp = chars[i];
            chars[i] = chars[rnd];
            chars[rnd] = tmp;
        }
        return new String(chars);
    }
}

import java.io.*;
import java.util.*;
 
public class BubbleSort {
 
    public static void bubble_sort(int[] idx, int n_idx, int[] buf) {
        int i, j, tmp;
        for (i = 0; i < n_idx; i++) {
            for (j = i + 1; j < n_idx; j++) {
                if (idx[j] < idx[i]) {
                    tmp = idx[i];
                    idx[i] = idx[j];
                    idx[j] = tmp;
                }
            }
        }
        for (i = 0; i < n_idx; i++) {
            for (j = i + 1; j < n_idx; j++) {
                if (buf[idx[j]] < buf[idx[i]]) {
                    tmp = buf[idx[i]];
                    buf[idx[i]] = buf[idx[j]];
                    buf[idx[j]] = tmp;
                }
            }
        }
    }
 
    public static void main(String[] args) {
        int[] values = {7, 6, 5, 4, 3, 2, 1, 0};
        int[] idx = {6, 1, 7};
        int i;
 
        System.out.println("before sort:");
        for (i = 0; i < 8; i++) {
            System.out.print(values[i] + " ");
        }
 
        System.out.println("\n\nafter sort:");
        bubble_sort(idx, 3, values);
 
        for (i = 0; i < 8; i++) {
            System.out.print(values[i] + " ");
        }
        System.out.println();
    }
}

import java.util.Arrays;
import java.util.stream.IntStream;
 
public class Catalan {
 
    public static void main(String[] args) {
        System.out.println("       direct     rec1     rec2");
        for (int n = 0; n < 16; n++) {
            System.out.printf("%2d :%9d%9d%9d%n", n, catalan_direct(n), catalan_rec1(n), catalan_rec2(n));
        }
    }
 
    public static int factorial(int n) {
        return IntStream.rangeClosed(1, n).reduce(1, (a, b) -> a * b);
    }
 
    public static int catalan_direct(int n) {
        return factorial(2 * n) / (factorial(n + 1) * factorial(n));
    }
 
    public static int catalan_rec1(int n) {
        if (n == 0) {
            return 1;
        }
        return IntStream.range(0, n).map(i -> catalan_rec1(i) * catalan_rec1(n - 1 - i)).sum();
    }
 
    public static int catalan_rec2(int n) {
        if (n == 0) {
            return 1;
        }
        return 2 * (2 * n - 1) * catalan_rec2(n - 1) / (n + 1);
    }
}

public class Hailstone {
 
    public static long hailstone(long n, long[][] sequence) {
        long i = 0;
        long[] seq = new long[1000000];
        while (n!= 1) {
            if (n % 2 == 0) {
                n = n / 2;
            } else {
                n = 3 * n + 1;
            }
            seq[(int) i] = n;
            i++;
        }
        sequence[0] = seq;
        return i;
    }
 
    public static void free_sequence(long[] seq) {
        seq = null;
    }
}

import java.util.Scanner;

public class rref {
    public static void main(String[] args) {
        int[][] matrix = new int[3][4];
        matrix[0][0] = 1;
        matrix[0][1] = 2;
        matrix[0][2] = -1;
        matrix[0][3] = -4;
        matrix[1][0] = 2;
        matrix[1][1] = 3;
        matrix[1][2] = -1;
        matrix[1][3] = -11;
        matrix[2][0] = -2;
        matrix[2][1] = 0;
        matrix[2][2] = -3;
        matrix[2][3] = 22;
        matrix = rref(matrix);
    }

    private static int[][] rref(int[][] matrix) {
        int lead = 0, rowCount = matrix.length, columnCount = matrix[0].length;
        for (int r = 0; r < rowCount; r++) {
            if (columnCount <= lead) break;
            int i = r;
            while (matrix[i][lead] == 0) {
                i++;
                if (i == rowCount) {
                    i = r;
                    lead++;
                    if (columnCount == lead) {
                        lead--;
                        break;
                    }
                }
            }
            for (int j = 0; j < columnCount; j++) {
                int temp = matrix[r][j];
                matrix[r][j] = matrix[i][j];
                matrix[i][j] = temp;
            }
            int div = matrix[r][lead];
            if (div!= 0)
                for (int j = 0; j < columnCount; j++) matrix[r][j] /= div;
            for (int j = 0; j < rowCount; j++) {
                if (j!= r) {
                    int sub = matrix[j][lead];
                    for (int k = 0; k < columnCount; k++) matrix[j][k] -= (sub * matrix[r][k]);
                }
            }
            lead++;
        }
        return matrix;
    }
}

task_description:
Implement some operations on variable-length quantities, at least including conversions from a normal number in the language to the binary representation of the variable-length quantity for that number, and vice versa. Any variants are acceptable.



Task

With above operations,

convert these two numbers 0x200000 (2097152 in decimal) and 0x1fffff (2097151 in decimal) into sequences of octets (an eight-bit byte); 
display these sequences of octets;
convert these sequences of octets back to numbers, and check that they are equal to original numbers.

code:
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.util.Arrays;
 
public class Main {
    public static void main(String[] args) throws IOException {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        for (long x : new long[]{0x200000, 0x1fffff}) {
            buf.write(putVarint(buf, x));
            System.out.printf("%d encodes into %d bytes: %x\n", x, buf.size(), buf.toByteArray());
            x = varint(buf.toByteArray());
            System.out.println(x + " decoded");
        }
    }
 
    public static byte[] putVarint(ByteArrayOutputStream buf, long x) throws IOException {
        while (x >= 0x80) {
            buf.write((int) ((x & 0x7f) | 0x80));
            x >>>= 7;
        }
        buf.write((int) x);
        return buf.toByteArray();
    }
 
    public static long varint(byte[] buf) {
        ByteBuffer buffer = ByteBuffer.wrap(buf);
        long x = 0;
        int s = 0;
        for (int i = 0; i < buf.length; i++) {
            byte b = buffer.get();
            x |= (long) (b & 0x7f) << s;
            if ((b & 0x80) == 0) {
                return x;
            }
            s += 7;
        }
        throw new IllegalArgumentException("buffer too small");
    }
}

public static int jacobi(int a, int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("'n' must be a positive integer.");
    }
    if (n % 2 == 0) {
        throw new IllegalArgumentException("'n' must be odd.");
    }
    a %= n;
    int result = 1;
    while (a!= 0) {
        while (a % 2 == 0) {
            a /= 2;
            int nMod8 = n % 8;
            if (nMod8 == 3 || nMod8 == 5) {
                result = -result;
            }
        }
        int temp = a;
        a = n;
        n = temp;
        if (a % 4 == 3 && n % 4 == 3) {
            result = -result;
        }
        a %= n;
    }
    if (n == 1) {
        return result;
    } else {
        return 0;
    }
}

import java.util.Random;

public class BalancedBrackets {
    public static void main(String[] args) {
        int M = 20;
        while (M-- > 0) {
            int N = new Random().nextInt(10);
            String bs = shuffle("[".repeat(N) + "]".repeat(N));
            System.out.println("\"" + bs + "\" is " + (isBalanced(bs)? "" : "un") + "balanced");
        }
    }

    private static String shuffle(String str) {
        char[] a = str.toCharArray();
        int c = a.length;
        while (c > 0) {
            int b = new Random().nextInt(c--);
            char d = a[c];
            a[c] = a[b];
            a[b] = d;
        }
        return new String(a);
    }

    private static boolean isBalanced(String str) {
        String a = str, b;
        do {
            b = a;
            a = a.replace("[]", "");
        } while (!a.equals(b));
        return a.isEmpty();
    }
}

