import javax.swing.ImageIcon;
 
class BasicBitmapStorage {
    BufferedImage image;
 
    public BasicBitmapStorage(int width, int height) {
        image = new BufferedImage(width, height, BufferedImage.TYPE_3BYTE_BGR);
    }
 
    public void fill(Color c) {
        Graphics g = image.getGraphics();
        g.setColor(c);
        g.fillRect(0, 0, image.getWidth(), image.getHeight());
    }
 
    public void setPixel(int x, int y, Color c) {
        image.setRGB(x, y, c.getRGB());
    }
 
    public Color getPixel(int x, int y) {
        return new Color(image.getRGB(x, y));
    }
}
 
public class BresenhamCircle {
    public static void drawCircle(BasicBitmapStorage bbs, int centerX, int centerY, int radius, Color circleColor) {
        int d = (5 - radius * 4) / 4;
        int x = 0;
        int y = radius;
 
        do {
            bbs.setPixel(centerX + x, centerY + y, circleColor);
            bbs.setPixel(centerX + x, centerY - y, circleColor);
            bbs.setPixel(centerX - x, centerY + y, circleColor);
            bbs.setPixel(centerX - x, centerY - y, circleColor);
            bbs.setPixel(centerX + y, centerY + x, circleColor);
            bbs.setPixel(centerX + y, centerY - x, circleColor);
            bbs.setPixel(centerX - y, centerY + x, circleColor);
            bbs.setPixel(centerX - y, centerY - x, circleColor);
            if (d < 0) {
                d += 2 * x + 1;
            } 
            else {
                d += 2 * (x - y) + 1;
                y--;
            }
            x++;
        } 
        while (x <= y);
    }
 
    public static void main(String[] args) {
        BasicBitmapStorage bbs = new BasicBitmapStorage(400, 400);
        bbs.fill(Color.pink);
        drawCircle(bbs, 200, 200, 100, Color.black);
        drawCircle(bbs, 200, 200,  50, Color.white);     
        JLabel label = new JLabel(new ImageIcon(bbs.image));
        String title = "Bresenham's circle algorithm";
        JOptionPane.showMessageDialog(null, label, title, JOptionPane.PLAIN_MESSAGE);
    }
}

import java.util.BitSet;
 
public class SierpinskiTriangle {
    private int len;
    private BitSet b;
 
    public SierpinskiTriangle(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("Order must be greater than zero");
        }
        len = 1 << (n+1);
        b = new BitSet(len+1);
        b.set(len>>1);
    }
 
    public void display() {
        for (int j = 0; j < len / 2; j++) {
            for (int i = 0; i < b.length(); i++) {
                System.out.print(b.get(i)? "*" : " ");
            }
            System.out.println();
            nextGen();
        }
    }
 
    private void nextGen() {
        BitSet next = new BitSet(b.length());
        for (int i = 0; i < b.length(); i++) {
            if (b.get(i)) {
                next.set(i - 1);
                next.set(i + 1);
            }
        }
        b = next;
    }
}

