import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
 
public class SourceLocation {
 
    public static void main(String[] args) {
        System.out.println(sourceLocation(Math.class, "sqrt"));
        System.out.println(sourceLocation(Class.class, "nesting"));
    }
 
    public static List<String> sourceLocation(Class<?> klass, String methodName) {
        List<String> result = new ArrayList<>();
        Method method = findMethod(klass, methodName);
        if (method!= null) {
            result.add(method.getDeclaringClass().getName() + ".java");
            result.add(String.valueOf(method.getLineNumber()));
        }
        return result;
    }
 
    private static Method findMethod(Class<?> klass, String methodName) {
        Method[] methods = klass.getDeclaredMethods();
        for (Method method : methods) {
            if (method.getName().equals(methodName) &&!Modifier.isNative(method.getModifiers())) {
                return method;
            }
        }
        return null;
    }
}

