import java.util.Arrays;
import java.util.List;
 
// Holes A=0, B=1, …, H=7
// With connections:
final String conn = """
       A   B
      /|\ /|\
     / | X | \
    /  |/ \|  \
   C - D - E - F
    \  |\ /|  /
     \ | X | /
      \|/ \|/
       G   H
""";
 
final List<List<Integer>> connections = Arrays.asList(
    Arrays.asList(0, 2), Arrays.asList(0, 3), Arrays.asList(0, 4),   // A to C, D, E
    Arrays.asList(1, 3), Arrays.asList(1, 4), Arrays.asList(1, 5),   // B to D, E, F
    Arrays.asList(6, 2), Arrays.asList(6, 3), Arrays.asList(6, 4),   // G to C, D, E
    Arrays.asList(7, 3), Arrays.asList(7, 4), Arrays.asList(7, 5),   // H to D, E, F
    Arrays.asList(2, 3), Arrays.asList(3, 4), Arrays.asList(4, 5)    // C-D, D-E, E-F
);
 
// 'isValid' checks if the pegs are a valid solution.
// If the absolute difference between any pair of connected pegs is
// greater than one it is a valid solution.
boolean isValid(int[] pegs) {
    for (List<Integer> conn : connections) {
        if (Math.abs(pegs[conn.get(0)] - pegs[conn.get(1)]) <= 1) return false;
    }
    return true;
}
 
void swap(int[] pegs, int i, int j) {
    int tmp = pegs[i];
    pegs[i] = pegs[j];
    pegs[j] = tmp;
}
 
//'solve' is a simple recursive brute force solver,
// it stops at the first found solution.
// It returns the solution, the number of positions tested,
// and the number of pegs swapped.
 
Triple<int[], Integer, Integer> solve() {
    int[] pegs = new int[8];
    for (int i = 0; i < pegs.length; i++) pegs[i] = i + 1;
    int tests = 0;
    int swaps = 0;
 
    boolean recurse(int i) {
        if (i >= pegs.length - 1) {
            tests++;
            return isValid(pegs);
        }
        // Try each remaining peg from pegs[i] onwards
        for (int j = i; j < pegs.length; j++) {
            swaps++;
            swap(pegs, i, j);
            if (recurse(i + 1)) return true;
            swap(pegs, i, j);
        }
        return false;
    }
 
    recurse(0);
    return new Triple<>(pegs, tests, swaps);
}
 
String pegsAsString(int[] pegs) {
    char[] ca = conn.toCharArray();
    for (int i = 0; i < ca.length; i++) {
        if (ca[i] >= 'A' && ca[i] <= 'H') ca[i] = (char) ('0' + pegs[ca[i] - 'A']);
    }
    return new String(ca);
}
 
public static void main(String[] args) {
    Triple<int[], Integer, Integer> result = solve();
    int[] p = result.getFirst();
    int tests = result.getSecond();
    int swaps = result.getThird();
    System.out.println(pegsAsString(p));
    System.out.println("Tested " + tests + " positions and did " + swaps + " swaps.");
}

public class Test
{
    public static boolean valid(int n, int nuts)
    {
        for (int k = n; k!= 0; k--, nuts -= 1 + nuts / n)
        {
            if (nuts % n!= 1)
            {
                return false;
            }                
        }
 
        return nuts!= 0 && (nuts % n == 0);
    }
 
    public static void main(String[] args)
    {
        int x = 0;
        for (int n = 2; n < 10; n++)
        {
            while (!valid(n, x))
                x++;
            System.out.println(n + ": " + x);
        }
    }
}

import java.util.Arrays;
 
public class SMA {
	private final int period;
	private final double[] window;
	private int head;
	private int tail;
	private double total;
 
	public SMA(int period) {
		this.period = period;
		this.window = new double[period];
		this.head = 0;
		this.tail = 0;
		this.total = 0;
	}
 
	public void add(double val) {
		// Special case: Initialization
		if (head == 0) {
			head = 0;
			window[head] = val;
			tail = head;
			inc(tail);
			total = val;
			return;
		}
 
		// Were we already full?
		if (head == tail) {
			// Fix total-cache
			total -= window[head];
			// Make room
			inc(head);
		}
 
		// Write the value in the next spot.
		window[tail] = val;
		inc(tail);
 
		// Update our total-cache
		total += val;
	}
 
	public double avg() {
		int size = this.size();
		if (size == 0) {
			return 0; // No entries => 0 average
		}
		return total / (double) size; // Cast to double for floating point arithmetic
	}
 
	private void inc(int p) {
		if (++p >= window.length) {
			p = 0;
		}
	}
 
	private int size() {
		if (head == 0)
			return 0;
		if (head == tail)
			return period;
		return (period + tail - head) % period;
	}
 
	public static void main(String[] args) {
		SMA foo = new SMA(3);
		SMA bar = new SMA(5);
 
		int[] data = { 1, 2, 3, 4, 5, 5, 4, 3, 2, 1 };
		for (int i : data) {
			foo.add(i);
			System.out.println("Added " + i + " avg: " + foo.avg());
		}
		System.out.println();
		for (int i : data) {
			bar.add(i);
			System.out.println("Added " + i + " avg: " + bar.avg());
		}
	}
}

