class Node<T extends Number> {
    T data;
    Node<T> next;
    public Node(T data, Node<T> next) {
        this.data = data;
        this.next = next;
    }
    public Node(T data) {
        this.data = data;
    }
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder(this.data.toString());
        Node<T> node = this.next;
        while (node!= null) {
            sb.append(" -> ").append(node.data.toString());
            node = node.next;
        }
        return sb.toString();
    }
}
 
public static <T extends Number> void insertAfter(Node<T> prev, Node<T> new) {
    new.next = prev.next;
    prev.next = new;
}
 
public static void main(String[] args) {
    Node<Integer> b = new Node<>(3);
    Node<Integer> a = new Node<>(1, b);
    System.out.println("Before insertion : " + a);
    Node<Integer> c = new Node<>(2);
    insertAfter(a, c);
    System.out.println("After  insertion : " + a);
}

