import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

public class DaysOfWeek {

    public static void main(String[] args) {
        List<String> lines = new ArrayList<>();
        try {
            lines = new File("days_of_week.txt").readLines();
        } catch (Exception e) {
            e.printStackTrace();
        }
        Pattern r = Pattern.compile("[ ]+");
        for (int i = 0; i < lines.size(); i++) {
            String line = lines.get(i);
            if (line.trim().isEmpty()) {
                System.out.println();
                continue;
            }
            String[] days = r.split(line.trim());
            if (days.length!= 7) throw new RuntimeException("There aren't 7 days in line " + (i + 1));
            if (new ArrayList<>(new HashSet<>(Arrays.asList(days))).size() < 7) { // implies some days have the same name
                System.out.println(" ∞  " + line);
                continue;
            }
            int len = 1;
            while (true) {
                if (new ArrayList<>(new HashSet<>(Arrays.asList(days))).size() == 7) {
                    System.out.println(String.format("%2d", len) + "  " + line);
                    break;
                }
                len++;
            }
        }
    }
}

