import java.util.Map;
import java.util.HashMap;
import java.util.List;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
 
public class Primes {
    public static class Transition {
        public final int first;
        public final int second;
        public Transition(int first, int second) {
            this.first = first;
            this.second = second;
        }
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass()!= o.getClass()) return false;
            Transition that = (Transition) o;
            return first == that.first && second == that.second;
        }
        @Override
        public int hashCode() {
            return 31 * first + second;
        }
        @Override
        public String toString() {
            return "(" + first + ", " + second + ")";
        }
    }
 
    public static boolean isPrime(int n) {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        if (n % 3 == 0) return n == 3;
        int d = 5;
        while (d * d <= n) {
            if (n % d == 0) return false;
            d += 2;
            if (n % d == 0) return false;
            d += 4;
        }
        return true;
    }
 
    public static List<Integer> generatePrimes() {
        List<Integer> primes = new ArrayList<>();
        primes.add(2);
        int p = 3;
        while (p <= Integer.MAX_VALUE) {
            if (isPrime(p)) primes.add(p);
            p += 2;
        }
        return primes;
    }
 
    public static void main(String[] args) {
        List<Integer> primes = generatePrimes();
        primes = primes.subList(0, 1_000_000);
        Map<Transition, Integer> transMap = new HashMap<>();
        for (int i = 0; i < primes.size() - 1; i++) {
            Transition transition = new Transition(primes.get(i) % 10, primes.get(i + 1) % 10);
            if (transMap.containsKey(transition))
                transMap.put(transition, transMap.get(transition) + 1);
            else
                transMap.put(transition, 1);
        }
        List<Transition> sortedTransitions = new ArrayList<>(transMap.keySet());
        Collections.sort(sortedTransitions, new Comparator<Transition>() {
            @Override
            public int compare(Transition o1, Transition o2) {
                return o1.first - o2.first;
            }
        });
        Collections.sort(sortedTransitions, new Comparator<Transition>() {
            @Override
            public int compare(Transition o1, Transition o2) {
                return o1.second - o2.second;
            }
        });
        System.out.println("First 1,000,000 primes. Transitions prime % 10 -> next-prime % 10.");
        for (Transition trans : sortedTransitions) {
            System.out.printf("%d -> %d  count: %5d  frequency: %4.2f%%%n",
                    trans.first, trans.second, transMap.get(trans), transMap.get(trans) / 10000.0);
        }
    }
}

import java.util.Random;
 
public class ShellSort {
 
    private static final int MAX = 126;
 
    public static void main(String[] args) {
 
        Random random = new Random();
        int[] arr = new int[MAX];
        for (int x = 0; x < MAX; x++) {
            arr[x] = random.nextInt(MAX) - random.nextInt(MAX);
        }
 
        System.out.println(" Before: \n=========\n");
        for (int x = 0; x < 7; x++) {
            for (int a = 0; a < 18; a++) {
                System.out.print(arr[x * 18 + a] + " ");
            }
            System.out.println();
        }
        System.out.println();
 
        ShellSort shellSort = new ShellSort();
        shellSort.sort(arr);
 
        System.out.println(" After: \n========\n");
        for (int x = 0; x < 7; x++) {
            for (int a = 0; a < 18; a++) {
                System.out.print(arr[x * 18 + a] + " ");
            }
            System.out.println();
        }
        System.out.println();
    }
 
    private int[] gap = {1750, 701, 301, 132, 57, 23, 10, 4, 1};
    private int idx;
    private int cnt;
 
    public void sort(int[] arr) {
        cnt = arr.length;
        for (int x = 0; x < 9; x++) {
            if (cnt > gap[x]) {
                idx = x;
                break;
            }
        }
 
        sortIt(arr);
    }
 
    private void sortIt(int[] arr) {
        boolean sorted = false;
        while (true) {
            sorted = true;
            int st = 0;
            for (int x = gap[idx]; x < cnt; x += gap[idx]) {
                if (arr[st] > arr[x]) {
                    swap(arr, st, x);
                    sorted = false;
                }
                st = x;
            }
            if (++idx >= 8) {
                idx = 8;
            }
            if (sorted && idx == 8) {
                break;
            }
        }
    }
 
    private void swap(int[] arr, int a, int b) {
        int t = arr[a];
        arr[a] = arr[b];
        arr[b] = t;
    }
}

