import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
 
public class NthRoot {
 
    public static void main(String[] args) {
        System.out.println(nthroot(2, 2, 100));
    }
 
    public static BigDecimal nthroot(int n, BigDecimal A, int precision) {
        MathContext mc = new MathContext(precision, RoundingMode.HALF_UP);
        BigDecimal n_dec = new BigDecimal(n);
        BigDecimal x_0 = A.divide(n_dec, mc); //step 1: make a while guess.
        BigDecimal x_1 = BigDecimal.ONE; //need it to exist before step 2
        while (true) {
            //step 2:
            x_0 = x_1;
            x_1 = (BigDecimal.ONE.divide(n_dec, mc)).multiply((n_dec.subtract(BigDecimal.ONE)).multiply(x_0).add(A.divide(x_0.pow(n - 1), mc)));
            if (x_0.equals(x_1)) {
                return x_1;
            }
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
 
public class Main {
 
    public static void main(String[] args) {
        List<String> listOfStrings = new ArrayList<>();
        listOfStrings.add("abcd");
        listOfStrings.add("123456789");
        listOfStrings.add("abcdef");
        listOfStrings.add("1234567");
        compareAndReportStringsLength(listOfStrings);
    }
 
    public static void compareAndReportStringsLength(List<String> listOfStrings) {
        if (!listOfStrings.isEmpty()) {
            String Q = "\"";
            String has_length = " has length ";
            String predicate_max = " and is the longest string";
            String predicate_min = " and is the shortest string";
            String predicate_ave = " and is neither the longest nor the shortest string";
 
            List<String> ls = new ArrayList<>(listOfStrings); // clone to avoid side-effects
            Collections.sort(ls, new Comparator<String>() {
                @Override
                public int compare(String a, String b) {
                    return b.length() - a.length(); // reverse sort!
                }
            });
            int max = ls.get(0).length();
            int min = ls.get(ls.size() - 1).length();
 
            for (String s : ls) {
                int length = s.length();
                String predicate;
                if (length == max) {
                    predicate = predicate_max;
                } else if (length == min) {
                    predicate = predicate_min;
                } else {
                    predicate = predicate_ave;
                }
 
                System.out.println(Q + s + Q + has_length + length + predicate);
            }
        }
    }
}

import java.util.HashMap;
import java.util.Map;
 
public class RomanNumerals {
    private static final Map<Integer, String> romanNumerals = new HashMap<>();
    static {
        romanNumerals.put(1000, "M");
        romanNumerals.put(900, "CM");
        romanNumerals.put(500, "D");
        romanNumerals.put(400, "CD");
        romanNumerals.put(100, "C");
        romanNumerals.put(90, "XC");
        romanNumerals.put(50, "L");
        romanNumerals.put(40, "XL");
        romanNumerals.put(10, "X");
        romanNumerals.put(9, "IX");
        romanNumerals.put(5, "V");
        romanNumerals.put(4, "IV");
        romanNumerals.put(1, "I");
    }
 
    public static String encode(int number) {
        if (number > 5000 || number < 1) {
            return null;
        }
        int num = number;
        String result = "";
        for (Map.Entry<Integer, String> entry : romanNumerals.entrySet()) {
            int multiple = entry.getKey();
            String numeral = entry.getValue();
            while (num >= multiple) {
                num -= multiple;
                result += numeral;
            }
        }
        return result;
    }
 
    public static void main(String[] args) {
        System.out.println(encode(1990));
        System.out.println(encode(1666));
        System.out.println(encode(2008));
    }
}

import java.util.Arrays;
import java.util.stream.IntStream;
 
public class KolakoskiSequence {
    public static class Crutch {
        public final int len;
        public int[] s;
        public int i;
 
        public Crutch(int len) {
            this.len = len;
            s = new int[len];
            i = 0;
        }
 
        public void Repeat(int count) {
            for (int j = 0; j < count; j++) {
                if (++i == len) return;
                s[i] = s[i - 1];
            }
        }
    }
 
    public static class Extension {
        public static int NextInCycle(int[] self, int index) {
            return self[index % self.length];
        }
 
        public static int[] Kolakoski(int[] self, int len) {
            Crutch c = new Crutch(len);
 
            int k = 0;
            while (c.i < len) {
                c.s[c.i] = NextInCycle(self, k);
                if (c.s[k] > 1) {
                    c.Repeat(c.s[k] - 1);
                }
                if (++c.i == len) return c.s;
                k++;
            }
            return c.s;
        }
 
        public static boolean PossibleKolakoski(int[] self) {
            int[] rle = new int[self.length];
            int prev = self[0];
            int count = 1;
            int pos = 0;
            for (int i = 1; i < self.length; i++) {
                if (self[i] == prev) {
                    count++;
                }
                else {
                    rle[pos++] = count;
                    count = 1;
                    prev = self[i];
                }
            }
            // no point adding final 'count' to rle as we're not going to compare it anyway
            for (int i = 0; i < pos; i++) {
                if (rle[i]!= self[i]) {
                    return false;
                }
            }
            return true;
        }
 
        public static String AsString(int[] self) {
            StringBuilder sb = new StringBuilder("[");
            int count = 0;
            for (int item : self) {
                if (count > 0) {
                    sb.append(", ");
                }
                sb.append(item);
                count++;
            }
            return sb.append("]").toString();
        }
    }
 
    public static void main(String[] args) {
        int[][] ias = {
                new int[]{1, 2},
                new int[]{2, 1},
                new int[]{1, 3, 1, 2},
                new int[]{1, 3, 2, 1}
        };
        int[] lens = { 20, 20, 30, 30 };
 
        for (int i = 0; i < ias.length; i++) {
            int len = lens[i];
            int[] kol = Extension.Kolakoski(ias[i], len);
 
            System.out.println("First " + len + " members of the sequence by " + Extension.AsString(ias[i]) + ": ");
            System.out.println(Extension.AsString(kol));
            System.out.println("Possible Kolakoski sequence? " + Extension.PossibleKolakoski(kol));
            System.out.println();
        }
    }
}

import java.util.Arrays;
 
public class PatienceSort {
 
	public static int[] patienceSort(int[] arr) {
		int[][] decks = new int[arr.length][arr.length];
		int[] count = new int[arr.length];
		int[] sortedArr = new int[arr.length];
		int i, j, min, pickedRow;
 
		for (i = 0; i < arr.length; i++) {
			for (j = 0; j < arr.length; j++) {
				if (count[j] == 0 || (count[j] > 0 && decks[j][count[j] - 1] >= arr[i])) {
					decks[j][count[j]] = arr[i];
					count[j]++;
					break;
				}
			}
		}
 
		min = decks[0][count[0] - 1];
		pickedRow = 0;
 
		for (i = 0; i < arr.length; i++) {
			for (j = 0; j < arr.length; j++) {
				if (count[j] > 0 && decks[j][count[j] - 1] < min) {
					min = decks[j][count[j] - 1];
					pickedRow = j;
				}
			}
			sortedArr[i] = min;
			count[pickedRow]--;
 
			for (j = 0; j < arr.length; j++)
				if (count[j] > 0) {
					min = decks[j][count[j] - 1];
					pickedRow = j;
					break;
				}
		}
 
		return sortedArr;
	}
 
}

