import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class OrderDisjointArrayItems {
  
  public static <T> void print(List<T> v) {
    System.out.print("{ ");
    for (T e : v) {
      System.out.print(e + " ");
    }
    System.out.print("}");
  }
  
  public static <T> List<T> orderDisjointArrayItems(List<T> M, List<T> N) {
    List<T> M_p = IntStream.range(0, M.size()).mapToObj(i -> M.get(i)).collect(Collectors.toList());
    for (T e : N) {
      int i = 0;
      for (; i < M_p.size(); ++i) {
        if (M_p.get(i)!= null) {
          if (M_p.get(i).equals(e)) {
            break;
          }
        }
      }
      if (i!= M_p.size()) {
        M_p.set(i, null);
      }
    }
    for (int i = 0; i < N.size(); ++i) {
      int j = 0;
      for (; j < M_p.size(); ++j) {
        if (M_p.get(j) == null) {
          break;
        }
      }
      if (j!= M_p.size()) {
        M_p.set(j, M.get(j));
        M_p.set(j, N.get(i));
      }
    }
    return M;
  }
  
  public static void main(String[] args) {
    List<List<List<String>>> l = new ArrayList<>();
    l.add(new ArrayList<List<String>>() {{
