BufferedImage tImage = ImageIO.read(new File("spectrum.bmp"));

for (int x = 0; x < tImage.getWidth(); x++)
{
	for (int y = 0; y < tImage.getHeight(); y++)
	{
		Color tCol = new Color(tImage.getRGB(x, y));

		// L = 0.2126·R + 0.7152·G + 0.0722·B 
		double L = 0.2126 * tCol.getRed() + 0.7152 * tCol.getGreen() + 0.0722 * tCol.getBlue();
		tImage.setRGB(x, y, new Color(Convert.ToInt32(L), Convert.ToInt32(L), Convert.ToInt32(L)).getRGB());
	}
}

// Save
ImageIO.write(tImage, "bmp", new File("spectrum2.bmp"));

