public class Vector {
    private double m;
    private double value;
    private double angle;
    private double x;
    private double y;
 
    public Vector(double m, double value) {
        this.m = m;
        this.value = value;
        this.angle = Math.toDegrees(Math.atan(this.m));
        this.x = this.value * Math.sin(Math.toRadians(this.angle));
        this.y = this.value * Math.cos(Math.toRadians(this.angle));
    }
 
    public Vector add(Vector vector) {
        double final_x = this.x + vector.x;
        double final_y = this.y + vector.y;
        double final_value = pytagoras(final_x, final_y);
        double final_m = final_y / final_x;
        return new Vector(final_m, final_value);
    }
 
    public Vector neg() {
        return new Vector(this.m, -this.value);
    }
 
    public Vector sub(Vector vector) {
        return this.add(vector.neg());
    }
 
    public Vector mul(double scalar) {
        return new Vector(this.m, this.value * scalar);
    }
 
    public Vector div(double scalar) {
        return this.mul(1 / scalar);
    }
 
    public String toString() {
        return "Vector:\n" +
                "    - Angular coefficient: " + this.m + "\n" +
                "    - Angle: " + this.angle + " degrees\n" +
                "    - Value: " + this.value + "\n" +
                "    - X component: " + this.x + "\n" +
                "    - Y component: " + this.y;
    }
 
    private double pytagoras(double x, double y) {
        return Math.sqrt(Math.pow(x, 2) + Math.pow(y, 2));
    }
}

import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.IOException;
import java.util.logging.Level;
import java.util.logging.Logger;
 
public class Benford {
 
    public static void main(String[] args) {
        if (args.length!= 1) {
            System.out.println("Usage: benford <file>");
            System.exit(1);
        }
 
        float[] actual = getActualDistribution(args[0]);
        float[] expected = benfordDistribution();
 
        System.out.println("digit\tactual\texpected");
        for (int i = 0; i < 9; i++) {
            System.out.printf("%d\t%.3f\t%.3f\n", i + 1, actual[i], expected[i]);
        }
    }
 
    private static float[] benfordDistribution() {
        float[] prob = new float[9];
        for (int i = 1; i < 10; i++) {
            prob[i - 1] = (float) (Math.log10(1 + 1.0 / i));
        }
 
        return prob;
    }
 
    private static float[] getActualDistribution(String fn) {
        File input = new File(fn);
        if (!input.exists()) {
            System.out.println("Can't open file");
            System.exit(1);
        }
 
        int[] tally = new int[9];
        int total = 0;
        try {
            BufferedReader reader = new BufferedReader(new FileReader(input));
            String line;
            while ((line = reader.readLine())!= null) {
                /* get the first nonzero digit on the current line */
                char c = line.charAt(0);
                while (c < '1' || c > '9') {
                    c = line.charAt(0);
                }
 
                tally[c - '1']++;
                total++;
            }
            reader.close();
        } catch (IOException ex) {
            Logger.getLogger(Benford.class.getName()).log(Level.SEVERE, null, ex);
        }
 
        float[] freq = new float[9];
        for (int i = 0; i < 9; i++) {
            freq[i] = tally[i] / (float) total;
        }
 
        return freq;
    }
}

public static long millis() { // Gets current time in milliseconds.
  return (new Date()).getTime();
}

/* Executes function 'func' n times, returns array of execution times. */
public static long[] benchmark(int n, Function func, Object[] args) {
  long[] times = new long[n];
  for (int i=0; i<n; i++) {
    long m = millis();
    func.apply(args);
    times[i] = millis() - m;
  }
  return times;
}

public class Main {
    private static final int ITERATIONS = 8;

    private static String neg(String sequence) {
        return sequence.chars()
               .map(ch -> (1 - Character.getNumericValue(ch)))
               .mapToObj(String::valueOf)
               .collect(Collectors.joining());
    }

    public static void main(String[] args) {
        String sequence = "0";
        for (int i = 0; i < ITERATIONS; i++) {
            System.out.println(String.format("%d: %s", i + 1, sequence));
            sequence = String.format("%s%s", sequence, neg(sequence));
        }
    }
}

