import java.util.function.Function;
 
class RecursiveFunc<T, R> {
    private final Function<RecursiveFunc<T, R>, Function<T, R>> p;
    RecursiveFunc(Function<RecursiveFunc<T, R>, Function<T, R>> p) {
        this.p = p;
    }
    Function<T, R> p(RecursiveFunc<T, R> r) {
        return p.apply(r);
    }
}
 
static <T, R> Function<T, R> y(Function<Function<T, R>, Function<T, R>> f) {
    RecursiveFunc<T, R> rec = new RecursiveFunc<>(r -> f.apply(t -> r.p(r).apply(t)));
    return rec.p(rec);
}
 
static Function<Integer, Integer> fac(Function<Integer, Integer> f) {
    return x -> x <= 1? 1 : x * f.apply(x - 1);
}
 
static Function<Integer, Integer> fib(Function<Integer, Integer> f) {
    return x -> x <= 2? 1 : f.apply(x - 1) + f.apply(x - 2);
}
 
public static void main(String[] args) {
    System.out.print("Factorial(1..10)   : ");
    for (int i = 1; i <= 10; i++) System.out.print(y(RecursiveFunc::fac).apply(i) + "  ");
    System.out.print("\nFibonacci(1..10)   : ");
    for (int i = 1; i <= 10; i++) System.out.print(y(RecursiveFunc::fib).apply(i) + "  ");
    System.out.println();
}

import java.io.*;
 
class Main {
    static final int MAX = 15;
 
    static int count_divisors(int n) {
        int i, count = 0;
        for (i = 1; i * i <= n; ++i) {
            if (!(n % i)) {
                if (i == n / i)
                    count++;
                else
                    count += 2;
            }
        }
        return count;
    }
 
    public static void main (String[] args) throws java.lang.Exception {
        int i, next = 1;
        System.out.printf("The first %d terms of the sequence are:\n", MAX);
        for (i = 1; next <= MAX; ++i) {
            if (next == count_divisors(i)) {           
                System.out.printf("%d ", i);
                next++;
            }
        }
        System.out.printf("\n");
    }
}

/*
 * Program seconds2string, C89 version.
 *
 * Read input from argv[1] or stdin, write output to stdout.
 */
 
import java.io.*;
import java.util.*;
 
/*
 * Converting the number of seconds in a human-readable string.
 * It is worth noting that direct output to stdout would be even simpler.
 */
public class seconds2string {
 
    public static String seconds2string(long seconds) {
        int i;
 
        final long s =  1;
        final long m = 60 * s;
        final long h = 60 * m;
        final long d = 24 * h;
        final long w =  7 * d;
 
        final long[] coeff = { w, d, h, m, s };
        final String[] units = { "wk", "d", "hr", "min", "sec" };
 
        String buffer = "";
 
        for ( i = 0; i < 5; i++ )
        {
            long value;
            value   = seconds / coeff[i];
            seconds = seconds % coeff[i];
            if ( value!= 0 )
            {
                if (!buffer.isEmpty() ) 
                    buffer += ", ";
                buffer += String.format("%d %s",value,units[i]);
            }
        }
 
        return buffer;
    }
 
    /*
     * Main function for seconds2string program.
     */
    public static void main(String[] args) {
        long seconds;
 
        if ( (args.length <  1) && (new Scanner(System.in)).hasNextLong() ) {
            seconds = (new Scanner(System.in)).nextLong();
        } else if ( args.length >= 1 ) {
            seconds = Long.parseLong(args[0]);
        } else {
            System.out.println("Usage: seconds2string <seconds>");
            System.exit(1);
        }
 
        System.out.println(seconds2string(seconds));
    }
}

import java.io.*;
import java.util.*;
import java.text.*;
import java.math.*;
import java.util.regex.*;

public class Solution {

    static String mid3(int n) {
        String buf = String.valueOf(Math.abs(n));
        int l = buf.length();
        if (l < 3 || (l & 1) == 0) return null;
        l = l / 2 - 1;
        return buf.substring(l, l + 3);
    }

    public static void main(String[] args) {
        int[] x = {123, 12345, 1234567, 987654321, 10001, -10001, -123, -100, 100, -12345, 1, 2, -1, -10, 2002, -2002, 0, 1234567890};
        String m;
        for (int i = 0; i < x.length; i++) {
            m = mid3(x[i]);
            if (m == null) m = "error";
            System.out.println(x[i] + ": " + m);
        }
    }
}

