import java.util.Stack;
 
class Expression {
 
    private String ex;
    private String op;
    private int prec;
 
    public Expression(String ex, String op, int prec) {
        this.ex = ex;
        this.op = op;
        this.prec = prec;
    }
 
    public Expression(String e1, String e2, String o) {
        this(e1 + " " + o + " " + e2, o, OPS.indexOf(o) / 2);
    }
 
    public Expression(String e) {
        this(e, "", 3);
    }
 
    @Override
    public String toString() {
        return ex;
    }
 
    public static final String OPS = "-+/*^";
}
 
public class PostfixToInfix {
 
    public static String postfixToInfix(String postfix) {
        Stack<Expression> expr = new Stack<>();
        String[] tokens = postfix.split("\\s+");
        for (String token : tokens) {
            int idx = Expression.OPS.indexOf(token);
            if (idx!= -1 && token.length() == 1) {
                Expression r = expr.pop();
                Expression l = expr.pop();
                int opPrec = idx / 2;
                if (l.prec < opPrec || (l.prec == opPrec && token.charAt(0) == '^')) {
                    l.ex = "(" + l.ex + ")";
                }
                if (r.prec < opPrec || (r.prec == opPrec && token.charAt(0)!= '^')) {
                    r.ex = "(" + r.ex + ")";
                }
                expr.push(new Expression(l.ex, r.ex, token));
            }
            else {
                expr.push(new Expression(token));
            }
            System.out.println(token + " -> " + expr);
        }
        return expr.peek().ex;
    }
 
    public static void main(String[] args) {
        String[] es = {
            "3 4 2 * 1 5 - 2 3 ^ ^ / +",
            "1 2 + 3 4 + ^ 5 6 + ^"
        };
        for (String e : es) {
            System.out.println("Postfix : " + e);
            System.out.println("Infix : " + postfixToInfix(e) + "\n");
        }
    }
}

