public class Foo {
  private static Object @@xyz = null;
  private String @name;
  private int @age;
  private Object @sex;
  private Object @bar;
  public Foo(String name, int age) {
    this.@name = name;
    this.@age = age;
  }
  public void add_sex(Object sex) {
    this.@sex = sex;
  }
  public static void main(String[] args) {
    Foo foo = new Foo("Angel", 18);
    System.out.println(foo.instance_variables());
    System.out.println(foo.instance_variable_defined("@age"));
    System.out.println(foo.instance_variable_get("@age"));
    System.out.println(foo.instance_variable_set("@age", 19));
    System.out.println(foo);
    foo.add_sex("woman");
    System.out.println(foo.instance_variables());
    System.out.println(foo);
    foo.instance_variable_set("@bar", null);
