import java.lang.Math;

public class AbundantOddNumbers {
	public static void main(String[] args) {
		int n, c;
		for (n = 1, c = 0; c < 25; n += 2) if (n < sum_proper_divisors(n)) System.out.println(++c + ": " + n);

		for ( ; c < 1000; n += 2) if (n < sum_proper_divisors(n)) c ++;
		System.out.println("\nThe one thousandth abundant odd number is: " + n);

		for (n = 1000000001 ;; n += 2) if (n < sum_proper_divisors(n)) break;
		System.out.println("The first abundant odd number above one billion is: " + n);
	}

	public static int sum_proper_divisors(int n) {
		int sum = 1;
		for (int i = 3, j; i < Math.sqrt(n)+1; i += 2) if (n % i == 0) sum += i + (i == (j = n / i)? 0 : j);
		return sum;
	}
}

