public static int[] leonardo(int n, int l0, int l1, int add) {
    int[] leo = new int[n];
    leo[0] = l0;
    leo[1] = l1;
    for (int i = 2; i < n; i++) leo[i] = leo[i - 1] + leo[i - 2] + add;
    return leo;
}
 
public static void main(String[] args) {
