public class Tokenize {
    private static final String SPE = "\ufffe";  // unused unicode char in Specials block
    private static final String SPF = "\uffff";  // ditto
 
    public static List<String> tokenize(String str, char sep, char esc) {
        String s = str.replace(esc + esc, SPE).replace(esc + sep, SPF);
        s = s.endsWith(esc)? s.substring(0, s.length() - 1).replace(esc, "") + esc : s.replace(esc, "");
        return Arrays.asList(s.split(sep)).stream().map(item -> item.replace(SPE, esc).replace(SPF, sep)).collect(Collectors.toList());
    }
 
    public static void main(String[] args) {
        String str = "one^|uno||three^^^^|four^^^|^cuatro|";
        char sep = '|';
        char esc = '^';
        List<String> items = tokenize(str, sep, esc);
        for (String item : items) System.out.println(item.isEmpty()? "(empty)" : item);
    }
}

