public class Mandelbrot {
    public static void main(String[] args) {
        double y = 1.0;
        while (y >= -1) {
            double x = -2.0;
            while (x <= 0.5) {
                System.out.print(mandelbrot(x, y) < 2? "*" : " ");
                x += 0.0315;
            }
            System.out.println();
            y -= 0.05;
        }
    }

    private static double mandelbrot(double x, double y) {
        return Stream.generate(() -> 0.0)
               .limit(50)
               .reduce(0.0, (z, c) -> z * z + Math.sqrt(x * x + y * y));
    }
}

