import java.util.ArrayList;
import java.util.List;
 
class Factorial {
	public static long factorial(int n) {
		if (n > 1)
			return n * factorial(n - 1);
		return 1;
	}
}
 
class SumOfFactorials {
	public static long sumOfFactorials(int num, int... args) {
		long sum = 0;
		for (int i = 0; i < num; i++)
			sum += Factorial.factorial(args[i]);
		return sum;
	}
}
 
class Main {
	public static void main(String[] args) {
		System.out.println("\nSum of factorials of [1,5] : " + SumOfFactorials.sumOfFactorials(5, 1, 2, 3, 4, 5));
		System.out.println("\nSum of factorials of [3,5] : " + SumOfFactorials.sumOfFactorials(3, 3, 4, 5));
		System.out.println("\nSum of factorials of [1,3] : " + SumOfFactorials.sumOfFactorials(3, 1, 2, 3));
	}
}

import java.util.ArrayList;
