import java.util.stream.IntStream;
 
public class AnyNacci {
 
    public static void main(String[] args) {
        List<List<Integer>> naccis = new ArrayList<>();
        naccis.add(Arrays.asList(2, 1));
        naccis.add(Arrays.asList(1, 1));
        naccis.add(Arrays.asList(1, 1, 2));
        naccis.add(Arrays.asList(1, 1, 2, 4));
        naccis.add(Arrays.asList(1, 1, 2, 4, 8));
        naccis.add(Arrays.asList(1, 1, 2, 4, 8, 16));
        naccis.add(Arrays.asList(1, 1, 2, 4, 8, 16, 32));
        naccis.add(Arrays.asList(1, 1, 2, 4, 8, 16, 32, 64));
        naccis.add(Arrays.asList(1, 1, 2, 4, 8, 16, 32, 64, 128));
        naccis.add(Arrays.asList(1, 1, 2, 4, 8, 16, 32, 64, 128, 256));
 
        naccis.forEach(seq -> {
            System.out.println(anynacci(seq, 15));
        });
    }
 
    public static List<Integer> anynacci(List<Integer> startSequence, int count) {
        int n = startSequence.size();
        List<Integer> result = new ArrayList<>(startSequence);
        IntStream.range(0, count - n).forEach(i -> {
            result.add(result.stream().skip(result.size() - n).mapToInt(Integer::intValue).sum());
        });
        return result;
    }
}

