import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
 
public class License {
 
    private static final int INOUT_LEN = 4;
    private static final int TIME_LEN = 20;
    private static final int MAX_MAXOUT = 1000;
 
    private static String inout;
    private static String time;
    private static int jobnum;
 
    private static String[] maxtime = new String[MAX_MAXOUT];
 
    public static void main(String[] args) throws IOException {
        BufferedReader in = null;
        int l_out = 0, maxout = -1, maxcount = 0;
 
        if (args.length > 0) {
            in = new BufferedReader(new FileReader(args[0]));
        } else {
            in = new BufferedReader(new InputStreamReader(System.in));
        }
 
        Pattern pattern = Pattern.compile("License (\\w{3}) @ (\\d{2}:\\d{2}:\\d{2}) for job (\\d+)");
 
        while (true) {
            String line = in.readLine();
            if (line == null) {
                break;
            }
 
            Matcher matcher = pattern.matcher(line);
            if (matcher.matches()) {
                inout = matcher.group(1);
                time = matcher.group(2);
                jobnum = Integer.parseInt(matcher.group(3));
 
                if (inout.equals("OUT")) {
                    l_out++;
                } else {
                    l_out--;
                }
 
                if (l_out > maxout) {
                    maxout = l_out;
                    maxcount = 0;
                    maxtime[0] = "";
                }
                if (l_out == maxout) {
                    if (maxcount < MAX_MAXOUT) {
                        maxtime[maxcount] = time;
                        maxcount++;
                    } else {
                        System.err.println("increase MAX_MAXOUT (now it is " + MAX_MAXOUT + ")");
                        System.exit(1);
                    }
                }
            }
        }
 
        System.out.println("Maximum simultaneous license use is " + maxout + " at the following times:");
        for (l_out = 0; l_out < maxcount; l_out++) {
            System.out.println(maxtime[l_out]);
        }
 
        if (in!= System.in) {
            in.close();
        }
        System.exit(0);
    }
}

public class QMean {
	public static double qmean(int[] num) {
		double sum = 0;
		for (int n : num) {
			sum += n * n;
		}
		return Math.sqrt(sum / num.length);
	}
}

