import java.util.Random;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
 
public class Main {
    private static final int bucket_count = 15;
    private static final int[] buckets = new int[bucket_count];
    private static final Lock[] bucket_mutex = new Lock[bucket_count];
 
    public static void main(String[] args) {
        Random random = new Random();
        for (int i = 0; i < bucket_count; i++) {
            buckets[i] = random.nextInt(100);
            bucket_mutex[i] = new ReentrantLock();
        }
        print_buckets();
 
        Thread t_eq = new Thread(new Equalizer());
        Thread t_rd = new Thread(new Randomizer());
        t_eq.start();
        t_rd.start();
 
        while (true) {
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
            for (Lock mutex : bucket_mutex) {
                mutex.lock();
            }
            print_buckets();
            for (Lock mutex : bucket_mutex) {
                mutex.unlock();
            }
        }
    }
 
    private static void print_buckets() {
        int total = 0;
        for (int bucket : buckets) {
            total += bucket;
            System.out.printf("%3d ", bucket);
        }
        System.out.printf("= %3d\n", total);
    }
 
    private static class Equalizer implements Runnable {
        @Override
        public void run() {
            Random random = new Random();
            while (true) {
                int from = random.nextInt(bucket_count);
                int to = random.nextInt(bucket_count);
                if (from!= to) {
                    int min = Math.min(from, to);
                    int max = Math.max(from, to);
                    bucket_mutex[min].lock();
                    bucket_mutex[max].lock();
                    int diff = buckets[from] - buckets[to];
                    int amount = Math.abs(diff / 2);
                    if (diff < 0) {
                        int temp = from;
                        from = to;
                        to = temp;
                    }
                    buckets[from] -= amount;
                    buckets[to] += amount;
                    bucket_mutex[min].unlock();
                    bucket_mutex[max].unlock();
                }
            }
        }
    }
 
    private static class Randomizer implements Runnable {
        @Override
        public void run() {
            Random random = new Random();
            while (true) {
                int from = random.nextInt(bucket_count);
                int to = random.nextInt(bucket_count);
                if (from!= to) {
                    int min = Math.min(from, to);
                    int max = Math.max(from, to);
                    bucket_mutex[min].lock();
                    bucket_mutex[max].lock();
                    int amount = random.nextInt(buckets[from] + 1);
                    buckets[from] -= amount;
                    buckets[to] += amount;
                    bucket_mutex[min].unlock();
                    bucket_mutex[max].unlock();
                }
            }
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Timer;
import java.util.TimerTask;
 
public class SleepSort {
 
    public static void main(String[] args) {
        int[] x = {3,2,4,7,3,6,9,1};
        if (sleepsort(x).equals(sorted(x))) {
            System.out.println("sleep sort worked for: " + x);
        } else {
            System.out.println("sleep sort FAILED for: " + x);
        }
    }
 
    public static List<Integer> sleepsort(int[] values) {
        List<Integer> result = new ArrayList<Integer>();
        int mx = values[0];
        for (int v : values) {
            if (mx < v) mx = v;
            Timer timer = new Timer();
            timer.schedule(new Add1(v, result), v);
        }
        try {
            Thread.sleep(mx+1);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        return result;
    }
 
    public static List<Integer> sorted(int[] values) {
        List<Integer> result = new ArrayList<Integer>();
        for (int v : values) {
            result.add(v);
        }
        java.util.Collections.sort(result);
        return result;
    }
 
    private static class Add1 extends TimerTask {
        private int v;
        private List<Integer> result;
 
        public Add1(int v, List<Integer> result) {
            this.v = v;
            this.result = result;
        }
 
        @Override
        public void run() {
            result.add(v);
        }
    }
}

import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class RepString {
    public static void main(String[] args) {
        String[] strings = {
                "1001110011",
                "1110111011",
                "0010010010",
                "1010101010",
                "1111111111",
                "0100101101",
                "0100100",
                "101",
                "11",
                "00",
                "1",
        };
        for (String string : strings) {
            String repString = repString(string);
            if (repString!= null) {
                System.out.printf("Longuest rep-string for '%s' is '%s' (%d chars)%n", string, repString, repString.length());
            } else {
                System.out.printf("No rep-string found for '%s'%n", string);
            }
        }
    }
 
    public static String repString(String string) {
        int index = string.length() / 2;
 
        for (int splitIndex = index; splitIndex > 0; splitIndex--) {
            boolean isRepString = true;
            String first = string.substring(0, splitIndex);
            String last = string.substring(splitIndex);
 
            String[] inter = last.split("(?<=\\G.{" + splitIndex + "})");
            for (int i = 0; i < inter.length - 1; i++) {
                if (!first.equals(inter[i])) {
                    isRepString = false;
                    break;
                }
            }
            String rmnd = inter[inter.length - 1];
 
            // Check that the remainder starts with the rep-string
            if (!first.startsWith(rmnd)) {
                isRepString = false;
            }
 
            if (isRepString) {
                return first;
            }
        }
        return null;
    }
 
    public static void testRepString() {
        Map<String, String> results = new HashMap<>();
        results.put("1001110011", "10011");
        results.put("1110111011", "1110");
        results.put("0010010010", "001");
        results.put("1010101010", "1010");
        results.put("1111111111", "11111");
        results.put("0100101101", null);
        results.put("0100100", "010");
        results.put("101", null);
        results.put("11", "1");
        results.put("00", "0");
        results.put("1", null);
 
        for (Map.Entry<String, String> entry : results.entrySet()) {
            String expected = entry.getValue();
            String actual = repString(entry.getKey());
            if (expected == null) {
                assert actual == null;
            } else {
                assert expected.equals(actual);
            }
        }
    }
}

