class Card {
    private int face;
    private char suit;
 
    public Card(int face, char suit) {
        this.face = face;
        this.suit = suit;
    }
 
    public int getFace() {
        return face;
    }
 
    public char getSuit() {
        return suit;
    }
}
 
public class PokerHands {
    private static final String FACES = "23456789tjqka";
    private static final String SUITS = "shdc";
 
    private static boolean isStraight(List<Card> cards) {
        List<Card> sorted = cards.stream().sorted(Comparator.comparingInt(Card::getFace)).collect(Collectors.toList());
        if (sorted.get(0).getFace() + 4 == sorted.get(4).getFace()) return true;
        if (sorted.get(4).getFace() == 14 && sorted.get(0).getFace() == 2 && sorted.get(3).getFace() == 5) return true;
        return false;
    }
 
    private static boolean isFlush(List<Card> cards) {
        char suit = cards.get(0).getSuit();
        if (cards.subList(1, 5).stream().allMatch(c -> c.getSuit() == suit)) return true;
        return false;
    }
 
    private static String analyzeHand(String hand) {
        String h = hand.toLowerCase();
        List<String> split = Arrays.stream(h.split(" ")).filter(s ->!s.equals("")).distinct().collect(Collectors.toList());
        if (split.size()!= 5) return "invalid";
        List<Card> cards = new ArrayList<>();
 
        for (String s : split) {
            if (s.length()!= 2) return "invalid";
            int fIndex = FACES.indexOf(s.charAt(0));
            if (fIndex == -1) return "invalid";
            int sIndex = SUITS.indexOf(s.charAt(1));
            if (sIndex == -1) return "invalid";
            cards.add(new Card(fIndex + 2, s.charAt(1)));
        }
 
        Map<Integer, List<Card>> groups = cards.stream().collect(Collectors.groupingBy(Card::getFace));
        switch (groups.size()) {
            case 2:
                if (groups.values().stream().anyMatch(l -> l.size() == 4)) return "four-of-a-kind";
                return "full-house";
            case 3:
                if (groups.values().stream().anyMatch(l -> l.size() == 3)) return "three-of-a-kind";
                return "two-pair";
            case 4:
                return "one-pair";
            default:
                boolean flush = isFlush(cards);
                boolean straight = isStraight(cards);
                if (flush && straight) return "straight-flush";
                if (flush) return "flush";
                if (straight) return "straight";
                return "high-card";
        }
    }
 
    public static void main(String[] args) {
        String[] hands = {
            "2h 2d 2c kc qd",
            "2h 5h 7d 8c 9s",
            "ah 2d 3c 4c 5d",
            "2h 3h 2d 3c 3d",
            "2h 7h 2d 3c 3d",
            "2h 7h 7d 7c 7s",
            "th jh qh kh ah",
            "4h 4s ks 5d ts",
            "qc tc 7c 6c 4c",
            "ah ah 7c 6c 4c"
        };
        for (String hand : hands) {
            System.out.println(hand + ": " + analyzeHand(hand));
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws IOException {
        int tokens = 12;
        Scanner scanner = new Scanner(System.in);
        while (true) {
            showTokens(tokens);
            System.out.print("  How many tokens 1, 2 or 3? ");
            String input = scanner.nextLine();
            int t = Integer.parseInt(input);
            if (t < 1 || t > 3) {
                System.out.println("\nMust be a number between 1 and 3, try again.\n");
            } else {
                int ct = 4 - t;
                String s = "s";
                if (ct == 1) {
                    s = "";
                }
                System.out.print("  Computer takes " + ct + " token" + s + "\n\n");
                tokens -= 4;
            }
            if (tokens == 0) {
                showTokens(0);
                System.out.println("  Computer wins!");
                return;
            }
        }
    }

    private static void showTokens(int tokens) {
        System.out.println("Tokens remaining " + tokens + "\n");
    }
}

