import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class PythagoreanTriples {

    public static void main(String[] args) {
        int n = 100;
        List<List<Integer>> triples = new ArrayList<>();
        for (int x : r(1, n)) {
            for (int y : r(1 + x, n)) {
                for (int z : r(1 + y, n)) {
                    if (x * x + y * y == z * z) {
                        triples.add(List.of(x, y, z));
                    }
                }
            }
        }
        System.out.println(triples);
    }

    private static List<Integer> r(int m, int n) {
        return IntStream.range(m, n + 1).boxed().collect(Collectors.toList());
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;
 
public class Wrap {
 
    public static String wrap(String text, int lineWidth) {
        List<String> words = new ArrayList<String>();
        StringTokenizer tokenizer = new StringTokenizer(text);
        while (tokenizer.hasMoreTokens()) {
            words.add(tokenizer.nextToken());
        }
        if (words.size() == 0) {
            return "";
        }
        String wrapped = words.get(0);
        int spaceLeft = lineWidth - wrapped.length();
        for (int i = 1; i < words.size(); i++) {
            String word = words.get(i);
            if (word.length() + 1 > spaceLeft) {
                wrapped += "\n" + word;
                spaceLeft = lineWidth - word.length();
            } else {
                wrapped += " " + word;
                spaceLeft -= 1 + word.length();
            }
        }
        return wrapped;
    }
 
    private static final String FROG = "In olden times when wishing still helped one, there lived a king\n" +
            "whose daughters were all beautiful, but the youngest was so beautiful\n" +
            "that the sun itself, which has seen so much, was astonished whenever\n" +
            "it shone in her face.  Close by the king's castle lay a great dark\n" +
            "forest, and under an old lime-tree in the forest was a well, and when\n" +
            "the day was very warm, the king's child went out into the forest and\n" +
            "sat down by the side of the cool fountain, and when she was bored she\n" +
            "took a golden ball, and threw it up on high and caught it, and this\n" +
            "ball was her favorite plaything.";
 
    public static void main(String[] args) {
        System.out.println("wrapped at 80:");
        System.out.println(wrap(FROG, 80));
        System.out.println("wrapped at 72:");
        System.out.println(wrap(FROG, 72));
    }
}

import java.util.HashMap;
import java.util.List;
import java.util.ArrayList;
import java.util.stream.Collectors;
 
public class MatrixChainMultiplication {
 
    public static void main(String[] args) {
        System.out.println(mcmDisplay(List.of(5, 6, 3, 1)));
        System.out.println(mcmDisplay(List.of(1, 5, 25, 30, 100, 70, 2, 1, 100, 250, 1, 1000, 2)));
        System.out.println(mcmDisplay(List.of(1000, 1, 500, 12, 1, 700, 2500, 3, 2, 5, 14, 10)));
    }
 
    public static String mcmDisplay(List<Integer> dims) {
        HashMap<List<Integer>, Pair<Integer, List<Integer>>> costs = new HashMap<>();
        String line = String.format("Dims : %s\n", dims);
        Pair<Integer, List<Integer>> ans = mcm(dims, costs);
        List<String> mats = new ArrayList<>();
        for (int i = 1; i <= ans.getSecond().size() + 1; i++) {
            mats.add(Integer.toString(i));
        }
        for (int i = 0; i < ans.getSecond().size(); i++) {
            String matTaken = mats.get(ans.getSecond().get(i));
            mats.remove(ans.getSecond().get(i));
            mats.add(ans.getSecond().get(i), String.format("(%s*%s)", matTaken, mats.get(ans.getSecond().get(i))));
        }
        line += String.format("Order: %s\n", mats.get(0));
        line += String.format("Cost : %d", ans.getFirst());
        return line;
    }
 
    public static Pair<Integer, List<Integer>> mcm(List<Integer> dims, HashMap<List<Integer>, Pair<Integer, List<Integer>>> costs) {
        if (costs.containsKey(dims)) {
            return costs.get(dims);
        }
        Pair<Integer, List<Integer>> ans;
        if (dims.size() == 3) {
            ans = new Pair<>(dims.get(0) * dims.get(1) * dims.get(2), List.of(0));
        } else {
            int minCost = Integer.MAX_VALUE;
            List<Integer> minPath = new ArrayList<>();
            for (int i = 1; i < dims.size() - 1; i++) {
                List<Integer> taken = dims.subList(i - 1, i + 2);
                List<Integer> rest = new ArrayList<>(dims.subList(0, i));
                rest.addAll(dims.subList(i + 1, dims.size()));
                Pair<Integer, List<Integer>> a1 = mcm(taken, costs);
                Pair<Integer, List<Integer>> a2 = mcm(rest, costs);
                if (a1.getFirst() + a2.getFirst() < minCost) {
                    minCost = a1.getFirst() + a2.getFirst();
                    minPath = List.of(i - 1);
                    minPath.addAll(a2.getSecond());
                }
            }
            ans = new Pair<>(minCost, minPath);
        }
        costs.put(dims, ans);
        return ans;
    }
 
    public static class Pair<T, U> {
        private T first;
        private U second;
 
        public Pair(T first, U second) {
            this.first = first;
            this.second = second;
        }
 
        public T getFirst() {
            return first;
        }
 
        public U getSecond() {
            return second;
        }
    }
}

public class Foo {
    // implementation of an instance method for struct Foo
    // returning the answer to life
    public int getTheAnswerToLife() {
        return 42;
    }
 
    // implementation of a static method for struct Foo
    // returning a new instance object
    public static Foo new() {
        System.out.println("Hello, world!");
        return new Foo(); // returning the new Foo object
    }
}
 
public class Main {
    public static void main(String[] args) {
        // create the instance object foo,
        // by calling the static method new of struct Foo
        Foo foo = Foo.new();
 
        // get the answer to life 
        // by calling the instance method of object foo
        System.out.println("The answer to life is " + foo.getTheAnswerToLife() + ".");
 
        // Note that in Rust, methods still work on references to the object.
        // Rust will automatically do the appropriate dereferencing to get the method to work:
        Foo lotsOfReferences = foo;
        System.out.println("The answer to life is still " + lotsOfReferences.getTheAnswerToLife() + ".");
    }
}

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
 
public class Ripemd160 {
 
    public static String ripemd160(String text) {
        try {
            MessageDigest md = MessageDigest.getInstance("RIPEMD160");
            md.update(text.getBytes());
            byte[] digest = md.digest();
            return bytesToHex(digest);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
 
    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
 
    public static void main(String[] args) {
        System.out.println(ripemd160("Rosetta Code"));
    }
}

import java.io.BufferedReader;
import java.io.FileNotFoundException;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
 
public class FastaEntry {
    public String Name;
    public StringBuilder Sequence;
}
 
public class FastaParser {
    public static List<FastaEntry> ParseFasta(BufferedReader fastaFile) throws IOException {
        FastaEntry f = null;
        String line;
        List<FastaEntry> entries = new ArrayList<FastaEntry>();
        while ((line = fastaFile.readLine())!= null) {
            // ignore comment lines
            if (line.startsWith(";"))
                continue;
 
            if (line.startsWith(">")) {
                if (f!= null)
                    entries.add(f);
                f = new FastaEntry();
                f.Name = line.substring(1);
                f.Sequence = new StringBuilder();
            } else if (f!= null)
                f.Sequence.append(line);
        }
        entries.add(f);
        return entries;
    }
 
    public static void main(String[] args) {
        try {
            BufferedReader fastaFile = new BufferedReader(new FileReader("fasta.txt"));
            List<FastaEntry> entries = ParseFasta(fastaFile);
            for (FastaEntry f : entries)
                System.out.println(f.Name + ": " + f.Sequence);
        } catch (FileNotFoundException e) {
            System.out.println(e);
        } catch (IOException e) {
            System.out.println(e);
        }
    }
}

