import java.util.function.Function;
import java.util.stream.IntStream;
 
public class Main {
    public static void main(String[] args) {
        System.out.println(harmonicSum(1, 100, i -> 1.0 / i));
    }
 
    public static double harmonicSum(int lo, int hi, Function<Double, Double> term) {
        return IntStream.rangeClosed(lo, hi)
               .mapToDouble(i -> term.apply((double) i))
               .sum();
    }
}

