import java.math.BigInteger;
 
public class Combinatorics {
 
    public static BigInteger perm(int n, int k) {
        if (n <= 0 || k < 0) throw new IllegalArgumentException();
        BigInteger p = BigInteger.ONE;
        for (int i = n - k + 1; i <= n; i++) p = p.multiply(BigInteger.valueOf(i));
        return p;
    }
 
    public static BigInteger comb(int n, int k) {
        if (n <= 0 || k < 0) throw new IllegalArgumentException();
        BigInteger c = BigInteger.ONE;
        for (int i = 2; i <= k; i++) c = c.multiply(BigInteger.valueOf(i));
        return perm(n, k).divide(c);
    }
 
    public static void main(String[] args) {    
        System.out.println("A sample of permutations from 1 to 12:");    
        for (int n = 1; n <= 12; n++) System.out.printf("%2d P %-2d = %d\n", n, n / 3, perm(n, n / 3));
 
        System.out.println("\nA sample of combinations from 10 to 60:");
        for (int n = 10; n <= 60; n += 10) System.out.printf("%2d C %-2d = %d\n", n, n / 3, comb(n, n / 3));
 
        System.out.println("\nA sample of permutations from 5 to 15000:");
        int[] na = {5, 50, 500, 1000, 5000, 15000};    
        for (int n : na) {
            int k = n / 3;
            String s = perm(n, k).toString();
            int l = s.length();
            String e = (l <= 40)? "" : "... (" + (l - 40) + " more digits)";
            System.out.printf("%5d P %-4d = %s%s\n", n, k, s.substring(0, 40), e);
        }
 
        System.out.println("\nA sample of combinations from 100 to 1000:");   
        for (int n = 100; n <= 1000; n += 100) {
            int k = n / 3;
            String s = comb(n, k).toString();
            int l = s.length();
            String e = (l <= 40)? "" : "... (" + (l - 40) + " more digits)";
            System.out.printf("%4d C %-3d = %s%s\n", n, k, s.substring(0, 40), e);
        }
    }
}

