import java.util.HashSet;
import java.util.Iterator;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Stream;
 
public class YellowstoneSequence {
    public static void main(String[] args) {
        System.out.println("First 30 Yellowstone numbers:");
        for (int y : yellowstoneSequence().limit(30).toArray()) {
            System.out.print(y + " ");
        }
        System.out.println();
    }
 
    public static Stream<Integer> yellowstoneSequence() {
        Set<Integer> sequence = new HashSet<>();
        int min = 1;
        int n = 0;
        int n1 = 0;
        int n2 = 0;
        return Stream.iterate(0, new Function<Integer, Integer>() {
            @Override
            public Integer apply(Integer i) {
                n2 = n1;
                n1 = n;
                if (n < 3) {
                    n += 1;
                } else {
                    n = min;
                    while (!(!sequence.contains(n) && gcd(n1, n) == 1 && gcd(n2, n) > 1)) {
                        n += 1;
                    }
                }
                sequence.add(n);
                while (sequence.contains(min)) {
                    sequence.remove(min);
                    min += 1;
                }
                return n;
            }
        });
    }
 
    public static int gcd(int a, int b) {
        if (b == 0) {
            return a;
        } else {
            return gcd(b, a % b);
        }
    }
}

import java.lang.Math;
 
public class LongYears {
 
	public static int p(int year) {
		return (int)((double)year + Math.floor(year/4) - Math.floor(year/100) + Math.floor(year/400)) % 7;
	}
 
	public static boolean is_long_year(int year) {
		return p(year) == 4 || p(year - 1) == 3;
	}
 
	public static void print_long_years(int from, int to) {
		for (int year = from; year <= to; ++year) {
			if (is_long_year(year)) {
				System.out.printf("%d ", year);
			}
		}
	}
 
	public static void main(String[] args) {
		System.out.println("Long (53 week) years between 1800 and 2100\n");
		print_long_years(1800, 2100);
		System.out.println();
	}
}

import java.lang.Math;
 
public class MathTest {
 
    public static void main(String[] args) {
        double radians = Math.PI / 4;
        double degrees = 45.0;
 
        double deg2rad(double d) {
            return d * Math.PI / 180;
        }
 
        double rad2deg(double r) {
            return r * 180 / Math.PI;
        }
 
        //sine
        System.out.println(Math.sin(radians) + " " + Math.sin(deg2rad(degrees)));
        //cosine
        System.out.println(Math.cos(radians) + " " + Math.cos(deg2rad(degrees)));
        //tangent
        System.out.println(Math.tan(radians) + " " + Math.tan(deg2rad(degrees)));
        //arcsine
        double arcsin = Math.asin(Math.sin(radians));
        System.out.println(arcsin + " " + rad2deg(arcsin));
        //arccosine
        double arccos = Math.acos(Math.cos(radians));
        System.out.println(arccos + " " + rad2deg(arccos));
        //arctangent
        double arctan = Math.atan(Math.tan(radians));
        System.out.println(arctan + " " + rad2deg(arctan));
    }
}

