import java.io.*;
import java.util.*;
 
public class Main {
 
    public static int countDivisors(int n) {
        int count = 0;
        int i = 1;
        int k = 2;
        if (n % 2 == 0) {
            k = 1;
        }
        while (i * i <= n) {
            if (n % i == 0) {
                count++;
                int j = n / i;
                if (j!= i) {
                    count++;
                }
            }
            i += k;
        }
        return count;
    }
 
    public static void main(String[] args) {
        System.out.println("The first 100 tau numbers are:");
        int count = 0;
        int i = 1;
        while (count < 100) {
            int tf = countDivisors(i);
            if (i % tf == 0) {
                System.out.printf("%4d  ", i);
                count++;
                if (count % 10 == 0) {
                    System.out.println();
                }
            }
            i++;
        }
    }
}

