public class PascalsTriangle {
 
    public static void createTriangle(int n) {
        if (n > 0) {
            for (int i = 0; i < n; i++) {
                int c = 1;
                System.out.print(" ".repeat(2 * (n - 1 - i)));
                for (int k = 0; k <= i; k++) {
                    System.out.print(String.format("%3d", c));
                    c = c * (i - k) / (k + 1);
                }
                System.out.println();
            }
        }
    }
 
    public static void main(String[] args) {
        createTriangle(8);
    }
}

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
import static java.lang.Math.atan2;
import static java.lang.Math.PI;
import static java.lang.Math.pow;
import static java.lang.Math.round;
import static java.lang.Math.sqrt;
 
public class HSV {
 
    public static void main(String[] args) throws IOException {
        BufferedImage im = new BufferedImage(300, 300, BufferedImage.TYPE_INT_RGB);
        double radius = Math.min(im.getWidth(), im.getHeight()) / 2.0;
        int cx = im.getWidth() / 2, cy = im.getHeight() / 2;
 
        for (int x = 0; x < im.getWidth(); x++) {
            for (int y = 0; y < im.getHeight(); y++) {
                int rx = x - cx;
                int ry = y - cy;
                double s = sqrt(pow(rx, 2.0) + pow(ry, 2.0)) / radius;
                if (s <= 1.0) {
                    double h = ((atan2(ry, rx) / PI) + 1.0) / 2.0;
                    Color rgb = Color.getHSBColor((float) h, (float) s, 1.0f);
                    im.setRGB(x, y, rgb.getRGB());
                }
            }
        }
 
        ImageIO.write(im, "png", new File("hsv.png"));
    }
}

