import java.util.ArrayList;
import java.util.List;
import java.lang.Math;
 
public class Factor {
 
    public static void main(String[] args) {
        assert(factor(100).equals(new int[]{1, 2, 4, 5, 10, 10, 20, 25, 50, 100}));
        assert(factor(101).equals(new int[]{1, 101}));
    }
 
    public static int[] factor(int num) {
        List<Integer> factors = new ArrayList<Integer>(); // creates a new list for the factors of the number
 
        for (int i = 1; i <= Math.sqrt(num); i++) {
            if (num % i == 0) {
                factors.add(i); // adds smallest factor to factors
                factors.add(num/i); // adds largest factor to factors
            }
        }
        int[] factorsArray = new int[factors.size()]; // creates a new array for the factors of the number
        for (int i = 0; i < factors.size(); i++) {
            factorsArray[i] = factors.get(i); // adds the factors to the array
        }
        return factorsArray; // returns the factors
    }
}

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Formatter;
 
public class Sha1 {
 
    public static void main(String[] args) {
        String myphrase = "Rosetta Code";
        try {
            MessageDigest sha1 = MessageDigest.getInstance("SHA-1");
            sha1.update(myphrase.getBytes());
            byte[] digest = sha1.digest();
            System.out.println(myphrase + " as a sha1 digest : " + toHex(digest) + " !");
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }
 
    public static String toHex(byte[] bytes) {
        Formatter formatter = new Formatter();
        for (byte b : bytes) {
            formatter.format("%02x", b);
        }
        return formatter.toString();
    }
}

import java.util.Arrays;
 
public class StirlingNumbers {
    private static class StirlingCache {
        private int max;
        private int[] values;
    }
 
    private static int stirlingNumber2(StirlingCache sc, int n, int k) {
        if (k == n)
            return 1;
        if (k == 0 || k > n || n > sc.max)
            return 0;
        return sc.values[n*(n-1)/2 + k - 1];
    }
 
    private static boolean stirlingCacheCreate(StirlingCache sc, int max) {
        int[] values = new int[max * (max + 1)/2];
        if (values == null)
            return false;
        sc.max = max;
        sc.values = values;
        for (int n = 1; n <= max; ++n) {
            for (int k = 1; k < n; ++k) {
                int s1 = stirlingNumber2(sc, n - 1, k - 1);
                int s2 = stirlingNumber2(sc, n - 1, k);
                values[n*(n-1)/2 + k - 1] = s1 + s2 * k;
            }
        }
        return true;
    }
 
    private static void stirlingCacheDestroy(StirlingCache sc) {
        sc.values = null;
    }
 
    private static void printStirlingNumbers(StirlingCache sc, int max) {
        System.out.print("Stirling numbers of the second kind:\nn/k");
        for (int k = 0; k <= max; ++k)
            System.out.printf(k == 0? "%2d" : "%8d", k);
        System.out.println();
        for (int n = 0; n <= max; ++n) {
            System.out.printf("%2d ", n);
            for (int k = 0; k <= n; ++k)
                System.out.printf(k == 0? "%2d" : "%8d", stirlingNumber2(sc, n, k));
            System.out.println();
        }
    }
 
    public static void main(String[] args) {
        StirlingCache sc = new StirlingCache();
        final int max = 12;
        if (!stirlingCacheCreate(sc, max)) {
            System.err.println("Out of memory");
            return;
        }
        printStirlingNumbers(sc, max);
        stirlingCacheDestroy(sc);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;
import java.util.stream.Stream;
 
public class SmarandachePrimeDigitalSequence {
 
    private static boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n % 2 == 0) {
            return n == 2;
        }
        if (n % 3 == 0) {
            return n == 3;
        }
        if (n % 5 == 0) {
            return n == 5;
        }
        int p = 7;
        int[] wheel = {4, 2, 4, 2, 4, 6, 2, 6};
        while (true) {
            for (int w : wheel) {
                if (p * p > n) {
                    return true;
                }
                if (n % p == 0) {
                    return false;
                }
                p += w;
            }
        }
    }
 
    private static int nextPrimeDigitNumber(int n) {
        if (n == 0) {
            return 2;
        }
        switch (n % 10) {
            case 2:
                return n + 1;
            case 3:
            case 5:
                return n + 2;
            default:
                return 2 + nextPrimeDigitNumber(n / 10) * 10;
        }
    }
 
    private static Stream<Integer> smarandachePrimeDigitalSequence() {
        return Stream.iterate(0, n -> nextPrimeDigitNumber(n))
               .filter(SmarandachePrimeDigitalSequence::isPrime);
    }
 
    public static void main(String[] args) {
        int limit = 1000000000;
        List<Integer> seq = smarandachePrimeDigitalSequence().limit(limit).collect(ArrayList::new, List::add, List::addAll);
        System.out.println("First 25 SPDS primes:");
        for (int i = 0; i < 25; i++) {
            System.out.print(seq.get(i) + " ");
        }
        System.out.println();
        System.out.println("100th SPDS prime: " + seq.get(99));
        System.out.println("1000th SPDS prime: " + seq.get(999));
        System.out.println("10,000th SPDS prime: " + seq.get(9999));
        System.out.println("Largest SPDS prime less than " + limit + ": " + seq.get(seq.size() - 1));
    }
}

// version 1.1.2
 
public static double horner(double[] coeffs, double x) {
    double sum = 0.0;
    for (int i = coeffs.length - 1; i >= 0; i--) sum = sum * x + coeffs[i];
    return sum;
}
 
public static void main(String[] args) {
    double[] coeffs = new double[]{-19.0, 7.0, -4.0, 6.0};
    System.out.println(horner(coeffs, 3.0));
}

import java.util.HashMap;
import java.util.Map;

public class HofstadterQ {
    public static void main(String[] args) {
        HofstadterQ hofstadterQ = new HofstadterQ();
        for (int i = 1; i <= 10; i++) {
            System.out.println("Q(" + i + ") = " + hofstadterQ.Q(i));
        }
        System.out.println("Q(1000) = " + hofstadterQ.Q(1000));
    }

    private Map<Integer, Integer> memo = new HashMap<>();

    public HofstadterQ() {
        memo.put(1, 1);
        memo.put(2, 1);
        memo.put(3, 1);
    }

    public int Q(int n) {
        Integer result = memo.get(n);
        if (result == null) {
            result = Q(n - Q(n - 1)) + Q(n - Q(n - 2));
            memo.put(n, result);
        }
        return result;
    }
}

