import java.util.Vector;
import java.util.Collections;
import java.util.Arrays;
import java.util.List;
import java.util.ArrayList;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class Main {
 
    public static List<Integer> findProperDivisors(int n) {
        List<Integer> divisors = new ArrayList<>();
        for (int i = 1; i < n / 2 + 1; i++) {
            if (n % i == 0) {
                divisors.add(i);
            }
        }
        return divisors;
    }
 
    public static void main(String[] args) {
        List<Integer> deficients = new ArrayList<>();
        List<Integer> perfects = new ArrayList<>();
        List<Integer> abundants = new ArrayList<>();
        List<Integer> divisors;
        for (int n = 1; n < 20001; n++) {
            divisors = findProperDivisors(n);
            int sum = divisors.stream().reduce(0, (a, b) -> a + b);
            if (sum < n) {
                deficients.add(n);
            }
            if (sum == n) {
                perfects.add(n);
            }
            if (sum > n) {
                abundants.add(n);
            }
        }
        System.out.println("Deficient : " + deficients.size());
        System.out.println("Perfect   : " + perfects.size());
        System.out.println("Abundant  : " + abundants.size());
    }
}

import java.util.Calendar;
import java.util.GregorianCalendar;

public class DiscordianDate {
    private static final String[] SEASON_NAMES = {"Chaos", "Discord", "Confusion", "Bureaucracy", "The Aftermath"};
    private static final String[] DAY_NAMES = {"Sweetmorn", "Boomtime", "Pungenday", "Prickle-Prickle", "Setting Orange"};
    private static final int YEAR_OFFSET = 1166;
    private static final int DAYS_PER_SEASON = 73;
    private static final int DAYS_PER_WEEK = 5;
    private static final int ST_TIBS_DAY_OF_YEAR = 60;

    private int year;
    private int day;
    private int season;
    private boolean stTibs;

    public DiscordianDate(int year, int month, int day) {
        GregorianCalendar gregorianDate = new GregorianCalendar(year, month - 1, day);
        this.day = gregorianDate.get(Calendar.DAY_OF_YEAR);

        if (gregorianDate.isLeapYear(year)) {
            if (this.day == ST_TIBS_DAY_OF_YEAR) {
                stTibs = true;
            } else if (this.day > ST_TIBS_DAY_OF_YEAR) {
                this.day -= 1;
            }
        }

        this.season = (this.day - 1) / DAYS_PER_SEASON;
        this.day = (this.day - 1) % DAYS_PER_SEASON + 1;
        this.year = gregorianDate.get(Calendar.YEAR) + YEAR_OFFSET;
    }

    public String getSeason() {
        return SEASON_NAMES[season];
    }

    public String getWeekday() {
        if (stTibs) {
            return "St. Tib's Day";
        } else {
            return DAY_NAMES[(day - 1) % DAYS_PER_WEEK];
        }
    }

    @Override
    public String toString() {
        return String.format("%s, %s %d, %d YOLD", stTibs? "St. Tib's Day" : getWeekday(), getSeason(), day, year);
    }
}

