import java.util.Scanner;
 
public class Main {
    public static void main(String[] args) {
        String lines = "";
        String longest = "";
        Scanner sc = new Scanner(new File("lines.txt"));
        while (sc.hasNext()) {
            String line = sc.nextLine();
            if (longer(longest, line)) {
                longest = line;
                lines = longest;
            } else if (!longer(line, longest)) {
                lines = lines.concat("\n").concat(line);
            }
        }
        sc.close();
        System.out.println(lines);
        System.out.println();
    }
 
    public static boolean longer(String a, String b) {
        try {
            a.substring(b.length());
            return false;
        } catch (StringIndexOutOfBoundsException e) {
            return true;
        }
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

public class Readings {
    public static void main(String[] args) throws IOException {
        String filename = "readings.txt";
        Map<String, Integer> total = new HashMap<String, Integer>();
        total.put("num_readings", 0);
        total.put("num_good_readings", 0);
        total.put("sum_readings", 0);
        int invalid_count = 0;
        int max_invalid_count = 0;
        String invalid_run_end = "";

        BufferedReader reader = new BufferedReader(new FileReader(filename));
        String line;
        while ((line = reader.readLine())!= null) {
            int num_readings = 0;
            int num_good_readings = 0;
            double sum_readings = 0.0;

            String[] fields = line.split(" ");
            for (int i = 1; i < fields.length; i += 2) {
                String reading = fields[i];
                String flag = fields[i + 1];
                num_readings += 1;
                if (Integer.parseInt(flag) > 0) {
                    num_good_readings += 1;
                    sum_readings += Double.parseDouble(reading);
                    invalid_count = 0;
                } else {
                    invalid_count += 1;
                    if (invalid_count > max_invalid_count) {
                        max_invalid_count = invalid_count;
                        invalid_run_end = fields[0];
                    }
                }
            }

            System.out.printf("Line: %11s  Reject: %2d  Accept: %2d  Line_tot: %10.3f  Line_avg: %10.3f\n",
                    fields[0], num_readings - num_good_readings, num_good_readings, sum_readings,
                    num_good_readings > 0 ? sum_readings/num_good_readings : 0.0);

            total.put("num_readings", total.get("num_readings") + num_readings);
            total.put("num_good_readings", total.get("num_good_readings") + num_good_readings);
            total.put("sum_readings", total.get("sum_readings") + (int)sum_readings);
        }

        System.out.println("");
        System.out.println("File(s)  = " + filename);
        System.out.printf("Total    = %.3f\n", total.get("sum_readings"));
        System.out.println("Readings = " + total.get("num_good_readings"));
        System.out.printf("Average  = %.3f\n", total.get("sum_readings")/total.get("num_good_readings"));
        System.out.println("");
        System.out.println("Maximum run(s) of " + max_invalid_count + " consecutive false readings ends at " + invalid_run_end);
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class BalancedParentheses {
 
    private static final long B(int x) {
        return 1L << x;
    }
 
    private static final class Tree {
        private final long tree;
 
        public Tree(long tree) {
            this.tree = tree;
        }
 
        public void show(int len) {
            for (; len > 0; len--) {
                System.out.print(tree & 1 == 1? "(" : ")");
                tree >>= 1;
            }
            System.out.println();
        }
    }
 
    private static final List<Tree> list = new ArrayList<Tree>();
    private static int cap = 0;
    private static int len = 0;
    private static final int[] offset = new int[32];
 
    private static void append(long t) {
        if (len == cap) {
            cap = cap == 0? 2 : cap * 2;
            list.ensureCapacity(cap);
        }
        list.add(new Tree(1 | t << 1));
        len++;
    }
 
    private static void listtrees(int n) {
        for (int i = offset[n]; i < offset[n + 1]; i++) {
            list.get(i).show(n * 2);
        }
    }
 
    private static void assemble(int n, long t, int sl, int pos, int rem) {
        if (rem == 0) {
            append(t);
            return;
        }
 
        if (sl > rem) {
            pos = offset[sl = rem];
        } else if (pos >= offset[sl + 1]) {
            if (--sl == 0) {
                return;
            }
            pos = offset[sl];
        }
 
        assemble(n, t << (2 * sl) | list.get(pos).tree, sl, pos, rem - sl);
        assemble(n, t, sl, pos + 1, rem);
    }
 
    private static void mktrees(int n) {
        if (offset[n + 1]!= 0) {
            return;
        }
        if (n!= 0) {
            mktrees(n - 1);
        }
 
        assemble(n, 0, n - 1, offset[n - 1], n - 1);
        offset[n + 1] = len;
    }
 
    public static void main(String[] args) {
        int n = 5;
        if (args.length > 0) {
            n = Integer.parseInt(args[0]);
        }
        if (n <= 0 || n > 25) {
            n = 5;
        }
 
        append(0);
 
        mktrees(n);
        System.err.printf("Number of %d-trees: %d%n", n, offset[n + 1] - offset[n]);
        listtrees(n);
    }
}

