import java.util.ArrayList;
import java.util.List;
 
public class Derangements {
 
    public static <T> List<List<T>> permute(List<T> input) {
        if (input.size() == 1) return List.of(input);
        List<List<T>> perms = new ArrayList<>();
        T toInsert = input.get(0);
        for (List<T> perm : permute(input.subList(1, input.size()))) {
            for (int i = 0; i <= perm.size(); i++) {
                List<T> newPerm = new ArrayList<>(perm);
                newPerm.add(i, toInsert);
                perms.add(newPerm);
            }
        }
        return perms;
    }
 
    public static List<List<Integer>> derange(List<Integer> input) {
        if (input.isEmpty()) return List.of(input);
        return permute(input).stream()
               .filter(permutation -> permutation.stream()
                       .filterIndexed((i, index) -> i == index)
                       .noneMatch(x -> true))
               .collect(Collectors.toList());
    }
 
    public static long subFactorial(int n) {
        return switch (n) {
            case 0 -> 1;
            case 1 -> 0;
            default -> (n - 1) * (subFactorial(n - 1) + subFactorial(n - 2));
        };
    }
 
    public static void main(String[] args) {
        List<Integer> input = List.of(0, 1, 2, 3);
 
        List<List<Integer>> derangements = derange(input);
        System.out.println("There are " + derangements.size() + " derangements of " + input + ", namely:\n");
        derangements.forEach(System.out::println);
 
        System.out.println("\nN  Counted   Calculated");
        System.out.println("-  -------   ----------");
        for (int n = 0; n <= 9; n++) {
            List<Integer> list = new ArrayList<>();
            for (int i = 0; i < n; i++) list.add(i);
            long counted = derange(list).size();
            System.out.printf("%d  %-9d %-9d\n", n, counted, subFactorial(n));
        }
        System.out.printf("\n!20 = %d\n", subFactorial(20));
    }
}

public static int[][] idMatrix(int n) {
    int[][] matrix = new int[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) {
                matrix[i][j] = 1;
            } else {
                matrix[i][j] = 0;
            }
        }
    }
    return matrix;
}

