import java.text.SimpleDateFormat;
import java.util.Date;
import java.io.File;
import java.io.IOException;
 
public class Simdb {
 
    private static final File file = new File("simdb.csv");
 
    private static class Item implements Comparable<Item> {
 
        private final String name;
        private final String date;
        private final String category;
 
        public Item(String name, String date, String category) {
            this.name = name;
            this.date = date;
            this.category = category;
        }
 
        @Override
        public int compareTo(Item other) {
            return date.compareTo(other.date);
        }
 
        @Override
        public String toString() {
            return name + ", " + date + ", " + category;
        }
    }
 
    private static void addItem(String[] input) {
        if (input.length < 2) {
            printUsage();
            return;
        }
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss");
        String date = sdf.format(new Date());
        String cat = input.length == 3? input[2] : "none";
        store(new Item(input[1], date, cat));
    }
 
    private static void printLatest(String[] a) {
        List<Item> db = load();
        if (db.isEmpty()) {
            System.out.println("No entries in database.");
            return;
        }
        // no need to sort db as items are added chronologically
        if (a.length == 2) {
            boolean found = false;
            for (Item item : db) {
                if (item.category.equals(a[1])) {
                    System.out.println(item);
                    found = true;
                    break;
                }
            }
            if (!found) System.out.println("There are no items for category '" + a[1] + "'");
        }
        else System.out.println(db.get(db.size() - 1));
    }
 
    private static void printAll() {
        List<Item> db = load();
        if (db.isEmpty()) {
            System.out.println("No entries in database.");
            return;
        }
        // no need to sort db as items are added chronologically
        for (Item item : db) System.out.println(item);
    }
 
    private static List<Item> load() {
        List<Item> db = new ArrayList<>();
        try {
            Scanner scanner = new Scanner(file);
            while (scanner.hasNextLine()) {
                String line = scanner.nextLine();
                String[] item = line.split(", ");
                db.add(new Item(item[0], item[1], item[2]));
            }
        }
        catch (IOException e) {
            System.out.println(e);
            System.exit(1);
        }
        return db;
    }
 
    private static void store(Item item) {
        try {
            FileWriter fw = new FileWriter(file, true);
            fw.write(item + "\n");
            fw.close();
        }
        catch (IOException e) {
            System.out.println(e);
        }
    }
 
    private static void printUsage() {
        System.out.println("""
            |Usage:
            |  simdb cmd [categoryName]
            |  add     add item, followed by optional category
            |  latest  print last added item(s), followed by optional category
            |  all     print all
            |  For instance: add "some item name" "some category name"
        """.trim());
    }
 
    public static void main(String[] args) {
        if (args.length!= 1 && args.length!= 2 && args.length!= 3) {
            printUsage();
            return;
        }
        try {
            file.createNewFile();  // create file if it doesn't already exist
        }
        catch (IOException e) {
            System.out.println(e);
        }
        switch (args[0].toLowerCase()) {
            case "add":
                addItem(args);
                break;
            case "latest":
                printLatest(args);
                break;
            case "all":
                printAll();
                break;
            default:
                printUsage();
        }
    }
}

import java.util.Scanner;
import java.util.Locale;
import java.lang.Math;
 
public class Main{
	public static void main(String[] args){
		double[] arr;
		double min,max;
		String str;
		int i,len;
		if(args.length == 0)
			System.out.println("Usage : "+args[0]+" <data points separated by spaces or commas>");
		else{
			arr = new double[args.length];
			for(i=0;i<args.length;i++){
				len = args[i].length();
 
				if(args[i].charAt(len-1)==','){
					str = args[i].substring(0,len-1);
					arr[i] = Double.parseDouble(str);
				}
				else
					arr[i] = Double.parseDouble(args[i]);
				if(i==0){
					min = arr[i];
					max = arr[i];
				}
				else{
					min=(min<arr[i]?min:arr[i]);
					max=(max>arr[i]?max:arr[i]);
				}
			}
 
			System.out.println("\nMax : "+max+",Min : "+min+",Range : "+(max-min));
 
			Locale.setDefault(Locale.US);
 
			for(i=0;i<args.length;i++){
				System.out.print((char)(9601 + (int)Math.ceil((arr[i]-min)/(max-min)*7)));
			}
		}
	}
}

task_description:
Task

Show one or more idiomatic ways of generating the Cartesian product of two arbitrary lists in your language.

Demonstrate that your function/method correctly returns:

{1, 2} × {3, 4} = {(1, 3), (1, 4), (2, 3), (2, 4)}
and, in contrast:

{3, 4} × {1, 2} = {(3, 1), (3, 2), (4, 1), (4, 2)}
Also demonstrate, using your function/method, that the product of an empty list with any other list is empty.

 {1, 2} × {} = {}
 {} × {1, 2} = {}
For extra credit, show or write a function returning the n-ary product of an arbitrary number of lists, each of arbitrary length. Your function might, for example, accept a single argument which is itself a list of lists, and return the n-ary product of those lists.

Use your n-ary Cartesian product function to show the following products:

 {1776, 1789} × {7, 12} × {4, 14, 23} × {0, 1}
 {1, 2, 3} × {30} × {500, 100}
 {1, 2, 3} × {} × {500, 100}

code:
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
 
public class CartesianProduct {
 
    public static void main(String[] args) {
        List<List<Integer>> cases = Arrays.asList(
                Arrays.asList(Arrays.asList(1, 2), Arrays.asList(3, 4)),
                Arrays.asList(Arrays.asList(3, 4), Arrays.asList(1, 2)),
                Arrays.asList(Arrays.asList(1, 2), Arrays.asList()),
                Arrays.asList(Arrays.asList(), Arrays.asList(1, 2)),
                Arrays.asList(Arrays.asList(1776, 1789), Arrays.asList(7, 12), Arrays.asList(4, 14, 23), Arrays.asList(0, 1)),
                Arrays.asList(Arrays.asList(1, 2, 3), Arrays.asList(30), Arrays.asList(500, 100)),
                Arrays.asList(Arrays.asList(1, 2, 3), Arrays.asList(), Arrays.asList(500, 100))
        );
        for (List<Integer> case_ : cases) {
            System.out.println(case_ + "\n" + cartesianProduct(case_) + "\n");
        }
    }
 
    public static List<List<Integer>> cartesianProduct(List<List<Integer>> lists) {
        List<List<Integer>> res = new ArrayList<>();
 
        List<List<Integer>>.ListIterator listIter = lists.listIterator();
        if (listIter.hasNext()) {
            List<Integer> firstList = listIter.next();
            for (Integer i : firstList) {
                res.add(Arrays.asList(i));
            }
        }
        while (listIter.hasNext()) {
            List<Integer> l = listIter.next();
            List<List<Integer>> tmp = new ArrayList<>();
            for (List<Integer> r : res) {
                for (Integer el : l) {
                    List<Integer> tmpEl = new ArrayList<>(r);
                    tmpEl.add(el);
                    tmp.add(tmpEl);
                }
            }
            res = tmp;
        }
        return res;
    }
}

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Imprecise {
    private final double value;
    private final double delta;

    public Imprecise(double value, double delta) {
        this.value = value;
        this.delta = Math.abs(delta);
    }

    public Imprecise(double value) {
        this(value, 0.0);
    }

    public Imprecise() {
        this(0.0, 0.0);
    }

    public Imprecise reciprocal() {
        return new Imprecise(1.0 / value, delta / (value * value));
    }

    public String toString() {
        return String.format("I(%g, %g)", value, delta);
    }

    public Imprecise negate() {
        return new Imprecise(-value, delta);
    }

    public Imprecise add(Imprecise other) {
        return new Imprecise(value + other.value, Math.sqrt(delta * delta + other.delta * other.delta));
    }

    public Imprecise add(double other) {
        return new Imprecise(value + other, delta);
    }

    public Imprecise subtract(Imprecise other) {
        return add(other.negate());
    }

    public Imprecise subtract(double other) {
        return add(-other);
    }

    public Imprecise multiply(Imprecise other) {
        double a1 = value;
        double b1 = delta;
        double a2 = other.value;
        double b2 = other.delta;
        double f = a1 * a2;
        return new Imprecise(f, f * Math.sqrt((b1 / a1) * (b1 / a1) + (b2 / a2) * (b2 / a2)));
    }

    public Imprecise multiply(double other) {
        return new Imprecise(value * other, delta * other);
    }

    public Imprecise divide(Imprecise other) {
        return multiply(other.reciprocal());
    }

    public Imprecise divide(double other) {
        return new Imprecise(value / other, delta / other);
    }

    public Imprecise pow(double other) {
        double f = Math.pow(value, other);
        return new Imprecise(f, f * other * (delta / value));
    }

    public static double distance(List<Imprecise> p1, List<Imprecise> p2) {
        return Math.sqrt(Math.pow(p1.get(0).subtract(p2.get(0)).value, 2) + Math.pow(p1.get(1).subtract(p2.get(1)).value, 2));
    }

    public static void main(String[] args) {
        Imprecise x1 = new Imprecise(100, 1.1);
        Imprecise x2 = new Imprecise(200, 2.2);
        Imprecise y1 = new Imprecise(50, 1.2);
        Imprecise y2 = new Imprecise(100, 2.3);
        List<Imprecise> p1 = Arrays.asList(x1, y1);
        List<Imprecise> p2 = Arrays.asList(x2, y2);
        System.out.println("Distance between points\n  p1: " + p1 + "\n  and p2: " + p2 + "\n  = " + distance(p1, p2));
    }
}

import java.lang.Math;
import java.lang.System;
 
public class A073916 {
 
    private static final int LIMIT = 15;
    private static int[] smallPrimes = new int[LIMIT];
 
    private static void sieve() {
        int i = 2, j;
        int p = 5;
 
        smallPrimes[0] = 2;
        smallPrimes[1] = 3;
 
        while (i < LIMIT) {
            for (j = 0; j < i; j++) {
                if (smallPrimes[j] * smallPrimes[j] <= p) {
                    if (p % smallPrimes[j] == 0) {
                        p += 2;
                        break;
                    }
                } else {
                    smallPrimes[i++] = p;
                    p += 2;
                    break;
                }
            }
        }
    }
 
    private static boolean is_prime(long n) {
        long i;
 
        for (i = 0; i < LIMIT; i++) {
            if (n % smallPrimes[i] == 0) {
                return n == smallPrimes[i];
            }
        }
 
        i = smallPrimes[LIMIT - 1] + 2;
        for (; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
 
        return true;
    }
 
    private static long divisor_count(long n) {
        long count = 1;
        long d;
 
        while (n % 2 == 0) {
            n /= 2;
            count++;
        }
 
        for (d = 3; d * d <= n; d += 2) {
            long q = n / d;
            long r = n % d;
            long dc = 0;
            while (r == 0) {
                dc += count;
                n = q;
                q = n / d;
                r = n % d;
            }
            count += dc;
        }
 
        if (n!= 1) {
            return count *= 2;
        }
        return count;
    }
 
    private static long OEISA073916(long n) {
        long count = 0;
        long result = 0;
        long i;
 
        if (is_prime(n)) {
            return (long)Math.pow(smallPrimes[n - 1], n - 1);
        }
 
        for (i = 1; count < n; i++) {
            if (n % 2 == 1) {
                //  The solution for an odd (non-prime) term is always a square number
                long root = (long)Math.sqrt(i);
                if (root * root!= i) {
                    continue;
                }
            }
            if (divisor_count(i) == n) {
                count++;
                result = i;
            }
        }
 
        return result;
    }
 
    public static void main(String[] args) {
        long n;
 
        sieve();
 
        for (n = 1; n <= LIMIT; n++) {
            if (n == 13) {
                System.out.printf("A073916(%d) = One more bit needed to represent result.\n", n);
            } else {
                System.out.printf("A073916(%d) = %d\n", n, OEISA073916(n));
            }
        }
    }
}

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.HashMap;
import java.util.Map;
 
public class LZW {
 
    private static final int EOF = -1;
 
    public static void compress(InputStream in, OutputStream out) throws IOException {
        Map<String, Integer> dictionary = new HashMap<String, Integer>();
        for (int i = 0; i < 256; i++) {
            dictionary.put("" + (char) i, i);
        }
 
        String w = "";
        int k;
        while ((k = in.read())!= EOF) {
            String entry = w + (char) k;
            if (dictionary.containsKey(entry)) {
                w = entry;
            } else {
                out.write(dictionary.get(w));
                dictionary.put(entry, dictionary.size());
                w = "" + (char) k;
            }
        }
 
        if (!w.isEmpty()) {
            out.write(dictionary.get(w));
        }
    }
 
    public static void decompress(InputStream in, OutputStream out) throws IOException {
        Map<Integer, String> dictionary = new HashMap<Integer, String>();
        for (int i = 0; i < 256; i++) {
            dictionary.put(i, "" + (char) i);
        }
 
        int k = in.read();
        String w = dictionary.get(k);
        out.write(w.getBytes());
        while ((k = in.read())!= EOF) {
            String entry;
            if (dictionary.containsKey(k)) {
                entry = dictionary.get(k);
            } else if (k == dictionary.size()) {
                entry = w + w.charAt(0);
            } else {
                throw new IllegalArgumentException("Bad compressed k: " + k);
            }
 
            out.write(entry.getBytes());
 
            dictionary.put(dictionary.size(), w + entry.charAt(0));
 
            w = entry;
        }
    }
 
    public static void main(String[] args) throws IOException {
        String input = "TOBEORNOTTOBEORTOBEORNOT";
        ByteArrayOutputStream compressed = new ByteArrayOutputStream();
        compress(new ByteArrayInputStream(input.getBytes()), compressed);
        System.out.println(compressed.toString());
        ByteArrayOutputStream decompressed = new ByteArrayOutputStream();
        decompress(new ByteArrayInputStream(compressed.toByteArray()), decompressed);
        System.out.println(decompressed.toString());
    }
}

public final class Collapse {
    public static final void main(@NotNull String[] args) {
        Intrinsics.checkParameterIsNotNull(args, "args");
        String[] strings = new String[]{"", "\"If I were two-faced, would I be wearing this one?\" ---  ", "..1111111111111111111111111111111111111111111111111111111111111117777888", "I never give 'em hell, I just tell the truth, and they think it's hell. ", "                                                   ---    ", "The better the 4-wheel drive, the further you'll be from help when ya get stuck!", "headmistressship", "aardvark"};
        for (String s : strings) {
            String c = collapse(s);
            System.out.println("original : length = " + s.length() + ", string = «««" + s + "»»»");
            System.out.println("collapsed : length = " + c.length() + ", string = «««" + c + "»»»");
            System.out.println();
        }
    }

    @NotNull
    public static final String collapse(@NotNull String s) {
        Intrinsics.checkParameterIsNotNull(s, "s");
        StringBuilder cs = new StringBuilder();
        char last = '\u0000';
        for (char c : s.toCharArray()) {
            if (c!= last) {
                cs.append(c);
                last = c;
            }
        }
        return cs.toString();
    }
}

