import java.util.function.Function;

public class Main {
    public static void main(String[] args) {
        Function<Integer, Function<Integer, Integer>> x = i -> () -> i;
        System.out.println(a(10, x.apply(1), x.apply(-1), x.apply(-1), x.apply(1), x.apply(0)));
    }

    public static int a(int k, Function<Integer, Integer> x1, Function<Integer, Integer> x2, Function<Integer, Integer> x3, Function<Integer, Integer> x4, Function<Integer, Integer> x5) {
        Function<Integer, Integer> b = () -> {
            k--;
            return a(k, b, x1, x2, x3, x4);
        };
        if (k <= 0) {
            return x4.apply(0) + x5.apply(0);
        }
        return b.apply(0);
    }
}

