import java.awt.*;
import java.awt.image.BufferedImage;
import javax.swing.*;
 
class PlasmaEffect extends JPanel {
    private final float[][] plasma;
    private float hueShift = 0.0f;
    private final BufferedImage img;
 
    public PlasmaEffect() {
        Dimension dim = new Dimension(640, 640);
        setPreferredSize(dim);
        setBackground(Color.white);
        img = new BufferedImage(dim.width, dim.height, BufferedImage.TYPE_INT_RGB);
        plasma = createPlasma(dim.height, dim.width);
        // animate about 24 fps and shift hue value with every frame
        new Timer(42, e -> {
            hueShift = (hueShift + 0.02f) % 1;
            repaint();
        }).start();
    }
 
    private float[][] createPlasma(int w, int h) {
        float[][] buffer = new float[h][w];
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                double value = Math.sin(x / 16.0);
                value += Math.sin(y / 8.0);
                value += Math.sin((x + y) / 16.0);
                value += Math.sin(Math.sqrt((x * x + y * y)) / 8.0);
                value += 4.0;  // shift range from -4.. 4 to 0.. 8
                value /= 8.0;  // bring range down to 0.. 1
                if (value < 0.0 || value > 1.0) throw new RuntimeException("Hue value out of bounds");
                buffer[y][x] = (float) value;
            }
        return buffer;
    }
 
    private void drawPlasma(Graphics2D g) {
        int h = plasma.length;
        int w = plasma[0].length;
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                float hue = hueShift + plasma[y][x] % 1;
                img.setRGB(x, y, Color.HSBtoRGB(hue, 1.0f, 1.0f));
            }
        g.drawImage(img, 0, 0, null);
    }
 
    @Override
    public void paintComponent(Graphics gg) {
        super.paintComponent(gg);
        Graphics2D g = (Graphics2D) gg;
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        drawPlasma(g);
    }
}
 
public class Main {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame f = new JFrame();
            f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            f.setTitle("Plasma Effect");
            f.setResizable(false);
            f.add(new PlasmaEffect(), BorderLayout.CENTER);
            f.pack();
            f.setLocationRelativeTo(null);
            f.setVisible(true);
        });
    }
}

