import java.util.Stack;
 
public class InfixToPostfix {
 
    public static void main(String[] args) {
        String infix = "3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3";
        infix = infix.replace("\\s+", ""); // remove spaces, so infix[i]!=" "
 
        Stack<String> s = new Stack<String>();
        String ops = "-+/*^";
        int[] precedence = {4, 3, 3, 2, 2};
        String[] associativity = {"Right", "Left", "Left", "Left", "Left"};
        String token;
        String postfix = "";
        String o1, o2;
 
        for (int i = 0; i < infix.length(); i++) {
            token = infix.substring(i, i + 1);
            if (token.matches("[0-9]")) { // if token is operand (here limited to 0 <= x <= 9)
                postfix += token + " ";
            } else if (ops.indexOf(token)!= -1) { // if token is an operator
                o1 = token;
                o2 = s.peek();
                while (ops.indexOf(o2)!= -1 && ( // while operator token, o2, on top of the stack
                        // and o1 is left-associative and its precedence is less than or equal to that of o2
                        (associativity[ops.indexOf(o1)].equals("Left") && (precedence[ops.indexOf(o1)] <= precedence[ops.indexOf(o2)])) ||
                        // the algorithm on wikipedia says: or o1 precedence < o2 precedence, but I think it should be
                        // or o1 is right-associative and its precedence is less than that of o2
                        (associativity[ops.indexOf(o1)].equals("Right") && (precedence[ops.indexOf(o1)] < precedence[ops.indexOf(o2)]))
                )) {
                    postfix += o2 + " "; // add o2 to output queue
                    s.pop(); // pop o2 of the stack
                    o2 = s.peek(); // next round
                }
                s.push(o1); // push o1 onto the stack
            } else if (token.equals("(")) { // if token is left parenthesis
                s.push(token); // then push it onto the stack
            } else if (token.equals(")")) { // if token is right parenthesis 
                while (!s.peek().equals("(")) { // until token at top is (
                    postfix += s.pop() + " ";
                }
                s.pop(); // pop (, but not onto the output queue
            }
        }
        postfix += s.toString().replace("[", "").replace("]", "").replace(",", "").replace(" ", "");
        System.out.println(postfix);
    }
}

public class IsPalindrome {
	public static void main(String[] args) {
		System.out.println(isPalindrome("racecar"));
	}

	public static boolean isPalindrome(String str) {
		int len = str.length();
		for (int i = 0; i < len / 2; i++) {
			if (str.charAt(i)!= str.charAt(len - 1 - i))
				return false;
		}
		return true;
	}
}

