public class Linear {
    public static void main(String[] args) {
        System.out.println(linear(new int[]{1, 2, 3}));
        System.out.println(linear(new int[]{0, 1, 2, 3}));
        System.out.println(linear(new int[]{1, 0, 3, 4}));
        System.out.println(linear(new int[]{1, 2, 0}));
        System.out.println(linear(new int[]{0, 0, 0}));
        System.out.println(linear(new int[]{0}));
        System.out.println(linear(new int[]{1, 1, 1}));
        System.out.println(linear(new int[]{-1, -1, -1}));
        System.out.println(linear(new int[]{-1, -2, 0, 3}));
        System.out.println(linear(new int[]{-1}));
    }
    public static String linear(int[] x) {
        String result = "";
        for (int i = 0; i < x.length; i++) {
            if (x[i]!= 0) {
                if (x[i] == 1) {
                    result += "e(" + (i + 1) + ")";
                } else if (x[i] == -1) {
                    result += "-e(" + (i + 1) + ")";
                } else {
                    result += x[i] + "*e(" + (i + 1) + ")";
                }
                if (i!= x.length - 1) {
                    result += " + ";
                }
            }
        }
        if (result.equals("")) {
            return "0";
        }
        return result.replace(" + -", " - ");
    }
}

import java.util.ArrayList;
import java.util.Calendar;
import java.util.Date;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;

public class Weekends {

    private static final List<Integer> LONG_MONTHS = List.of(1, 3, 5, 7, 8, 10, 12);
    private static final List<Integer> YEARS = IntStream.rangeClosed(1900, 2100).boxed().collect(Collectors.toList());

    public static void main(String[] args) {
        List<Date> dates = YEARS.stream()
               .flatMap(y -> LONG_MONTHS.stream().map(m -> {
                    Calendar calendar = Calendar.getInstance();
                    calendar.set(y, m - 1, 31);
                    return calendar.getTime();
                }))
               .filter(d -> d.toString().endsWith("Sun"))
               .collect(Collectors.toList());
        List<Integer> years_4w = YEARS.stream()
               .filter(y ->!dates.stream().anyMatch(d -> d.toString().startsWith(y + "-")))
               .collect(Collectors.toList());

        System.out.println("There are " + dates.size() + " months with 5 weekends from 1900 to 2100:");
        System.out.println(dates.subList(0, 5).stream().map(d -> d.toString().substring(4, 7) + " " + d.toString().substring(0, 4)).collect(Collectors.toList()));
        System.out.println("...");
        System.out.println(dates.subList(dates.size() - 5, dates.size()).stream().map(d -> d.toString().substring(4, 7) + " " + d.toString().substring(0, 4)).collect(Collectors.toList()));
        System.out.println("There are " + years_4w.size() + " years without months with 5 weekends:");
        System.out.println(years_4w.stream().map(Object::toString).collect(Collectors.joining(", ")));
    }
}

public class SEDOL {
    public static int[] sedol_weights = { 1, 3, 1, 7, 3, 9 };
    public static int sedolChecksum(String sedol) {
        int len = sedol.length();
        int sum = 0;
        if (len == 7) {
            return sedol.charAt(6);
        }
        if ((len > 7) || (len < 6) || sedol.matches("[AEIOUaeiou]+")) {
            return -1;
        }
        for (int i = 0; i < 6; i++) {
            if (Character.isDigit(sedol.charAt(i))) {
                sum += ((sedol.charAt(i) - 48) * sedol_weights[i]);
            } else if (Character.isLetter(sedol.charAt(i))) {
                sum += ((Character.toUpperCase(sedol.charAt(i)) - 55) * sedol_weights[i]);
            } else {
                return -1;
            }
        }
        return (10 - (sum % 10)) % 10;
    }
}

