public final class PopCount {
    public static final void main(String[] args) {
        System.out.println("The population count of the first 30 powers of 3 are:");
        long pow3 = 1L;
        for (int i = 1; i <= 30; i++) {
            System.out.print(popCount(pow3) + " ");
            pow3 *= 3L;
        }
        System.out.println("\n");
        System.out.println("The first thirty evil numbers are:");
        int count = 0;
        int i = 0;
        while (true) {
            long pc = popCount(i);
            if (pc % 2 == 0) {
                System.out.print(i + " ");
                if (++count == 30) break;
            }
            i++;
        }
        System.out.println("\n");
        System.out.println("The first thirty odious numbers are:");
        count = 0;
        i = 1;
        while (true) {
            long pc = popCount(i);
            if (pc % 2 == 1) {
                System.out.print(i + " ");
                if (++count == 30) break;
            }
            i++;
        }
        System.out.println();
    }
 
    public static final long popCount(long n) {
        if (n < 0L) throw new IllegalArgumentException("n must be non-negative");
        else return java.lang.Long.bitCount(n);
    }
}

