public class Main {
  public static void main(String[] args) {
    List<Integer> a = new ArrayList<>();
    a.add(0);
    Set<Integer> used = new HashSet<>();
    used.add(0);
    Set<Integer> used1000 = new HashSet<>();
    used1000.add(0);
    boolean foundDup = false;
    int n = 1;
    while (n <= 15 ||!foundDup || used1000.size() < 1001) {
      int next = a.get(n - 1) - n;
      if (next < 1 || used.contains(next)) {
        next += 2 * n;
      }
      boolean alreadyUsed = used.contains(next);
      a.add(next);
      if (!alreadyUsed) {
        used.add(next);
        if (next >= 0 && next <= 1000) {
          used1000.add(next);
        }
      }
      if (n == 14) {
        System.out.println("The first 15 terms of the Recaman's sequence are: " + a);
      }
      if (!foundDup && alreadyUsed) {
        System.out.println("The first duplicated term is a[" + n + "] = " + next);
        foundDup = true;
      }
      if (used1000.size() == 1001) {
        System.out.println("Terms up to a[" + n + "] are needed to generate 0 to 1000");
      }
      n++;
    }
  }
}

