import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
 
public class MissingPermutations {
 
    public static void main(String[] args) {
        String[] given = {
                "ABCD", "CABD", "ACDB", "DACB", "BCDA", "ACBD", "ADCB", "CDAB", "DABC", "BCAD", "CADB", "CDBA",
                "CBAD", "ABDC", "ADBC", "BDCA", "DCBA", "BACD", "BADC", "BDAC", "CBDA", "DBCA", "DCAB"
        };
 
        List<String> all = Arrays.stream(given[0].split(""))
               .sorted()
               .collect(Collectors.toList());
 
        List<String> missing = new ArrayList<>();
        for (int i = 0; i < all.size(); i++) {
            for (int j = i + 1; j < all.size(); j++) {
                for (int k = j + 1; k < all.size(); k++) {
                    for (int l = k + 1; l < all.size(); l++) {
                        String permutation = all.get(i) + all.get(j) + all.get(k) + all.get(l);
                        if (!Arrays.asList(given).contains(permutation)) {
                            missing.add(permutation);
                        }
                    }
                }
            }
        }
 
        System.out.println("missing: " + missing);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public class Latin {
    private int size;
    private List<Integer> mst;
    private int[][] square;

    public Latin(int size) {
        this.size = size;
        this.mst = new ArrayList<>();
        for (int i = 1; i <= size; i++) {
            mst.add(i);
        }
        this.square = new int[size][size];

        if (create(0, 0)) {
            for (int[] row : square) {
                for (int i : row) {
                    System.out.print(i + " ");
                }
                System.out.println();
            }
        }
    }

    private boolean create(int c, int r) {
        List<Integer> d = new ArrayList<>(mst);
        int s;
        while (true) {
            do {
                s = d.remove(new Random().nextInt(d.size()));
                if (s == 0) return false;
            } while (check(s, c, r));

            square[c][r] = s;
            if (++c >= size) {
                c = 0;
                if (++r >= size) {
                    return true;
                }
            }
            if (create(c, r)) return true;
            if (--c < 0) {
                c = size - 1;
                if (--r < 0) {
                    return false;
                }
            }
        }
    }

    private boolean check(int d, int c, int r) {
        for (int a = 0; a < size; a++) {
            if (c - a > -1) {
                if (square[c - a][r] == d)
                    return true;
            }
            if (r - a > -1) {
                if (square[c][r - a] == d)
                    return true;
            }
        }
        return false;
    }
}

import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
 
public class CloseTo {
 
    public static void main(String[] args) {
        List<BigDecimal[]> testvalues = new ArrayList<>();
        testvalues.add(new BigDecimal[]{new BigDecimal("100000000000000.01"), new BigDecimal("100000000000000.011")});
        testvalues.add(new BigDecimal[]{new BigDecimal("100.01"), new BigDecimal("100.011")});
        testvalues.add(new BigDecimal[]{new BigDecimal("10000000000000.001").divide(new BigDecimal("10000.0"), MathContext.DECIMAL128), new BigDecimal("1000000000.0000001000")});
        testvalues.add(new BigDecimal[]{new BigDecimal("0.001"), new BigDecimal("0.0010000001")});
        testvalues.add(new BigDecimal[]{new BigDecimal("0.000000000000000000000101"), new BigDecimal("0.0")});
        testvalues.add(new BigDecimal[]{new BigDecimal("1."));
        testvalues.add(new BigDecimal[]{new BigDecimal("3.14159265358979323846"), new BigDecimal("3.14159265358979324")});
        testvalues.add(new BigDecimal[]{new BigDecimal("NaN"), new BigDecimal("NaN")});
        testvalues.add(new BigDecimal[]{new BigDecimal("Infinity"), new BigDecimal("Infinity")});
 
        for (BigDecimal[] testvalue : testvalues) {
            System.out.println(testvalue[0] + " " + (testvalue[0].closeTo(testvalue[1])? "≈" : "≉") + " " + testvalue[1]);
        }
    }
 
    public static boolean closeTo(BigDecimal a, BigDecimal b) {
        return closeTo(a, b, new BigDecimal(Float.MIN_NORMAL));
    }
 
    public static boolean closeTo(BigDecimal a, BigDecimal b, BigDecimal tol) {
        if (a.equals(b)) {
            return true;
        }
        if (a.isNaN() || b.isNaN()) {
            return false;
        }
        if (a.isInfinite() ^ b.isInfinite()) {
            return false;
        }
        return a.subtract(b).abs().compareTo(tol.multiply(a.abs().max(b.abs()))) <= 0;
    }
}

import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.BufferedWriter;
import java.io.DataOutputStream;
import java.awt.image.BufferedImage;
import java.awt.Color;

public class PPMWriter
{
    public static void WriteBitmapToPPM(String file, BufferedImage bitmap) throws IOException
        {
            //Use a streamwriter to write the text part of the encoding
            BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(new FileOutputStream(file)));
            writer.write("P6\n");
            writer.write(String.format("%d  %d\n", bitmap.getWidth(), bitmap.getHeight()));
            writer.write("255\n");
            writer.close();
            //Switch to a binary writer to write the data
            DataOutputStream writerB = new DataOutputStream(new FileOutputStream(file, true));
            for (int x = 0; x < bitmap.getHeight(); x++)
                for (int y = 0; y < bitmap.getWidth(); y++)
                {
                    Color color = new Color(bitmap.getRGB(y, x));
                    writerB.writeByte(color.getRed());
                    writerB.writeByte(color.getGreen());
                    writerB.writeByte(color.getBlue());
                }
            writerB.close();
        }
}

public class LCM {
    public static void main(String[] args) {
        int[] A = {-50,25,-45,-18,90,447};
        System.out.println(LCM(A));
    }

    public static int LCM(int[] A) {
        int n = A.length, a = Math.abs(A[0]);
        for (int i = 1; i < n; i++) {
            int b = Math.abs(A[i]), c = a;
            while (a!= 0 && b!= 0) {
                if (a > b) {
                    a %= b;
                } else {
                    b %= a;
                }
            }
            a = Math.abs(c*A[i])/(a+b);
        }
        return a;
    }
}

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
 
public class CircleSort {
    public static int[] circleSort(int[] array) {
        if (array.length > 0)
            while (circleSortR(array, 0, array.length - 1, 0)!= 0)
                continue;
        return array;
    }
 
    private static int circleSortR(int[] arr, int lo, int hi, int numSwaps) {
        if (lo == hi)
            return numSwaps;
 
        int high = hi;
        int low = lo;
        int mid = (hi - lo) / 2;
 
        while (lo < hi) {
            if (arr[lo] > arr[hi]) {
                int temp = arr[lo];
                arr[lo] = arr[hi];
                arr[hi] = temp;
                numSwaps++;
            }
            lo++;
            hi--;
        }
 
        if (lo == hi && arr[lo] > arr[hi + 1]) {
            int temp = arr[lo];
            arr[lo] = arr[hi + 1];
            arr[hi + 1] = temp;
            numSwaps++;
        }
 
        numSwaps = circleSortR(arr, low, low + mid, numSwaps);
        numSwaps = circleSortR(arr, low + mid + 1, high, numSwaps);
 
        return numSwaps;
    }
 
    public static void main(String[] args) {
        int[] sortedArray = circleSort(new int[] { 6, 7, 8, 9, 2, 5, 3, 4, 1 });
        List<Integer> list = Arrays.stream(sortedArray).boxed().collect(Collectors.toList());
        list.forEach(i -> System.out.print(i.toString() + " "));
        System.out.println();
        int[] sortedArray2 = circleSort(new int[] { 2, 14, 4, 6, 8, 1, 3, 5, 7, 11, 0, 13, 12, -1 });
        list = Arrays.stream(sortedArray2).boxed().collect(Collectors.toList());
        list.forEach(i -> System.out.print(i.toString() + " "));
        System.out.println();
        int[] sortedArray3 = circleSort(new int[] { 2, 3, 3, 5, 5, 1, 1, 7, 7, 6, 6, 4, 4, 0, 0 });
        list = Arrays.stream(sortedArray3).boxed().collect(Collectors.toList());
        list.forEach(i -> System.out.print(i.toString() + " "));
    }
}

