import java.lang.String;
import java.lang.System;
 
class Program
{
    public static void main(String[] args)
    {
        //string creation
        String x = "hello world";
 
        //# mark string for garbage collection
        x = null;
 
        //# string assignment with a null byte
        x = "ab\0";
        System.out.println(x);
        System.out.println(x.length()); // 3
 
        //# string comparison
        if (x.equals("hello"))
            System.out.println("equal");
        else
            System.out.println("not equal");
 
        if (x.compareTo("bc") == -1)
            System.out.println("x is lexicographically less than 'bc'");
 
        //# string cloning 
        char[] c = new char[3];
        x.getChars(0, 3, c, 0);
        Object objecty = new String(c);
        String y = new String(c);
 
        System.out.println(x.equals(y));      //same as string.equals
        System.out.println(x.equals(y)); //it overrides object.Equals
 
        System.out.println(x.equals(objecty)); //uses object.Equals, return false
 
        //# check if empty
        String empty = "";
        String nullString = null;
        String whitespace = "   ";
        if (nullString == null && empty.equals("") && 
            (nullString == null || nullString.length() == 0) && (empty.length() == 0) &&
            (nullString == null || nullString.length() == 0 || nullString.trim().length() == 0) && (empty.length() == 0 || empty.trim().length() == 0) &&
            (whitespace.length() == 0 || whitespace.trim().length() == 0))
            System.out.println("Strings are null, empty or whitespace");
 
        //# append a byte
        x = "helloworld";
        x += (char)83;
        System.out.println(x);
 
        //# substring
        String slice = x.substring(5, 5);
        System.out.println(slice);
 
        //# replace bytes
        String greeting = x.replace("worldS", "");
        System.out.println(greeting);
 
        //# join strings
        String join = greeting + " " + slice;
        System.out.println(join);
    }
}

