class m35
{
    public void doIt( long i )
    {
	long sum = 0;
	for( long a = 1; a < i; a++ )
	    if(!( a % 3 ) ||!( a % 5 ) ) sum += a;
 
	System.out.println( "Sum is " + sum + " for n = " + i );
    }
 
    // this method uses less than half iterations than the first one
    public void doIt_b( long i )
    {
	long sum = 0;
	for( long a = 0; a < 28; a++ )
	{
	    if(!( a % 3 ) ||!( a % 5 ) )
	    {
		sum += a;
		for( long s = 30; s < i; s += 30 )
		    if( a + s < i ) sum += ( a + s );
 
	    }
	}
	System.out.println( "Sum is " + sum + " for n = " + i );
    }
}
//--------------------------------------------------------------------------------------------------
class Main
{
    public static void main ( String[] args ) throws java.lang.Exception
    {
	m35 m = new m35();
	m.doIt( 1000 );
    }
}

