import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
 
/* Separates each integer in the list with an 'a' then encodes in base 11. Empty list mapped to '-1' */
public class Rank {
    public static BigInteger rank(List<Integer> li) {
        if (li.size() == 0) return BigInteger.valueOf(-1);
        else return new BigInteger(join(li, "a"), 11);
    }
 
    public static List<Integer> unrank(BigInteger r) {
        if (r.equals(BigInteger.valueOf(-1))) return new ArrayList<Integer>();
        else return split(r.toString(11), 'a');
    }
 
    /* Each integer n in the list mapped to '1' plus n '0's. Empty list mapped to '0' */
    public static BigInteger rank2(List<Integer> li) {
        if (li.size() == 0) return BigInteger.ZERO;
        StringBuilder sb = new StringBuilder();
        for (Integer i : li) sb.append("1" + repeat("0", i));
        return new BigInteger(sb.toString(), 2);
    }
 
    public static List<Integer> unrank2(BigInteger r) {
        if (r.equals(BigInteger.ZERO)) return new ArrayList<Integer>();
        else return split(r.toString(2).substring(1), '1');
    }
 
    public static void main(String[] args) {
        List<Integer> li;
        BigInteger r;
        li = new ArrayList<Integer>();
        li.add(0);
        li.add(1);
        li.add(2);
        li.add(3);
        li.add(10);
        li.add(100);
        li.add(987654321);
        System.out.println("Before ranking   : " + li);
        r = rank(li);
        System.out.println("Rank = " + r);
        li = unrank(r);
        System.out.println("After unranking  : " + li);
 
        System.out.println("\nAlternative approach (not suitable for large numbers)...\n");
        li.remove(li.size() - 1);
        System.out.println("Before ranking   : " + li);
        r = rank2(li);
        System.out.println("Rank = " + r);
        li = unrank2(r);
        System.out.println("After unranking  : " + li);
 
        System.out.println();
        for (int i = 0; i <= 10; i++) {
            BigInteger bi = BigInteger.valueOf(i);
            li = unrank2(bi);
            System.out.println(String.format("%2d", i) + " -> " + String.format("%9s", li.toString()).replace(",", "") + " -> " + rank2(li));
        }
    }
 
    private static String join(List<Integer> li, String sep) {
        StringBuilder sb = new StringBuilder();
        for (Integer i : li) {
            if (sb.length() > 0) sb.append(sep);
            sb.append(i);
        }
        return sb.toString();
    }
 
    private static List<Integer> split(String s, char sep) {
        List<Integer> li = new ArrayList<Integer>();
        int start = 0;
        int end = s.indexOf(sep);
        while (end!= -1) {
            li.add(Integer.parseInt(s.substring(start, end)));
            start = end + 1;
            end = s.indexOf(sep, start);
        }
        li.add(Integer.parseInt(s.substring(start)));
        return li;
    }
 
    private static String repeat(String s, int n) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) sb.append(s);
        return sb.toString();
    }
}

