import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
 
public class MersennePrime {
 
    public static BigInteger newtonIteration(BigInteger n, BigInteger x0) {
        BigInteger x1 = n.divide(x0).add(x0).shiftRight(1);
        if (x0.equals(x1) || x0.equals(x1.subtract(BigInteger.ONE))) {
            return x0;
        }
        return newtonIteration(n, x1);
    }
 
    public static BigInteger sqrt(BigInteger value) {
        if (value.compareTo(BigInteger.ZERO) < 0) {
            throw new IllegalArgumentException("square root of negative numbers is not supported");
        }
 
        if (value.compareTo(BigInteger.TWO) < 0) {
            return value;
        }
        return newtonIteration(value, BigInteger.ONE);
    }
 
    public static boolean isPrime(BigInteger p) {
        if (p.equals(BigInteger.TWO)) {
            return true;
        } else if (p.compareTo(BigInteger.ONE) <= 0 || p.mod(BigInteger.TWO).equals(BigInteger.ZERO)) {
            return false;
        } else {
            BigInteger to = sqrt(p);
            for (BigInteger i = BigInteger.valueOf(3); i.compareTo(to) <= 0; i = i.add(BigInteger.TWO)) {
                if (p.mod(i).equals(BigInteger.ZERO)) {
                    return false;
                }
            }
            return true;
        }
    }
 
    public static boolean isMersennePrime(BigInteger p) {
        if (p.equals(BigInteger.TWO)) {
            return true;
        } else {
            BigInteger m_p = BigInteger.ONE.shiftLeft(p.intValue()).subtract(BigInteger.ONE);
            BigInteger s = BigInteger.valueOf(4);
            for (BigInteger i = BigInteger.valueOf(3); i.compareTo(p) <= 0; i = i.add(BigInteger.ONE)) {
                s = s.multiply(s).subtract(BigInteger.valueOf(2)).mod(m_p);
            }
            return s.equals(BigInteger.ZERO);
        }
    }
 
    public static void main(String[] args) {
        int upb = 5000;
        long tm = System.currentTimeMillis();
        System.out.println("Finding Mersenne primes in M[2.." + upb + "]:");
        System.out.println("M2");
        for (BigInteger p = BigInteger.valueOf(3); p.compareTo(BigInteger.valueOf(upb)) <= 0; p = p.add(BigInteger.TWO)) {
            if (isPrime(p) && isMersennePrime(p)) {
                System.out.println("M" + p);
            }
        }
