    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

public class DiceRoller {
    public static void main(String[] args) {
        Stats rolledCharacter = roll();

        while (rolledCharacter.total < 75 || rolledCharacter.rolls.stream().filter(a -> a >= 15).count() < 2) {
            rolledCharacter = roll();
        }

        System.out.println("The 6 random numbers generated are:");
        System.out.println(String.join(", ", rolledCharacter.rolls.toString()));
        System.out.println("Their sum is " + rolledCharacter.total + " and " + rolledCharacter.rolls.stream().filter(a -> a >= 15).count() + " of them are >= 15");
    }

    public static Stats roll() {
        Stats stats = new Stats();
        stats.rolls = new ArrayList<>();
        stats.total = 0;

        for (int i = 0; i <= 5; i++) {
            List<Integer> d6s = new ArrayList<>();

            for (int j = 0; j <= 3; j++) {
                d6s.add(new Random().nextInt(6) + 1);
            }

            Collections.sort(d6s);
            d6s.remove(0);
            int rollTotal = d6s.stream().mapToInt(Integer::intValue).sum();

            stats.rolls.add(rollTotal);
            stats.total += rollTotal;
        }

        return stats;
    }

    public static class Stats {
        public List<Integer> rolls;
        public int total;
    }
}

public static int fib(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be >= 0");
    }
    return fib1(n, 0, 1);
}
 
private static int fib1(int k, int a, int b) {
    if (k == 0) {
        return a;
    } else {
        return fib1(k - 1, b, a + b);
    }
}
 
public static void main(String[] args) {
    for (int i = 0; i <= 20; i++) {
        System.out.print(fib(i) + " ");
    }
    System.out.println();
}

