public final class Stack<E> {
    private final java.util.List<E> data = new java.util.ArrayList<>();
 
    public final int getSize() {
        return data.size();
    }
 
    public final boolean getEmpty() {
        return getSize() == 0;
    }
 
    public final void push(E element) {
        data.add(element);
    }
 
    public final E pop() {
        if (getEmpty()) {
            throw new RuntimeException("Can't pop elements from an empty stack");
        }
        return data.remove(data.size() - 1);
    }
 
    public final E getTop() {
        if (getEmpty()) {
            throw new RuntimeException("Empty stack can't have a top element");
        }
        return data.get(data.size() - 1);
    }
 
    public final void clear() {
        data.clear();
    }
 
    @Override
    public final java.lang.String toString() {
        return data.toString();
    }
}
 
public final class MainKt {
    public static final void main(java.lang.String[] args) {
        Stack<java.lang.Integer> s = new Stack<>();
        for (int i = 1; i <= 5; i++) {
            s.push(i);
        }
        System.out.println(s);
        System.out.println("Size of stack = " + s.getSize());
        System.out.print("Popping: ");
        for (int i = 1; i <= 3; i++) {
            System.out.print(s.pop() + " ");
        }
        System.out.println("\nRemaining on stack: " + s);
        System.out.println("Top element is now " + s.getTop());
        s.clear();
        System.out.println("After clearing, stack is " + (s.getEmpty()? "empty" : "not empty"));
        try {
            s.pop();
        }
        catch (java.lang.Exception e) {
            System.out.println(e.getMessage());
        }
    }
}

