import java.util.ArrayList;
import java.util.List;
 
public class DeBruijn {
 
    private static final String digits = "0123456789";
 
    public static String deBruijn(int k, int n) {
        String alphabet = digits.substring(0, k);
        byte[] a = new byte[k * n];
        List<Byte> seq = new ArrayList<>();
        db(1, 1, a, seq, k, n);
        StringBuilder buf = new StringBuilder();
        for (Byte i : seq) {
            buf.append(alphabet.charAt(i));
        }
        String b = buf.toString();
        return b + b.substring(0, n - 1); // as cyclic append first (n-1) digits
    }
 
    private static void db(int t, int p, byte[] a, List<Byte> seq, int k, int n) {
        if (t > n) {
            if (n % p == 0) {
                for (int i = 1; i <= p; i++) {
                    seq.add(a[i]);
                }
            }
        } else {
            a[t] = a[t - p];
            db(t + 1, p, a, seq, k, n);
            for (int j = a[t - p] + 1; j < k; j++) {
                a[t] = (byte) j;
                db(t + 1, t, a, seq, k, n);
            }
        }
    }
 
    private static boolean allDigits(String s) {
        for (char b : s.toCharArray()) {
            if (b < '0' || b > '9') {
                return false;
            }
        }
        return true;
    }
 
    private static void validate(String db) {
        int le = db.length();
        int[] found = new int[10000];
        List<String> errs = new ArrayList<>();
        // Check all strings of 4 consecutive digits within 'db'
        // to see if all 10,000 combinations occur without duplication.
        for (int i = 0; i < le - 3; i++) {
            String s = db.substring(i, i + 4);
            if (allDigits(s)) {
                int n = Integer.parseInt(s);
                found[n]++;
            }
        }
        for (int i = 0; i < 10000; i++) {
            if (found[i] == 0) {
                errs.add(String.format("    PIN number %04d missing", i));
            } else if (found[i] > 1) {
                errs.add(String.format("    PIN number %04d occurs %d times", i, found[i]));
            }
        }
        int lerr = errs.size();
        if (lerr == 0) {
            System.out.println("  No errors found");
        } else {
            String pl = "s";
            if (lerr == 1) {
                pl = "";
            }
            System.out.printf("  %d error%s found:\n", lerr, pl);
            System.out.println(String.join("\n", errs));
        }
    }
 
    private static String reverse(String s) {
        StringBuilder sb = new StringBuilder(s);
        return sb.reverse().toString();
    }
 
    public static void main(String[] args) {
        String db = deBruijn(10, 4);
        int le = db.length();
        System.out.println("The length of the de Bruijn sequence is " + le);
        System.out.println("\nThe first 130 digits of the de Bruijn sequence are:");
        System.out.println(db.substring(0, 130));
        System.out.println("\nThe last 130 digits of the de Bruijn sequence are:");
        System.out.println(db.substring(le - 130));
        System.out.println("\nValidating the de Bruijn sequence:");
        validate(db);
 
        System.out.println("\nValidating the reversed de Bruijn sequence:");
        String dbr = reverse(db);
        validate(dbr);
 
        char[] bytes = db.toCharArray();
        bytes[4443] = '.';
        db = new String(bytes);
        System.out.println("\nValidating the overlaid de Bruijn sequence:");
        validate(db);
    }
}

import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class Ramanujan {
    public static void main(String[] args) {
        System.out.println("Ramanujan's constant using formula f(N) = exp(pi*sqrt(N)):\n"
                + f(163).toString());
        System.out.println("\nResult with last four Heegner numbers:\n");
        List<Integer> heegnerNumbers = Arrays.asList(19, 43, 67, 163);
        heegnerNumbers.forEach(n -> {
            BigDecimal x = f(n);
            BigDecimal c = x.setScale(0, RoundingMode.CEILING);
            BigDecimal pc = x.divide(c, MathContext.DECIMAL128).multiply(new BigDecimal(100));
            System.out.println("f(" + n + ") = " + x + " = " + pc + "% of " + c);
        });
    }

    private static BigDecimal f(int n) {
        BigDecimal pi = BigDecimal.valueOf(Math.PI);
        return BigDecimal.valueOf(Math.exp(Math.sqrt(n) * pi.doubleValue()));
    }
}

import java.util.Scanner;
 
public class Euler0069 {
 
    public static int gcd(int n, int k) {
        if (n < k || k < 1) {
            throw new IllegalArgumentException("Need n >= k and k >= 1");
        }
 
        int s = 1;
        while ((n & 1) == 0 && (k & 1) == 0) {
            n >>= 1;
            k >>= 1;
            s <<= 1;
        }
 
        int t = n;
        if ((n & 1)!= 0) {
            t = -k;
        }
        while (t!= 0) {
            while ((t & 1) == 0) {
                t >>= 1;
            }
            if (t > 0) {
                n = t;
            } else {
                k = -t;
            }
            t = n - k;
        }
        return n * s;
    }
 
    public static int totient(int n) {
        int tot = 0;
        for (int k = 1; k <= n; k++) {
            if (gcd(n, k) == 1) {
                tot++;
            }
        }
        return tot;
    }
 
    public static void main(String[] args) {
        System.out.println(" n  phi   prime");
        System.out.println("---------------");
        int count = 0;
        for (int n = 1; n <= 25; n++) {
            int tot = totient(n);
            boolean isPrime = n - 1 == tot;
            if (isPrime) {
                count++;
            }
            System.out.printf("%2d   %2d   %b\n", n, tot, isPrime);
        }
        System.out.println("\nNumber of primes up to 25     = " + count);
        for (int n = 26; n <= 100000; n++) {
            int tot = totient(n);
            if (tot == n - 1) {
                count++;
            }
            if (n == 100 || n == 1000 || n % 10000 == 0) {
                System.out.printf("\nNumber of primes up to %-6d = %d\n", n, count);
            }
        }
    }
}

// Version 1.3.21
 
public class Main {
    public static void main(String[] args) {
        List<Integer> perfect = new ArrayList<>();
        int n = 1;
        while (perfect.size() < 20) {
            int tot = n;
            int sum = 0;
            while (tot!= 1) {
                tot = totient(tot);
                sum += tot;
            }
            if (sum == n) perfect.add(n);
            n += 2;
        }
        System.out.println("The first 20 perfect totient numbers are:");
        System.out.println(perfect);
    }
 
    public static int totient(int n) {
        int tot = n;
        int nn = n;
        int i = 2;
        while (i * i <= nn) {
            if (nn % i == 0) {
                while (nn % i == 0) nn /= i;
                tot -= tot / i;
            }
            if (i == 2) i = 1;
            i += 2;
        }
        if (nn > 1) tot -= tot / nn;
        return tot;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        int order = 3;
        String grain = "#";
        List<String> carpet = new ArrayList<>();
        carpet.add(grain);
        for (; order > 0; order--) {
            // repeat expression allows for multiple character
            // grain and for multi-byte UTF-8 characters.
            String hole = IntStream.range(0, grain.codePointCount(0, grain.length()))
                   .mapToObj(i -> " ").collect(Collectors.joining());
            List<String> middle = new ArrayList<>();
            for (int i = 0; i < carpet.size(); i++) {
                String s = carpet.get(i);
                middle.add(s + hole + s);
                carpet.set(i, s.repeat(3));
            }
            carpet.addAll(middle);
            carpet.addAll(carpet);
        }
        carpet.forEach(System.out::println);
    }
}

import java.util.regex.Pattern;
import java.util.regex.Matcher;
 
public class Main {
    private static final Pattern reg = Pattern.compile("([0-9]+(\\.[0-9]+)?)");
    private static String reverse(String s) {
        return new StringBuilder(s).reverse().toString();
    }
    private static String commatize(String s, int startIndex, int period, String sep) {
        if (startIndex < 0 || startIndex >= s.length() || period < 1 || sep.equals("")) {
            return s;
        }
        Matcher m = reg.matcher(s.substring(startIndex));
        if (!m.find()) {
            return s;
        }
        String[] splits = m.group().split("\\.");
        String ip = splits[0];
        if (ip.length() > period) {
            String pi = reverse(ip);
            for (int i = (pi.length() - 1) / period * period; i >= period; i -= period) {
                pi = pi.substring(0, i) + sep + pi.substring(i);
            }
            ip = reverse(pi);
        }
        if (m.group().contains(".")) {
            String dp = splits[1];
            if (dp.length() > period) {
                for (int i = (dp.length() - 1) / period * period; i >= period; i -= period) {
                    dp = dp.substring(0, i) + sep + dp.substring(i);
                }
            }
            ip += "." + dp;
        }
        return s.substring(0, startIndex) + s.substring(startIndex).replaceFirst(m.group(), ip);
    }
    public static void main(String[] args) {
        String[] tests = {
            "123456789.123456789",
            ".123456789",
            "57256.1D-4",
            "pi=3.14159265358979323846264338327950288419716939937510582097494459231",
            "The author has two Z$100000000000000 Zimbabwe notes (100 trillion).",
            "-in Aus$+1411.8millions",
            "===US$0017440 millions=== (in 2000 dollars)",
            "123.e8000 is pretty big.",
            "The land area of the earth is 57268900(29% of the surface) square miles.",
            "Ain't no numbers in this here words, nohow, no way, Jose.",
            "James was never known as 0000000007",
            " wrote: I believe there are " +
                "15747724136275002577605653961181555468044717914527116709366231425076185631031296" +
                " protons in the universe.",
            "   $-140000±100 millions.",
            "6/9/1946 was a good year for some.",
        };
        System.out.println(commatize(tests[0], 0, 2, "*"));
        System.out.println(commatize(tests[1], 0, 3, "-"));
        System.out.println(commatize(tests[2], 0, 4, "__"));
        System.out.println(commatize(tests[3], 0, 5, " "));
        System.out.println(commatize(tests[4], 0, 3, "."));
        for (String test : tests) {
            System.out.println(commatize(test, 0, 3, ","));
        }
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class Main {
	public static void main(String[] args) {
		for( int i=1; i<=22; i++ )
		{				
			List<Integer> f = Factorize(i);
			System.out.print( i + ":  " + f.get(0) );
			for( int j=1; j<f.size(); j++ )
			{
				System.out.print( " * " + f.get(j) );
			}
			System.out.println();
		}
	}
 
public static List<Integer> Factorize( int n )
{
	List<Integer> l = new ArrayList<Integer>();
 
if ( n == 1 )
{
	l.add(1);
}
else
{
	int k = 2;
	while( n > 1 ) 
	{
		while( n % k == 0 )
		{
			l.add( k );
			n /= k;
		}
		k++;
	}
}			
return l;
}	
}

import java.util.Arrays;
import java.util.stream.IntStream;

public class Cholesky {
    public static void main(String[] args) {
        double[][] arr3 = {{25, 15, -5}, {15, 18, 0}, {-5, 0, 11}};
        System.out.println(Arrays.deepToString(cholesky(arr3)));
        double[][] arr4 = {{18, 22, 54, 42}, {22, 70, 86, 62}, {54, 86, 174, 134}, {42, 62, 134, 106}};
        System.out.println(Arrays.deepToString(cholesky(arr4)));
    }

    public static double[][] cholesky(double[][] array) {
        double[][] zeros = new double[array.length][array.length];
        for (int i = 0; i < array.length; i++) {
            for (int j = 0; j < array.length; j++) {
                zeros[i][j] = 0;
            }
        }
        double[][] L = new double[array.length][array.length];
        for (int r = 0; r < array.length; r++) {
            for (int c = 0; c < array.length; c++) {
                double sum = 0;
                for (int i = 0; i < c; i++) {
                    sum += L[r][i] * L[c][i];
                }
                if (c < r + 1) {
                    if (r == c) {
                        L[r][c] = Math.sqrt(array[r][r] - sum);
                    } else {
                        L[r][c] = (array[r][c] - sum) / L[c][c];
                    }
                } else {
                    L[r][c] = 0;
                }
            }
        }
        return L;
    }
}

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Squeezer {
    public static void main(String[] args) {
        List<String> strings = Arrays.asList(
                "",
                "\"If I were two-faced, would I be wearing this one?\" ---  ",
                "..1111111111111111111111111111111111111111111111111111111111111117777888",
                "I never give 'em hell, I just tell the truth, and they think it's hell. ",
                "                                                   ---    ",
                "The better the 4-wheel drive, the further you'll be from help when ya get stuck!",
                "headmistressship",
                "aardvark",
                "😍😀🙌💃😍😍😍🙌");
        List<String> squeezers = Arrays.asList(",-,7,., -r,e,s,a,😍".split(","));
        for (int i = 0; i < strings.size(); i++) {
            String txt = strings.get(i);
            String chars = squeezers.get(i);
            System.out.println("\nOriginal Size: " + txt.length() + " «««" + txt + "»»»");
            for (String ch : chars.split(",")) {
                String this = "Squeezer '" + ch + "'";
                String sqz = squeezer(ch, txt);
                System.out.println(this + " Size: " + sqz.length() + " «««" + sqz + "»»»");
            }
        }
    }

    public static String squeezer(String s, String txt) {
        return Stream.of(txt.split("(?<=" + s + ")|(?=" + s + ")"))
               .filter(item ->!item.equals(s))
               .collect(Collectors.joining());
    }
}

import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
 
public class SameFringe {
 
    public static void main(String[] args) {
        Object a = new Object[] { 1, 2, 3, 4, 5, 6, 7, 8 };
        Object b = new Object[] { 1, new Object[] { 2, 3 }, new Object[] { 4, new Object[] { 5, new Object[] { 6, 7 }, 8 } } };
        Object c = new Object[] { new Object[] { new Object[] { 1, 2 }, 3 }, 4, 5, 6, 7, 8 };
 
        Object x = new Object[] { 1, 2, 3, 4, 5, 6, 7, 8, 9 };
        Object y = new Object[] { 0, 2, 3, 4, 5, 6, 7, 8 };
        Object z = new Object[] { 1, 2, new Object[] { 4, 3 }, 5, 6, 7, 8 };
 
        assert sameFringe(a, a);
        assert sameFringe(a, b);
        assert sameFringe(a, c);
 
        assert!sameFringe(a, x);
        assert!sameFringe(a, y);
        assert!sameFringe(a, z);
    }
 
    public static boolean sameFringe(Object tree1, Object tree2) {
        return all(node1EqualsNode2(fringe(tree1), fringe(tree2)));
    }
 
    public static boolean all(Iterator<?> iterator) {
        while (iterator.hasNext()) {
            if (!iterator.next().equals(true)) {
                return false;
            }
        }
        return true;
    }
 
    public static Iterator<Object> fringe(Object tree) {
        return new FringeIterator(tree);
    }
 
    public static Iterator<Object> node1EqualsNode2(Iterator<Object> node1Iterator, Iterator<Object> node2Iterator) {
        return new Node1EqualsNode2Iterator(node1Iterator, node2Iterator);
    }
 
    private static class FringeIterator implements Iterator<Object> {
 
        private final Iterator<Object> iterator;
 
        public FringeIterator(Object tree) {
            this.iterator = new FringeIterable(tree).iterator();
        }
 
        @Override
        public boolean hasNext() {
            return iterator.hasNext();
        }
 
        @Override
        public Object next() {
            return iterator.next();
        }
 
        @Override
        public void remove() {
            throw new UnsupportedOperationException();
        }
    }
 
    private static class FringeIterable implements Iterable<Object> {
 
        private final Object tree;
 
        public FringeIterable(Object tree) {
            this.tree = tree;
        }
 
        @Override
        public Iterator<Object> iterator() {
            return new FringeIterator(tree);
        }
    }
 
    private static class Node1EqualsNode2Iterator implements Iterator<Object> {
 
        private final Iterator<Object> node1Iterator;
        private final Iterator<Object> node2Iterator;
 
        public Node1EqualsNode2Iterator(Iterator<Object> node1Iterator, Iterator<Object> node2Iterator) {
            this.node1Iterator = node1Iterator;
            this.node2Iterator = node2Iterator;
        }
 
        @Override
        public boolean hasNext() {
            return node1Iterator.hasNext() && node2Iterator.hasNext();
        }
 
        @Override
        public Object next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }
            return node1Iterator.next().equals(node2Iterator.next());
        }
 
        @Override
        public void remove() {
            throw new UnsupportedOperationException();
        }
    }
}

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.Timer;
 
public class Polyspiral extends JPanel {
 
    private double inc;
 
    public Polyspiral() {
        setBackground(Color.WHITE);
        setSize(640, 640);
 
        Timer timer = new Timer(40, new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                inc = (inc + 0.05) % 360;
                repaint();
            }
        });
        timer.start();
    }
 
    private void drawSpiral(Graphics g, int len, double angleIncrement) {
        double x1 = getWidth() / 2;
        double y1 = getHeight() / 2;
        double angle = angleIncrement;
 
        for (int i = 0; i < 150; i++) {
            double x2 = x1 + Math.cos(angle) * len;
            double y2 = y1 - Math.sin(angle) * len;
            g.drawLine((int) x1, (int) y1, (int) x2, (int) y2);
            x1 = x2;
            y1 = y2;
 
            len += 3;
 
            angle = (angle + angleIncrement) % (Math.PI * 2);
        }
    }
 
    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        Graphics2D g2d = (Graphics2D) g;
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
 
        drawSpiral(g2d, 5, toRadians(inc));
    }
 
    private double toRadians(double angle) {
        return Math.PI * angle / 180.0;
    }
 
    public static void main(String[] args) {
        JFrame frame = new JFrame("Polyspiral");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.add(new Polyspiral());
        frame.pack();
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
    }
}

import java.util.Scanner;
 
public class Snusp {
    public static void main(String[] args) {
        int datalength = 100;
        String progstring = "       /==!/======ECHO==,==.==#\n" +
                "       |   |\n" +
                "$==>==@/==@/==<==#";
        int[] data = new int[datalength];
        int dp = 0;
        int ipx = 0;
        int ipy = 0;
        int direction = 0;
        String[] lines = progstring.split("\n");
        int lmax = 0;
        for (String line : lines) {
            if (line.length() > lmax) {
                lmax = line.length();
            }
        }
        for (int i = 0; i < lines.length; i++) {
            lines[i] = lines[i].substring(0, lmax);
        }
        for (int i = 0; i < lines.length; i++) {
            if (lines[i].indexOf("\$")!= -1) {
                ipx = lines[i].indexOf("\$");
                ipy = i;
            }
        }
        boolean running = true;
        while (running) {
            char cmdcode = lines[ipy].charAt(ipx);
            switch (cmdcode) {
                case '>':
                    dp++;
                    break;
                case '<':
                    dp--;
                    if (dp < 0) {
                        running = false;
                    }
                    break;
                case '+':
                    data[dp]++;
                    break;
                case '-':
                    data[dp]--;
                    break;
                case ',':
                    Scanner scanner = new Scanner(System.in);
                    data[dp] = scanner.next().charAt(0);
                    break;
                case '.':
                    System.out.print((char) data[dp]);
                    break;
                case '/':
                    direction = (direction + (direction % 2 == 0? 3 : 5)) % 4;
                    break;
                case '\\':
                    direction = (direction + (direction % 2 == 0? 1 : -1)) % 4;
                    break;
                case '!':
                    ipnext();
                    break;
                case '?':
                    if (data[dp] == 0) {
                        ipnext();
                    }
                    break;
                case '@':
                    // TODO
                    break;
                case '#':
                    // TODO
                    break;
                case '\n':
                    running = false;
                    break;
            }
            ipnext();
        }
        System.exit(data[dp]);
    }
 
    private static void ipnext() {
        // TODO
    }
}

import java.util.Random;
 
public class Unbiased {
	private static Random rand = new Random();
 
	public static boolean biased(int bias) {
		int r, rand_max = rand.nextInt();
		while ((r = rand.nextInt()) > rand_max);
		return r < rand_max / bias;
	}
 
	public static boolean unbiased(int bias) {
		int a;
		while ((a = biased(bias)) == biased(bias));
		return a;
	}
 
	public static void main(String[] args) {
		int b, n = 10000, cb, cu, i;
		for (b = 3; b <= 6; b++) {
			for (i = cb = cu = 0; i < n; i++) {
				cb += biased(b)? 1 : 0;
				cu += unbiased(b)? 1 : 0;
			}
			System.out.printf("bias %d: %5.3f%% vs %5.3f%%\n", b,
					100. * cb / n, 100. * cu / n);
		}
	}
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.function.Function;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;
 
public class GapPermutations {
 
    public static void main(String[] args) {
        test(5, 2, 1);
        test(5);
        test(5, 5);
        test(5, 1, 1, 1);
        test(10, 8);
        test(15, 2, 3, 2, 3);
        test(10, 4, 3);
        test(5, 2, 3);
    }
 
    private static void test(int cells, int... blocks) {
        int grpSize = blocks.length + 1;
        int numGaps = cells - Arrays.stream(blocks).sum();
 
        // Filter functions
        Function<List<Integer>, Boolean> sumsToTrg = list -> list.stream().mapToInt(i -> i).sum() == numGaps;
        Function<List<Integer>, Boolean> noInnerZero = list ->!list.subList(1, list.size() - 1).contains(0);
 
        // Output formatting
        Function<List<Integer>, List<Integer>> combine = list -> {
            List<Integer> result = new ArrayList<>();
            for (int i = 0; i < list.size(); i++) {
                result.add(list.get(i));
                if (i < blocks.length) {
                    result.add(blocks[i]);
                }
            }
            return result;
        };
        Function<List<Integer>, List<Integer>> choices = list -> {
            List<Integer> result = new ArrayList<>();
            for (int i = 0; i < list.size(); i++) {
                for (int j = 0; j < list.get(i); j++) {
                    result.add(i % 2 == 0? 0 : 1);
                }
            }
            return result;
        };
        Function<List<Integer>, String> arrJoin = list -> list.stream().map(Object::toString).collect(Collectors.joining(""));
        Function<List<Integer>, String> output = arrJoin.compose(choices).compose(combine);
 
        System.out.println("\n" + cells + " cells. Blocks: " + Arrays.toString(blocks));
        gapPerms(grpSize, numGaps, 0)
               .filter(noInnerZero)
               .filter(sumsToTrg)
               .map(output)
               .forEach(System.out::println);
    }
 
    private static List<List<Integer>> gapPerms(int grpSize, int numGaps, int minVal) {
        int maxVal = numGaps - grpSize * minVal + minVal;
        if (maxVal <= 0) {
            return grpSize == 2? Arrays.asList(Arrays.asList(0)) : new ArrayList<>();
        }
        return looper(mkArr(grpSize, minVal), maxVal, new ArrayList<>(), 0);
    }
 
    private static List<List<Integer>> looper(List<Integer> arr, int max, List<List<Integer>> acc, int idx) {
        if (idx!= arr.size()) {
            List<List<Integer>> b = looper(new ArrayList<>(arr), max, acc, idx + 1);
            if (b.get(0).get(idx)!= max) {
                b.get(0).set(idx, b.get(0).get(idx) + 1);
                acc.addAll(looper(new ArrayList<>(b.get(0)), max, acc, idx));
            }
        }
        return acc;
    }
 
    private static List<Integer> mkArr(int l, int f) {
        return IntStream.range(0, l).map(i -> f).boxed().collect(Collectors.toList());
    }
 
    private static int sumArr(List<Integer> arr) {
        return arr.stream().mapToInt(i -> i).sum();
    }
 
    private static List<Integer> zip(List<Integer> a, List<Integer> b) {
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < a.size(); i++) {
            result.add(a.get(i));
            if (i < b.size()) {
                result.add(b.get(i));
            }
        }
        return result;
    }
 
    private static List<Integer> zipArr(List<Integer> arr) {
        return a -> zip(a, arr);
    }
 
    private static boolean hasInner(int v) {
        return arr -> arr.subList(1, arr.size() - 1).contains(v);
    }
 
    private static int choose(int even, int odd) {
        return n -> n % 2 == 0? even : odd;
    }
 
    private static List<Integer> toBin(Function<Integer, Integer> f) {
        return arr -> arr.stream().flatMap(i -> Stream.generate(() -> f.apply(i)).limit(i)).collect(Collectors.toList());
    }
}

