import java.util.Random;
import java.util.Map;
import java.util.HashMap;
import java.util.List;
import java.util.ArrayList;
import java.util.Collections;
 
public class SeqMut {
 
    public static List<Map.Entry<Character, Integer>> basecount(String dna) {
        Map<Character, Integer> counts = new HashMap<>();
        for (char c : dna.toCharArray()) {
            counts.put(c, counts.getOrDefault(c, 0) + 1);
        }
        List<Map.Entry<Character, Integer>> list = new ArrayList<>(counts.entrySet());
        Collections.sort(list, (a, b) -> a.getKey().compareTo(b.getKey()));
        return list;
    }
 
    public static List<String> seq_split(String dna, int n) {
        List<String> parts = new ArrayList<>();
        for (int i = 0; i < dna.length(); i += n) {
            parts.add(dna.substring(i, Math.min(i + n, dna.length())));
        }
        return parts;
    }
 
    public static void seq_pp(String dna, int n) {
        for (int i = 0; i < dna.length(); i += n) {
            System.out.printf("%5d: %s\n", i, dna.substring(i, Math.min(i + n, dna.length())));
        }
        System.out.println("\n  BASECOUNT:");
        int tot = 0;
        for (Map.Entry<Character, Integer> entry : basecount(dna)) {
            System.out.printf("    %3s: %d\n", entry.getKey(), entry.getValue());
            tot += entry.getValue();
        }
        System.out.printf("    %3s= %d\n", "TOT", tot);
    }
 
    public static String seq_mutate(String dna, int count, String kinds, String choice) {
        Random random = new Random();
        for (int i = 0; i < count; i++) {
            char kind = kinds.charAt(random.nextInt(kinds.length()));
            int index = random.nextInt(dna.length());
            if (kind == 'I') {    // Insert
                dna = dna.substring(0, index) + choice.charAt(random.nextInt(choice.length())) + dna.substring(index);
            } else if (kind == 'D' && dna.length() > 0) {  // Delete
                dna = dna.substring(0, index) + dna.substring(index + 1);
            } else if (kind == 'S' && dna.length() > 0) {  // Substitute
                dna = dna.substring(0, index) + choice.charAt(random.nextInt(choice.length())) + dna.substring(index + 1);
            }
        }
        return dna;
    }
 
    public static void main(String[] args) {
        int length = 250;
        System.out.println("SEQUENCE:");
        String sequence = "ACGT";
        Random random = new Random();
        for (int i = 0; i < length; i++) {
            sequence += sequence.charAt(random.nextInt(sequence.length()));
        }
        seq_pp(sequence, 50);
        System.out.println("\n\nMUTATIONS:");
        String mseq = seq_mutate(sequence, 10, "IDSS", "ATCG");
        seq_pp(mseq, 50);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
 
public class Main {
 
    public static void main(String[] args) {
        long tm = System.currentTimeMillis();
        if (!find())
            System.out.println("Nothing found!");
        System.out.println("time=" + (System.currentTimeMillis() - tm) + " milliseconds");
    }
 
    public static boolean find() {
        final int MAX = 250;
        List<Double> pow5 = new ArrayList<>(MAX);
        for (int i = 1; i < MAX; i++)
            pow5.add((double)i * i * i * i * i);
        for (int x0 = 1; x0 < MAX; x0++) {
            for (int x1 = 1; x1 < x0; x1++) {
                for (int x2 = 1; x2 < x1; x2++) {
                    for (int x3 = 1; x3 < x2; x3++) {
                        double sum = pow5.get(x0) + pow5.get(x1) + pow5.get(x2) + pow5.get(x3);
                        if (Collections.binarySearch(pow5, sum) >= 0) {
                            System.out.println(x0 + " " + x1 + " " + x2 + " " + x3 + " " + Math.pow(sum, 1.0 / 5.0));
                            return true;
                        }
                    }
                }
            }
        }
        // not found
        return false;
    }
}

