import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class Program {
    static Tuple<Integer, Integer> DigitalRoot(long num) {
        int mp = 0;
        while (num > 9) {
            num = Arrays.stream(String.valueOf(num).split("")).mapToInt(Integer::parseInt).reduce(1, (a, b) -> a * b);
            mp++;
        }
        return new Tuple<>(mp, (int) num);
    }
    public static void main(String[] args) {
        for (long num : new long[] { 123321, 7739, 893, 899998 }) {
            var t = DigitalRoot(num);
            System.out.printf("%d has multiplicative persistence %d and multiplicative digital root %d%n", num, t.Item1, t.Item2);
        }
 
        final int twidth = 5;
        List<Long>[] table = new List[10];
        for (int i = 0; i < 10; i++)
            table[i] = new ArrayList<>();
        long number = -1;
        while (Arrays.stream(table).anyMatch(x -> x.size() < twidth)) {
            var t = DigitalRoot(++number);
            if (table[t.Item2].size() < twidth)
                table[t.Item2].add(number);
        }
        for (int i = 0; i < 10; i++)
            System.out.printf(" %d : [%s]%n", i, String.join(", ", table[i].stream().map(x -> x.toString()).collect(Collectors.toList())));
    }
}
 
class Tuple<T1, T2> {
    public final T1 Item1;
    public final T2 Item2;
    public Tuple(T1 item1, T2 item2) {
        Item1 = item1;
        Item2 = item2;
    }
}

