// version 1.1.2
 
public class NegBase {
 
    private static final String DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
 
    public static String encodeNegBase(long n, int b) {
        if (n == 0L) return "0";
        StringBuilder out = new StringBuilder();
        long nn = n;
        while (nn!= 0L) {
            int rem = (int)(nn % b);
            nn /= b;
            if (rem < 0) {
                nn++;
                rem -= b;
            }
            out.append(DIGITS.charAt(rem));
        }
        return out.reverse().toString();
    }
 
    public static long decodeNegBase(String ns, int b) {
        if (ns.equals("0")) return 0;
        long total = 0L;
        long bb = 1L;
        for (int i = ns.length() - 1; i >= 0; i--) {
            total += DIGITS.indexOf(ns.charAt(i)) * bb;
            bb *= b;
        }
        return total;
    }
 
    public static void main(String[] args) {
        long[] nbl = {10L, -2, 146L, -3, 15L, -10, -17596769891L, -62};
        for (int i = 0; i < nbl.length; i += 2) {
            String ns = encodeNegBase(nbl[i], (int)nbl[i+1]);
            System.out.printf("%12d encoded in base %-3d = %s\n", nbl[i], nbl[i+1], ns);
            long n  = decodeNegBase(ns, (int)nbl[i+1]);
            System.out.printf("%12s decoded in base %-3d = %d\n\n", ns, nbl[i+1], n);
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;
 
public class SafePrimes {
 
    public static void main(String[] args) {
        System.out.println("First 35 safe-primes:");
        System.out.println(Stream.iterate(2, i -> i + 1)
               .filter(SafePrimes::isSafePrime)
               .limit(35)
               .collect(Collectors.toList()));
        System.out.println(formatParts(1_000_000));
        System.out.println();
        System.out.println("First 40 unsafe-primes:");
        System.out.println(Stream.iterate(2, i -> i + 1)
               .filter(i ->!isSafePrime(i))
               .limit(40)
               .collect(Collectors.toList()));
        System.out.println(formatParts(10_000_000));
    }
 
    private static boolean isSafePrime(int n) {
        return isPrime(n) && isPrime((n - 1) / 2);
    }
 
    private static boolean isPrime(int n) {
        return IntStream.range(2, n)
               .noneMatch(i -> n % i == 0);
    }
 
    private static String formatParts(int n) {
        List<Integer> parts = new ArrayList<>();
        IntStream.range(2, n)
               .filter(SafePrimes::isSafePrime)
               .forEach(i -> parts.add(i));
        int safe = parts.size();
        int unsafe = n - safe - 1;
        return String.format("There are %d safes and %d unsafes below %d.", safe, unsafe, n);
    }
}

