import java.util.Arrays;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;

public class ThieleInterpolator {
    public static void main(String[] args) {
        // task 1: build 32 row trig table
        double[] xVal = IntStream.range(0, 32).mapToDouble(i -> i *.05).toArray();
        double[] tSin = Arrays.stream(xVal).map(Math::sin).toArray();
        double[] tCos = Arrays.stream(xVal).map(Math::cos).toArray();
        double[] tTan = Arrays.stream(xVal).map(Math::tan).toArray();
        // task 2: define inverses
        Function iSin = thieleInterpolator(tSin, xVal);
        Function iCos = thieleInterpolator(tCos, xVal);
        Function iTan = thieleInterpolator(tTan, xVal);
        // task 3: demonstrate identities
        System.out.println(String.format("%16.14f", 6 * iSin(.5)));
        System.out.println(String.format("%16.14f", 3 * iCos(.5)));
        System.out.println(String.format("%16.14f", 4 * iTan(1)));
    }

    public static Function thieleInterpolator(double[] x, double[] y) {
        double[][] ρ = new double[y.length][];
        for (int i = 0; i < y.length; i++) {
            ρ[i] = new double[y.length - i];
            Arrays.fill(ρ[i], y[i]);
        }
        for (int i = 0; i < ρ.length - 1; i++) {
            ρ[i][1] = (x[i] - x[i + 1]) / (ρ[i][0] - ρ[i + 1][0]);
        }
        for (int i = 2; i < ρ.length; i++) {
            for (int j = 0; j < ρ.length - i; j++) {
                ρ[j][i] = (x[j] - x[j + i]) / (ρ[j][i - 1] - ρ[j + 1][i - 1]) + ρ[j + 1][i - 2];
            }
        }
        double[] ρ0 = ρ[0];
        return new Function() {
            @Override
            public double apply(double xin) {
                double a = 0;
                for (int i = ρ0.length - 1; i > 1; i--) {
                    a = (xin - x[i - 1]) / (ρ0[i] - ρ0[i - 2] + a);
                }
                return y[0] + (xin - x[0]) / (ρ0[1] + a);
            }
        };
    }

    public interface Function {
        double apply(double x);
    }
}

package raster;

import java.util.Arrays;

public class Grmap {
    private int rows;
    private int cols;
    private short[] px;

    public Grmap(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.px = new short[rows * cols];
    }

    public int[] histogram(int bins) {
        if (bins <= 0) {
            bins = this.cols;
        }
        int[] h = new int[bins];
        Arrays.fill(h, 0);
        for (short p : this.px) {
            h[p * (bins - 1) / Short.MAX_VALUE]++;
        }
        return h;
    }

    public void threshold(short t) {
        for (int i = 0; i < this.px.length; i++) {
            if (this.px[i] < t) {
                this.px[i] = 0;
            } else {
                this.px[i] = Short.MAX_VALUE;
            }
        }
    }
}

