/* Algorithm complexity: n*log(n) */
import java.util.Arrays;
 
public class Main {
 
    public static void main(String[] args) {
        int[] triangle = {
            55,
            94, 48,
            95, 30, 96,
            77, 71, 26, 67,
            97, 13, 76, 38, 45,
            7, 36, 79, 16, 37, 68,
            48, 7, 9, 18, 70, 26, 6,
            18, 72, 79, 46, 59, 79, 29, 90,
            20, 76, 87, 11, 32, 7, 7, 49, 18,
            27, 83, 58, 35, 71, 11, 25, 57, 29, 85,
            14, 64, 36, 96, 27, 11, 58, 56, 92, 18, 55,
            2, 90, 3, 60, 48, 49, 41, 46, 33, 36, 47, 23,
            92, 50, 48, 2, 36, 59, 42, 79, 72, 20, 82, 77, 42,
            56, 78, 38, 80, 39, 75, 2, 71, 66, 66, 1, 3, 55, 72,
            44, 25, 67, 84, 71, 67, 11, 61, 40, 57, 58, 89, 40, 56, 36,
            85, 32, 25, 85, 57, 48, 84, 35, 47, 62, 17, 1, 1, 99, 89, 52,
            6, 71, 28, 75, 94, 48, 37, 10, 23, 51, 6, 48, 53, 18, 74, 98, 15,
            27, 2, 92, 23, 8, 71, 76, 84, 15, 52, 92, 63, 81, 10, 44, 10, 69, 93
        };
 
        final int size = triangle.length;
        final int tn = (int)Math.sqrt(2.0 * size);
        assert(tn * (tn + 1) == 2 * size);    // size should be a triangular number
 
        // walk backward by rows, replacing each element with max attainable therefrom
        for (int n = tn - 1; n > 0; --n)   // n is size of row, note we do not process last row
            for (int k = (n * (n-1)) / 2; k < (n * (n+1)) / 2; ++k) // from the start to the end of row
                triangle[k] += Math.max(triangle[k + n], triangle[k + n + 1]);
 
        System.out.println("Maximum total: " + triangle[0]);
    }
}

import java.util.*;
import java.lang.*;
import java.io.*;
 
class Ideone
{
	public static double agm(double a, double g)		//ARITHMETIC GEOMETRIC MEAN
	{	double epsilon = 1.0E-16,a1,g1;
		if(a*g<0.0)
		{	System.out.println("Couldn't find arithmetic-geometric mean of these numbers\n");
			System.exit(1);
		}
		while(Math.abs(a-g)>epsilon)
		{	a1 = (a+g)/2.0;
			g1 = Math.sqrt(a*g);
			a = a1;
			g = g1;
		}
		return a;
	}
 
public static void main (String[] args) throws java.lang.Exception
{
	double x, y;
	Scanner sc = new Scanner(System.in);
	System.out.println("Enter X and Y: ");	//Enter two numbers
	x = sc.nextDouble();
	y = sc.nextDouble();
	System.out.println("\nThe Arithmetic-Geometric Mean of "+x+" and "+y+" is "+agm(x, y));
}
}

import java.math.BigInteger;

public class Lah {
    public static BigInteger factorial(BigInteger n) {
        if (n.equals(BigInteger.ZERO)) return BigInteger.ONE;
        if (n.equals(BigInteger.ONE)) return BigInteger.ONE;
        BigInteger prod = BigInteger.ONE;
        BigInteger num = n;
        while (num.compareTo(BigInteger.ONE) > 0) {
            prod = prod.multiply(num);
            num = num.subtract(BigInteger.ONE);
        }
        return prod;
    }

    public static BigInteger lah(BigInteger n, BigInteger k) {
        if (k.equals(BigInteger.ONE)) return factorial(n);
        if (k.equals(n)) return BigInteger.ONE;
        if (k.compareTo(n) > 0) return BigInteger.ZERO;
        if (k.compareTo(BigInteger.ONE) < 0 || n.compareTo(BigInteger.ONE) < 0) return BigInteger.ZERO;
        return (factorial(n).multiply(factorial(n.subtract(BigInteger.ONE)))).divide(factorial(k).multiply(factorial(k.subtract(BigInteger.ONE)))).divide(factorial(n.subtract(k)));
    }

    public static void main(String[] args) {
        System.out.println("Unsigned Lah numbers: L(n, k):");
        System.out.print("n/k ");
        for (int i = 0; i <= 12; i++) {
            System.out.printf("%10d ", i);
        }
        System.out.println();
        for (int row = 0; row <= 12; row++) {
            System.out.printf("%-3d", row);
            for (int i = 0; i <= row; i++) {
                BigInteger l = lah(BigInteger.valueOf(row), BigInteger.valueOf(i));
                System.out.printf("%11d", l);
            }
            System.out.println();
        }
        System.out.println("\nMaximum value from the L(100, *) row:");
        System.out.println(java.util.stream.IntStream.range(0, 101).mapToObj(i -> lah(BigInteger.valueOf(100), BigInteger.valueOf(i))).max(java.util.Comparator.naturalOrder()).get());
    }
}

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
 
public class Isbn13 {
    public static void main(String[] args) {
        List<String> isbns = Arrays.asList("978-1734314502", "978-1734314509", "978-1788399081", "978-1788399083");
        for (String isbn : isbns) {
            String res = "bad";
            if (checkIsbn13(isbn)) {
                res = "good";
            }
            System.out.printf("%s: %s\n", isbn, res);
        }
    }
 
    public static boolean checkIsbn13(String isbn) {
        // remove any hyphens or spaces
        isbn = isbn.replaceAll("-", "").replaceAll(" ", "");
        // check length == 13
        int le = isbn.length();
        if (le!= 13) {
            return false;
        }
        // check only contains digits and calculate weighted sum
        int sum = 0;
        for (int i = 0; i < isbn.length(); i++) {
            char c = isbn.charAt(i);
            if (c < '0' || c > '9') {
                return false;
            }
            if (i % 2 == 0) {
                sum += c - '0';
            } else {
                sum += 3 * (c - '0');
            }
        }
        return sum % 10 == 0;
    }
}

import java.math.BigInteger;

public class Factorial {
    public static void main(String[] args) {
        System.out.print("!0 through !10: 0");
        BigInteger one = BigInteger.ONE;
        BigInteger n = BigInteger.ONE;
        BigInteger f = BigInteger.ONE;
        BigInteger l = BigInteger.ONE;
        Runnable next = () -> { f = f.multiply(n); l = l.add(f); n = n.add(one); };
        while (true) {
            next.run();
            System.out.print(" " + l);
            if (n.equals(BigInteger.TEN)) {
                break;
            }
        }
        System.out.println();
        while (true) {
            for (int i = 0; i < 10; i++) {
                next.run();
            }
            System.out.printf("!%d: %d\n", n, l);
            if (n.equals(BigInteger.valueOf(110))) {
                break;
            }
        }
        System.out.println("Lengths of !1000 through !10000 by thousands:");
        for (int i = 110; i < 1000; i++) {
            next.run();
        }
        while (true) {
            System.out.print(" " + l.toString().length());
            if (n.equals(BigInteger.valueOf(10000))) {
                break;
            }
            for (int i = 0; i < 1000; i++) {
                next.run();
            }
        }
        System.out.println();
    }
}

import java.util.Scanner;

class SubStringTestClass
{
   public static int CountSubStrings(String testString, String testSubstring)
   {
        int count = 0;
 
        if (testString.contains(testSubstring))
        {
            for (int i = 0; i < testString.length(); i++)
            {
                if (testString.substring(i).length() >= testSubstring.length())
                {
                    boolean equals = testString.substring(i, testSubstring.length()).equals(testSubstring);
                    if (equals)
                    {
                        count++;
                        i += testSubstring.length() - 1;  // Fix: Don't count overlapping matches
                    }
                }
            }
        }
        return count;
   }
}

public static boolean perf1(int n) {
    int sum = 0;
    for (int i = 1; i < n; i++) {
        if (n % i == 0) {
            sum += i;
        }
    }
    return sum == n;
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
 
public class InsertionSort {
 
    public static void main(String[] args) {
        List<String> items = new ArrayList<>();
        items.add("violet");
        items.add("red");
        items.add("green");
        items.add("indigo");
        items.add("blue");
        items.add("yellow");
        items.add("orange");
        List<String> ans = order(items);
        System.out.println(ans);
    }
 
    public static List<String> order(List<String> items) {
        List<String> ordered = new ArrayList<>();
        int q = 0;
        for (String item : items) {
            q = _insort_right(ordered, item, q);
        }
        return ordered;
    }
 
    public static int _insort_right(List<String> a, String x, int q) {
        int lo = 0;
        int hi = a.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            q++;
            Scanner scanner = new Scanner(System.in);
            System.out.print(q + ": IS " + x + " LESS-THAN " + a.get(mid) + "? y/n: ");
            String less = scanner.nextLine();
            if (less.equals("y")) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        a.add(lo, x);
        return q;
    }
}

import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Level;
import java.util.logging.Logger;
import org.apache.directory.api.ldap.model.exception.LdapException;
import org.apache.directory.ldap.client.api.LdapNetworkConnection;
 
public class LDAP {
    public void run() {
        LdapNetworkConnection connection = null;
        try {
            if (info) {
                log.info("LDAP Connection to " + hostname + " on port " + port);
            }
            connection = new LdapNetworkConnection(hostname, Integer.parseInt(port));
            try {
                if (info) {
                    log.info("LDAP bind");
                }
                connection.bind();
            } catch (LdapException e) {
                log.severe(e.toString());
            }
            try {
                if (info) {
                    log.info("LDAP unbind");
                }
                connection.unBind();
            } catch (LdapException e) {
                log.severe(e.toString());
            }
        } finally {
            try {
                if (info) {
                    log.info("LDAP close connection");
                }
                connection.close();
            } catch (IOException e) {
                log.severe(e.toString());
            }
        }
    }
 
    private final Logger log = Logger.getLogger(LDAP.class.getName());
    private final boolean info = log.isLoggable(Level.INFO);
    private final String hostname;
    private final String port;
 
    public LDAP(Map<String, String> map) {
        hostname = map.get("hostname");
        port = map.get("port");
    }
 
    public static void main(String[] args) {
        new LDAP(new HashMap<String, String>() {{
            put("hostname", "localhost");
            put("port", "10389");
        }}).run();
    }
}

