import java.util.HashMap;
import java.util.Map;
 
public class ShannonEntropy {
    public static double log2(double d) {
        return Math.log(d) / Math.log(2.0);
    }
 
    public static double shannon(String s) {
        Map<Character, Integer> counters = new HashMap<>();
        for (char c : s.toCharArray()) {
            if (counters.containsKey(c)) counters.put(c, counters.get(c) + 1);
            else counters.put(c, 1);
        }
        double nn = s.length();
        double sum = 0.0;
        for (char key : counters.keySet()) {
            double term = counters.get(key) / nn;
            sum += term * log2(term);
        }
        return -sum;
    }
 
    public static void main(String[] args) {
        String[] samples = {
            "1223334444",
            "1223334444555555555", 
            "122333", 
            "1227774444",
            "aaBBcccDDDD",
            "1234567890abcdefghijklmnopqrstuvwxyz",
            "Rosetta Code"
        };
        System.out.println("            String                             Entropy");
        System.out.println("------------------------------------      ------------------");
        for (String sample : samples) {
            System.out.printf("%36s  ->  %18.16f%n", sample, shannon(sample));
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
 
public class LineSimplification {
    private static class Point {
        public double x;
        public double y;
 
        public Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }
 
    private static double perpendicularDistance(Point pt, Point lineStart, Point lineEnd) {
        double dx = lineEnd.x - lineStart.x;
        double dy = lineEnd.y - lineStart.y;
 
        // Normalize
        double mag = Math.sqrt(dx * dx + dy * dy);
        if (mag > 0.0) {
            dx /= mag;
            dy /= mag;
        }
        double pvx = pt.x - lineStart.x;
        double pvy = pt.y - lineStart.y;
 
        // Get dot product (project pv onto normalized direction)
        double pvdot = dx * pvx + dy * pvy;
 
        // Scale line direction vector and subtract it from pv
        double ax = pvx - pvdot * dx;
        double ay = pvy - pvdot * dy;
 
        return Math.sqrt(ax * ax + ay * ay);
    }
 
    private static void ramerDouglasPeucker(List<Point> pointList, double epsilon, List<Point> output) {
        if (pointList.size() < 2) {
            throw new IllegalArgumentException("Not enough points to simplify");
        }
 
        // Find the point with the maximum distance from line between the start and end
        double dmax = 0.0;
        int index = 0;
        int end = pointList.size() - 1;
        for (int i = 1; i < end; ++i) {
            double d = perpendicularDistance(pointList.get(i), pointList.get(0), pointList.get(end));
            if (d > dmax) {
                index = i;
                dmax = d;
            }
        }
 
        // If max distance is greater than epsilon, recursively simplify
        if (dmax > epsilon) {
            List<Point> recResults1 = new ArrayList<>();
            List<Point> recResults2 = new ArrayList<>();
            List<Point> firstLine = pointList.subList(0, index + 1);
            List<Point> lastLine = pointList.subList(index, pointList.size());
            ramerDouglasPeucker(firstLine, epsilon, recResults1);
            ramerDouglasPeucker(lastLine, epsilon, recResults2);
 
            // build the result list
            output.addAll(recResults1.subList(0, recResults1.size() - 1));
            output.addAll(recResults2);
            if (output.size() < 2) throw new RuntimeException("Problem assembling output");
        }
        else {
            // Just return start and end points
            output.clear();
            output.add(pointList.get(0));
            output.add(pointList.get(pointList.size() - 1));
        }
    }
 
    public static void main(String[] args) {
        List<Point> pointList = new ArrayList<>();
        pointList.add(new Point(0.0, 0.0));
        pointList.add(new Point(1.0, 0.1));
        pointList.add(new Point(2.0, -0.1));
        pointList.add(new Point(3.0, 5.0));
        pointList.add(new Point(4.0, 6.0));
        pointList.add(new Point(5.0, 7.0));
        pointList.add(new Point(6.0, 8.1));
        pointList.add(new Point(7.0, 9.0));
        pointList.add(new Point(8.0, 9.0));
        pointList.add(new Point(9.0, 9.0));
        List<Point> pointListOut = new ArrayList<>();
        ramerDouglasPeucker(pointList, 1.0, pointListOut);
        System.out.println("Points remaining after simplification:");
        pointListOut.forEach(p -> System.out.println(p));
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class PalindromicGapfulNumbers {
 
    public static void main(String[] args) {
        int count = 20;
        System.out.println("First 20 palindromic gapful numbers ending with:");
        for (int digit = 1; digit <= 9; digit++) {
            System.out.println(digit + " : " + digitscount(digit, count));
        }
 
        count = 100;
        System.out.println("\nLast 15 of first 100 palindromic gapful numbers ending in:");
        for (int digit = 1; digit <= 9; digit++) {
            System.out.println(digit + " : " + digitscount(digit, count).subList(count - 15, count));
        }
 
        count = 1000;
        System.out.println("\nLast 10 of first 1000 palindromic gapful numbers ending in:");
        for (int digit = 1; digit <= 9; digit++) {
            System.out.println(digit + " : " + digitscount(digit, count).subList(count - 10, count));
        }
    }
 
    private static List<Integer> digitscount(int digit, int count) {
        int pow = 2;
        List<Integer> nums = new ArrayList<>();
        while (nums.size() < count) {
            nums.addAll(palindromesgapful(digit, pow));
            pow++;
        }
        return nums;
    }
 
    private static List<Integer> palindromesgapful(int digit, int pow) {
        int r1 = digit * (int) Math.pow(10, pow) + 1;
        int r2 = (int) Math.pow(10, pow) * (digit + 1);
        int nn = digit * 11;
        return IntStream.range(r1, r2)
               .filter(i -> {
                    String n = String.valueOf(i);
                    return n.equals(new StringBuilder(n).reverse().toString()) && i % nn == 0;
                })
               .boxed()
               .collect(Collectors.toList());
    }
}

import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;
 
public class LexicographicOrder {
 
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int[] numbers = {0, 5, 13, 21, -22};
        System.out.println("In lexicographical order:");
        for (int i = 0; i < 5; ++i) {
            int n = numbers[i];
            int k = n;
            if (k < 1) {
                k = 2 - k;
            }
            int[] ints = new int[k];
            lexOrder(n, ints);
            System.out.print(String.format("%3d: [", n));
            for (int j = 0; j < k; ++j) {
                System.out.print(String.format("%d ", ints[j]));
            }
            System.out.println("\b]");
        }
    }
 
    public static void lexOrder(int n, int[] ints) {
        String[] strs;
        int first = 1, last = n, k = n;
        if (n < 1) {
            first = n;
            last = 1;
            k = 2 - n;
        }
        strs = new String[k];
        for (int i = first; i <= last; ++i) {
            if (i >= 1) {
                strs[i - first] = String.valueOf(i);
            } else if (i == 0) {
                strs[i - first] = "0";
            } else {
                strs[i - first] = String.valueOf(i);
            }
        }
        Arrays.sort(strs, new Comparator<String>() {
            @Override
            public int compare(String a, String b) {
                return a.compareTo(b);
            }
        });
        for (int i = 0; i < k; ++i) {
            ints[i] = Integer.parseInt(strs[i]);
        }
    }
}

import java.util.ArrayList;
