import java.util.Arrays;
 
public class StoogeSort {
 
    public static void main(String[] args) {
        int[] array = {1,4,5,3,-6,3,7,10,-2,-5};
        System.out.println(Arrays.toString(stoogesort(array)));
    }
 
    public static int[] stoogesort(int[] array) {
        return stoogesort(array, 0, array.length-1);
    }
 
    public static int[] stoogesort(int[] array, int i, int j) {
        if (array[j] < array[i]) {
            int temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
        if (j - i > 1) {
            int t = (j - i + 1)/3;
            stoogesort(array, i, j-t);
            stoogesort(array, i+t, j);
            stoogesort(array, i, j-t);
        }
        return array;
    }
}

