import java.io.File
 
fun merge2(inputFile1: String, inputFile2: String, outputFile: String) {
    val file1 = File(inputFile1)
    val file2 = File(inputFile2)
    require(file1.exists() && file2.exists()) { "Both input files must exist" }
    val reader1 = file1.bufferedReader()
    val reader2 = file2.bufferedReader()
    val writer  = File(outputFile).printWriter()
    var line1 = reader1.readLine()
    var line2 = reader2.readLine()
    while (line1!= null && line2!= null) {
        if (line1 <= line2) {
            writer.println(line1)
            line1 = reader1.readLine()
        }
        else {
            writer.println(line2)
            line2 = reader2.readLine()
        }
    }
    while (line1!= null) {
        writer.println(line1)
        line1 = reader1.readLine()
    }
    while (line2!= null) {
        writer.println(line2)
        line2 = reader2.readLine()
    }
    reader1.close()
    reader2.close()
    writer.close()
}
 
fun mergeN(inputFiles: List<String>, outputFile: String) {
    val files = inputFiles.map { File(it) }
    require(files.all { it.exists() }) { "All input files must exist" }
    val readers = files.map { it.bufferedReader() }
    val writer  = File(outputFile).printWriter()
    var lines = readers.map { it.readLine() }.toMutableList()
    while (lines.any { it!= null }) {
        val line = lines.filterNotNull().min()
        val index = lines.indexOf(line)
        writer.println(line)
        lines[index] = readers[index].readLine()
    }
    readers.forEach { it.close() }
    writer.close()
}
 
fun main(args:Array<String>) {
    val files = listOf("merge1.txt", "merge2.txt", "merge3.txt", "merge4.txt")
    merge2(files[0], files[1], "merged2.txt")
    mergeN(files, "mergedN.txt")
    // check it worked
    println(File("merged2.txt").readText()) 
    println(File("mergedN.txt").readText())
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Program {
    static List<Long> primes = new ArrayList<Long>();

    public static void main(String[] args) {
        primes.add(3L);
        primes.add(5L);
        final int cutOff = 200;
        final int bigUn = 100000;
        final int chunks = 50;
        final int little = bigUn / chunks;
        final String tn = " cuban prime";
        System.out.printf("The first %,d%s%n", cutOff, tn);
        int c = 0;
        boolean showEach = true;
        long u = 0, v = 1;
        long st = System.currentTimeMillis();
        for (long i = 1; i <= Long.MAX_VALUE; i++) {
            boolean found = false;
            int mx = (int) Math.ceil(Math.sqrt(v += (u += 6)));
            for (Long item : primes) {
                if (item > mx)
                    break;
                if (v % item == 0) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                c += 1;
                if (showEach) {
                    for (long z = primes.get(primes.size() - 1) + 2; z <= v - 2; z += 2) {
                        boolean fnd = false;
                        for (Long item : primes) {
                            if (item > mx)
                                break;
                            if (z % item == 0) {
                                fnd = true;
                                break;
                            }
                        }
                        if (!fnd)
                            primes.add(z);
                    }
                    primes.add(v);
                    System.out.printf("%11d", v);
                    if (c % 10 == 0)
                        System.out.println();
                    if (c == cutOff) {
                        showEach = false;
                        System.out.printf("\nProgress to the %,dth%s: ", bigUn, tn);
                    }
                }
                if (c % little == 0) {
                    System.out.print(".");
                    if (c == bigUn)
                        break;
                }
            }
        }
        System.out.printf("\nThe %,dth%s is %,17d%n", c, tn, v);
        System.out.printf("Computation time was %d seconds%n", (System.currentTimeMillis() - st) / 1000);
        if (System.getProperty("java.vendor").toLowerCase().contains("microsoft")) {
            Scanner scanner = new Scanner(System.in);
            scanner.nextLine();
        }
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
 
public class Dijkstra {
 
    public static void main(String[] args) {
        List<Edge> edges = new ArrayList<>();
        edges.add(new Edge("a", "b", 7));
        edges.add(new Edge("a", "c", 9));
        edges.add(new Edge("a", "f", 14));
        edges.add(new Edge("b", "c", 10));
        edges.add(new Edge("b", "d", 15));
        edges.add(new Edge("c", "d", 11));
        edges.add(new Edge("c", "f", 2));
        edges.add(new Edge("d", "e", 6));
        edges.add(new Edge("e", "f", 9));
 
        Graph graph = new Graph(edges);
        System.out.println(graph.dijkstra("a", "e"));
    }
 
    static class Graph {
        private List<Edge> edges;
        private Set<String> vertices;
 
        public Graph(List<Edge> edges) {
            this.edges = edges;
            this.vertices = new HashSet<>();
            for (Edge edge : edges) {
                vertices.add(edge.start);
                vertices.add(edge.end);
            }
        }
 
        public List<String> dijkstra(String source, String dest) {
            assert vertices.contains(source);
            Map<String, Integer> dist = new HashMap<>();
            Map<String, String> previous = new HashMap<>();
            for (String vertex : vertices) {
                dist.put(vertex, Integer.MAX_VALUE);
            }
            dist.put(source, 0);
            Queue<String> q = new LinkedList<>(vertices);
            Map<String, Set<Edge>> neighbours = new HashMap<>();
            for (String vertex : vertices) {
                neighbours.put(vertex, new HashSet<>());
            }
            for (Edge edge : edges) {
                neighbours.get(edge.start).add(edge);
                neighbours.get(edge.end).add(new Edge(edge.end, edge.start, edge.cost));
            }
 
            while (!q.isEmpty()) {
                String u = q.stream().min((v1, v2) -> dist.get(v1) - dist.get(v2)).get();
                q.remove(u);
                if (dist.get(u) == Integer.MAX_VALUE || u.equals(dest)) {
                    break;
                }
                for (Edge edge : neighbours.get(u)) {
                    String v = edge.end;
                    int alt = dist.get(u) + edge.cost;
                    if (alt < dist.get(v)) {
                        dist.put(v, alt);
                        previous.put(v, u);
                    }
                }
            }
 
            List<String> s = new LinkedList<>();
            String u = dest;
            while (previous.get(u)!= null) {
                s.add(0, u);
                u = previous.get(u);
            }
            s.add(0, u);
            return s;
        }
    }
 
    static class Edge {
        String start;
        String end;
        int cost;
 
        public Edge(String start, String end, int cost) {
            this.start = start;
            this.end = end;
            this.cost = cost;
        }
    }
}

