def binomialCoeff(n, k):
    result = 1
    for i in range(1, k+1):
        result = result * (n-i+1) / i
    return result
 
if __name__ == "__main__":
    print(binomialCoeff(5, 3))

import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
 
public class IPAddr {
    private static final String[] TESTCASES = {
            "127.0.0.1",                "127.0.0.1:80",
            "::1",                      "[::1]:80",
            "2605:2700:0:3::4713:93e3", "[2605:2700:0:3::4713:93e3]:80"
    };
    private static final String[] HEADER = {
            "String", "Address", "Port", "Family", "Hex"
    };
    private static final String[] EMPTY_ROW = {
            "", "", "", "", ""
    };
    private static final Pattern PATTERN = Pattern.compile(
            "\\A\\[(?<address>.*)\\]:(?<port>\\d+)\\z|\\A(?<address>[^:]+):(?<port>\\d+)\\z");
 
    public static void main(String[] args) {
        List<String[]> output = new ArrayList<>();
        output.add(HEADER);
        output.add(EMPTY_ROW);
 
        for (String str : TESTCASES) {
            Matcher matcher = PATTERN.matcher(str);
            if (matcher.matches()) {
                String address = matcher.group("address");
                String port = matcher.group("port");
                InetAddress inetAddress = null;
                try {
                    inetAddress = InetAddress.getByName(address);
                } catch (UnknownHostException e) {
                    e.printStackTrace();
                }
                String family = "IPv4";
                if (inetAddress.getAddress().length == 16) {
                    family = "IPv6";
                }
                String[] row = {str, inetAddress.getHostAddress(), port, family, Long.toHexString(inetAddress.hashCode())};
                output.add(row);
            }
        }
 
        outputTable(output);
    }
 
    private static void outputTable(List<String[]> rows) {
        int[] widths = new int[rows.get(0).length];
        for (String[] row : rows) {
            for (int i = 0; i < row.length; i++) {
                widths[i] = Math.max(widths[i], row[i].length());
            }
        }
        String format = "";
        for (int width : widths) {
            format += "%" + width + "s\t";
        }
        for (String[] row : rows) {
            System.out.println(String.format(format, row));
        }
    }
}

import java.math.BigInteger;
import java.util.Scanner;

public class Test {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        test(-2);
        test(-1);
        test(0);
        test(1);
        test(2);
        testBig("-222222222222222222222222222222222222");
        testBig("-1");
        testBig("0");
        testBig("1");
        testBig("222222222222222222222222222222222222");
    }

    public static void test(int n) {
        System.out.printf("Testing integer %3d:  ", n);
        // & 1 is a good way to test
        if (n & 1 == 0) {
            System.out.print("even ");
        } else {
            System.out.print(" odd ");
        }
        // Careful when using %: negative n % 2 returns -1.  So, the code below
        // works, but can be broken by someone thinking they can reverse the
        // test by testing n % 2 == 1.  The valid reverse test is n % 2 != 0.
        if (n % 2 == 0) {
            System.out.println("even");
        } else {
            System.out.println(" odd");
        }
    }

    public static void testBig(String s) {
        BigInteger b = new BigInteger(s);
        System.out.printf("Testing big integer %v:  ", b);
        // the Bit function is the only sensible test for big ints.
        if (b.testBit(0) == 0) {
            System.out.println("even");
        } else {
            System.out.println("odd");
        }
    }
}

import java.util.Random;
import java.util.Scanner;
import java.util.Stack;
import java.util.Set;
import java.util.HashSet;
import java.util.function.BiFunction;
 
public class RPNParse
{
  Stack<Double> stk = new Stack<Double>();
  Set<Integer> digits = new HashSet<Integer>();
 
  void op(BiFunction<Double, Double, Double> f)
  {
    if(stk.size() < 2)
      throw new RuntimeException("Improperly written expression");
    double b = stk.pop();
    double a = stk.pop();
    stk.push(f.apply(a, b));
  }
 
  void parse(char c)
  {
    if(c >= '0' && c <= '9')
    {
      stk.push(c - '0');
      digits.add(c - '0');
    }
    else if(c == '+')
      op((a, b) -> a+b);
    else if(c == '-')
      op((a, b) -> a-b);
    else if(c == '*')
      op((a, b) -> a*b);
    else if(c == '/')
      op((a, b) -> a/b);
  }
 
  void parse(String s)
  {
    for(int i = 0; i < s.length(); ++i)
      parse(s.charAt(i));
  }
 
  double getResult()
  {
    if(stk.size()!= 1)
      throw new RuntimeException("Improperly written expression");
    return stk.pop();
  }
 
  public static void main(String[] args)
  {
    Random rnd = new Random();
 
    Set<Integer> digits = new HashSet<Integer>();
    System.out.print("Make 24 with the digits: ");
    for(int i = 0; i < 4; ++i)
    {
      int n = rnd.nextInt(9) + 1;
      System.out.print(" " + n);
      digits.add(n);
    }
    System.out.println();
 
    RPNParse parser = new RPNParse();
 
    try
    {
      Scanner input = new Scanner(System.in);
      parser.parse(input.nextLine());
 
      if(!digits.equals(parser.digits))
        System.out.println("Error: Not using the given digits");
      else
      {
        double r = parser.getResult();
        System.out.println("Result: " + r);
 
        if(r > 23.999 && r < 24.001)
          System.out.println("Good job!");
        else
          System.out.println("Try again.");
      }
    }
    catch(RuntimeException e)
    {
      System.out.println("Error: " + e.getMessage());
    }
  }
}

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import org.apache.batik.dom.GenericDOMImplementation;
import org.apache.batik.svggen.SVGGraphics2D;
import org.apache.batik.svggen.SVGGraphics2DIOException;
import org.w3c.dom.DOMImplementation;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.svg.SVGPathElement;
import org.w3c.dom.svg.SVGSVGElement;
 
public class SierpinskiSquareCurve {
    private double currentX;
    private double currentY;
    private int currentAngle;
    private double lineLength;
 
    public SierpinskiSquareCurve(double x, double y, double length, int angle) {
        this.currentX = x;
        this.currentY = y;
        this.currentAngle = angle;
        this.lineLength = length;
    }
 
    public static String rewrite(int order) {
        String str = "F+XF+F+XF";
        for (int i = 0; i < order; i++) {
            StringBuilder tmp = new StringBuilder();
            for (char ch : str.toCharArray()) {
                switch (ch) {
                    case 'X':
                        tmp.append("XF-F+F-XF+F+XF-F+F-X");
                        break;
                    default:
                        tmp.append(ch);
                }
            }
            str = tmp.toString();
        }
        return str;
    }
 
    public SVGPathElement execute(int order) {
        SVGPathElement path = (SVGPathElement) document.createElementNS(SVG_NAMESPACE_URI, "path");
        path.setAttributeNS(null, "fill", "none");
        path.setAttributeNS(null, "stroke", "black");
        path.setAttributeNS(null, "stroke-width", "1");
        StringBuilder data = new StringBuilder();
        data.append("M ").append(currentX).append(" ").append(currentY).append(" ");
        for (char ch : rewrite(order).toCharArray()) {
            switch (ch) {
                case 'F':
                    data.append(drawLine());
                    break;
                case '+':
                    turn(90);
                    break;
                case '-':
                    turn(-90);
                    break;
                default:
            }
        }
        path.setAttributeNS(null, "d", data.toString());
        return path;
    }
 
    private String drawLine() {
        double theta = Math.toRadians(currentAngle);
        currentX += lineLength * Math.cos(theta);
        currentY += lineLength * Math.sin(theta);
        return "L " + currentX + " " + currentY + " ";
    }
 
    private void turn(int angle) {
        currentAngle = (currentAngle + angle) % 360;
    }
 
    public static void save(String file, int size, double length, int order) throws IOException, SVGGraphics2DIOException {
        double x = (size - length) / 2.0;
        double y = length;
        SierpinskiSquareCurve s = new SierpinskiSquareCurve(x, y, length, 0);
        Element rect = document.createElementNS(SVG_NAMESPACE_URI, "rect");
        rect.setAttributeNS(null, "width", "100%");
        rect.setAttributeNS(null, "height", "100%");
        rect.setAttributeNS(null, "fill", "white");
        svgRoot.appendChild(rect);
        svgRoot.appendChild(s.execute(order));
        svgGenerator.stream(svgRoot, new File(file));
    }
 
    private static final String SVG_NAMESPACE_URI = "http://www.w3.org/2000/svg";
    private static final DOMImplementation domImpl = GenericDOMImplementation.getDOMImplementation();
    private static final Document document = domImpl.createDocument(SVG_NAMESPACE_URI, "svg", null);
    private static final SVGGraphics2D svgGenerator = new SVGGraphics2D(document);
    private static final SVGSVGElement svgRoot = document.getRootElement();
 
    public static void main(String[] args) throws IOException, SVGGraphics2DIOException {
        save("sierpinski_square_curve.svg", 635, 5.0, 5);
    }
}

