import java.util.Locale;
import java.text.NumberFormat;
 
public class NivenNumbers {
    // Returns the sum of the digits of n given the
    // sum of the digits of n - 1
    static int digitSum(long n, int sum) {
        sum += 1;
        while (n > 0 && n % 10 == 0) {
            sum -= 9;
            n /= 10;
        }
        return sum;
    }
 
    static boolean divisible(long n, int d) {
        if ((d & 1) == 0 && (n & 1) == 1) {
            return false;
        }
        return n % d == 0;
    }
 
    public static void main(String[] args) {
        NumberFormat nf = NumberFormat.getNumberInstance(Locale.US);
        long previous = 1;
        int gap = 0;
        int sum = 0;
        int nivenIndex = 0;
        int gapIndex = 1;
        long niven = 1;
        System.out.println("Gap index  Gap    Niven index    Niven number");
        while (gapIndex <= 32) {
            sum = digitSum(niven, sum);
            if (divisible(niven, sum)) {
                if (niven > previous + gap) {
                    gap = (int) (niven - previous);
                    System.out.printf("%9d %4d %14s %15s%n", gapIndex, gap, nf.format(nivenIndex), nf.format(previous));
                    gapIndex += 1;
                }
                previous = niven;
                nivenIndex += 1;
            }
            niven += 1;
        }
    }
}

import com.sun.jna.Library;
import com.sun.jna.Native;
import com.sun.jna.Pointer;
import com.sun.jna.Structure;
import com.sun.jna.ptr.IntByReference;
import com.sun.jna.win32.StdCallLibrary;
import com.sun.jna.win32.W32APIOptions;
import java.util.Arrays;
import java.util.List;

public class HelloWorld {

    public interface Winspool extends StdCallLibrary {

        Winspool INSTANCE = (Winspool) Native.loadLibrary("winspool.drv", Winspool.class, W32APIOptions.DEFAULT_OPTIONS);

        public static class DOCINFOA extends Structure {

            public String pDocName;
            public String pOutputFile;
            public String pDataType;

            @Override
            protected List getFieldOrder() {
                return Arrays.asList(new String[]{"pDocName", "pOutputFile", "pDataType"});
            }
        }

        boolean OpenPrinter(String szPrinter, IntByReference hPrinter, Pointer pd);

        boolean StartDocPrinter(Pointer hPrinter, int level, DOCINFOA di);

        boolean StartPagePrinter(Pointer hPrinter);

        boolean EndPagePrinter(Pointer hPrinter);

        boolean EndDocPrinter(Pointer hPrinter);

        boolean ClosePrinter(Pointer hPrinter);

        boolean WritePrinter(Pointer hPrinter, Pointer pBytes, int dwCount, IntByReference dwWritten);
    }

    public static void main(String[] args) {
        IntByReference hPrinter = new IntByReference();
        boolean openSuccessful = Winspool.INSTANCE.OpenPrinter("My Printer", hPrinter, null);
        if (openSuccessful) {
            Winspool.DOCINFOA docInfo = new Winspool.DOCINFOA();
            docInfo.pDocName = "Hello World Example";
            docInfo.pOutputFile = null;
            docInfo.pDataType = "RAW";

            if (Winspool.INSTANCE.StartDocPrinter(hPrinter, 1, docInfo)) {
                Winspool.INSTANCE.StartPagePrinter(hPrinter);

                String helloWorld = "Hello World!";
                Pointer buf = Native.toString(helloWorld);

                IntByReference bytesWritten = new IntByReference();
                Winspool.INSTANCE.WritePrinter(hPrinter, buf, helloWorld.length(), bytesWritten);
            }
            if (Winspool.INSTANCE.EndPagePrinter(hPrinter)) {
                if (Winspool.INSTANCE.EndDocPrinter(hPrinter)) {
                    Winspool.INSTANCE.ClosePrinter(hPrinter);
                }
            }
        }
    }
}

import java.util.Random;
import java.util.Vector;
import java.util.Collections;
import java.util.Comparator;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;
 
public class RandomNumbers {
 
    public static void printStars(int number) {
        if (number > 0) {
            for (int i = 0; i < number + 1; i++) {
                System.out.print('*');
            }
        }
        System.out.println();
    }
 
    public static void main(String[] args) {
        int numberOfRandoms = Integer.parseInt(args[0]);
        Random random = new Random();
        Vector<Double> randoms = new Vector<>();
        for (int i = 0; i < numberOfRandoms + 1; i++) {
            randoms.add(random.nextDouble());
        }
        Collections.sort(randoms);
        double start = 0.0;
        for (int i = 0; i < 9; i++) {
            double to = start + 0.1;
            int howmany = (int) randoms.stream().filter(new Predicate<Double>() {
                @Override
                public boolean test(Double c) {
                    return c >= start && c < to;
                }
            }).count();
            if (start == 0.0) {
                System.out.print("0.0" + " - " + to + ": ");
            } else {
                System.out.print(start + " - " + to + ": ");
            }
            if (howmany > 50) {
                howmany = howmany / (howmany / 50);
            }
            printStars(howmany);
            start += 0.1;
        }
        double mean = randoms.stream().mapToDouble(Double::doubleValue).average().getAsDouble();
        double sum = randoms.stream().mapToDouble(num -> Math.pow(num - mean, 2)).sum();
        double stddev = Math.pow(sum / randoms.size(), 0.5);
        System.out.println("The mean is " + mean + " !");
        System.out.println("Standard deviation is " + stddev + " !");
    }
}

