            hd.add(new BigInteger(h, 16).toByteArray());
        }
        ExecutorService executor = Executors.newFixedThreadPool(26);
        CountDownLatch latch = new CountDownLatch(26);
        for (char c = 'a'; c <= 'z'; c++) {
            executor.execute(new BruteForce4(c, hd, latch));
        }
        try {
            latch.await();
        } catch (InterruptedException ex) {
            Logger.getLogger(BruteForce4.class.getName()).log(Level.SEVERE, null, ex);
        }
        executor.shutdown();
    }
 
    private final char c;
    private final List<byte[]> hd;
    private final CountDownLatch latch;
 
    public BruteForce4(char c, List<byte[]> hd, CountDownLatch latch) {
        this.c = c;
        this.hd = hd;
        this.latch = latch;
    }
 
    @Override
    public void run() {
        byte[] p = new byte[5];
        p[0] = (byte) c;
        byte[] p1 = new byte[4];
        System.arraycopy(p, 1, p1, 0, 4);
        while (true) {
            byte[] ph = null;
            try {
                ph = MessageDigest.getInstance("SHA-256").digest(p);
            } catch (NoSuchAlgorithmException ex) {
                Logger.getLogger(BruteForce4.class.getName()).log(Level.SEVERE, null, ex);
            }
            for (int i = 0; i < hd.size(); i++) {
                if (MessageDigest.isEqual(hd.get(i), ph)) {
                    System.out.println(new String(p) + " " + hh[i]);
                }
            }
            for (int i = 0; i < p1.length; i++) {
                if (p1[i] < 'z') {
                    p1[i]++;
                    break;
                }
                p1[i] = 'a';
            }
            latch.countDown();
            return;
        }
    }
}

public static void insertionSort(int[] array) {
    for (int index = 1; index < array.length; index++) {
        int value = array[index];
        int subIndex = index - 1;
        while (subIndex >= 0 && array[subIndex] > value) {
            array[subIndex + 1] = array[subIndex];
            subIndex--;
        }
        array[subIndex + 1] = value;
    }
}
 
public static void main(String[] args) {
    int[] numbers = new int[]{5, 2, 3, 17, 12, 1, 8, 3, 4, 9, 7};
 
    Consumer<int[]> printArray = (message, array) -> {
        System.out.print(message + " [");
        for (int index = 0; index < array.length; index++) {
            int number = array[index];
            System.out.print(index == array.length - 1? number : number + ", ");
        }
        System.out.println("]");
    };
 
    printArray.accept("Unsorted:", numbers);
    insertionSort(numbers);
    printArray.accept("Sorted:", numbers);
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
 
public class UlamSpiral {
 
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter n: ");
        int n = in.nextInt();
        System.out.print("Enter i: ");
        int i = in.nextInt();
        System.out.print("Enter c: ");
        char c = in.next().charAt(0);
        generate(n, i, c);
    }
 
    public static void generate(int n, int i, char c) {
        List<List<String>> s = new ArrayList<>();
        for (int j = 0; j < n; j++) {
            List<String> row = new ArrayList<>();
            for (int k = 0; k < n; k++) {
                row.add("");
            }
            s.add(row);
        }
        Direction dir = Direction.RIGHT;
        int y = n / 2;
        int x;
        if (n % 2 == 0) {
            x = y - 1;
        } else {
            x = y;
        }
 
        for (int j = i; j <= n * n - 1 + i; j++) {
            if (isPrime(j)) {
                if (c == 0) {
                    s.get(y).set(x, String.format("%3d", j));
                } else {
                    s.get(y).set(x, String.format("%2c ", c));
                }
            } else {
                s.get(y).set(x, "---");
            }
 
            switch (dir) {
                case RIGHT:
                    if (x <= n - 1 && s.get(y - 1).get(x).equals("") && j > i) {
                        dir = Direction.UP;
                    }
                    break;
                case UP:
                    if (s.get(y).get(x - 1).equals("")) {
                        dir = Direction.LEFT;
                    }
                    break;
                case LEFT:
                    if (x == 0 || s.get(y + 1).get(x).equals("")) {
                        dir = Direction.DOWN;
                    }
                    break;
                case DOWN:
                    if (s.get(y).get(x + 1).equals("")) {
                        dir = Direction.RIGHT;
                    }
                    break;
            }
 
            switch (dir) {
                case RIGHT:
                    x += 1;
                    break;
                case UP:
                    y -= 1;
                    break;
                case LEFT:
                    x -= 1;
                    break;
                case DOWN:
                    y += 1;
                    break;
            }
        }
 
        for (List<String> row : s) {
            System.out.println(row);
        }
        System.out.println();
    }
 
    public static boolean isPrime(int a) {
        if (a == 2) {
            return true;
        }
        if (a <= 1 || a % 2 == 0) {
            return false;
        }
        int max = (int) Math.sqrt(a);
        for (int n = 3; n <= max; n += 2) {
            if (a % n == 0) {
                return false;
            }
        }
        return true;
    }
 
    enum Direction {
        RIGHT, UP, LEFT, DOWN
    }
}

