import java.util.Random;
 
public class Life {
	private int w, h;
	private Field a, b;
	private Random rand = new Random();
 
	public Life(int w, int h) {
		this.w = w;
		this.h = h;
		a = new Field(w, h);
		for (int i = 0; i < (w * h / 2); i++) {
			a.set(rand.nextInt(w), rand.nextInt(h), true);
		}
		b = new Field(w, h);
	}
 
	public void step() {
		for (int y = 0; y < h; y++) {
			for (int x = 0; x < w; x++) {
				b.set(x, y, a.next(x, y));
			}
		}
		Field t = a;
		a = b;
		b = t;
	}
 
	public String toString() {
		StringBuilder buf = new StringBuilder();
		for (int y = 0; y < h; y++) {
			for (int x = 0; x < w; x++) {
				char b ='';
				if (a.state(x, y)) {
					b = '*';
				}
				buf.append(b);
			}
			buf.append('\n');
		}
		return buf.toString();
	}
 
	public static void main(String[] args) throws InterruptedException {
		Life l = new Life(80, 15);
		for (int i = 0; i < 300; i++) {
			l.step();
			System.out.print("\033[H\033[2J");
			System.out.println(l);
			Thread.sleep(33);
		}
	}
}
 
class Field {
	private boolean[][] s;
	private int w, h;
 
	public Field(int w, int h) {
		s = new boolean[h][w];
		this.w = w;
		this.h = h;
	}
 
	public void set(int x, int y, boolean b) {
		s[y][x] = b;
	}
 
	public boolean next(int x, int y) {
		int on = 0;
		for (int i = -1; i <= 1; i++) {
			for (int j = -1; j <= 1; j++) {
				if (state(x + i, y + j) &&!(j == 0 && i == 0)) {
					on++;
				}
			}
		}
		return on == 3 || on == 2 && state(x, y);
	}
 
	public boolean state(int x, int y) {
		while (y < 0) {
			y += h;
		}
		while (x < 0) {
			x += w;
		}
		return s[y % h][x % w];
	}
}

import java.util.ArrayList;
import java.util.List;
 
public class AngleConverter {
 
    public static void main(String[] args) {
        List<Double> nums = new ArrayList<>();
        nums.add(-2.0);
        nums.add(-1.0);
        nums.add(0.0);
        nums.add(1.0);
        nums.add(2.0);
        nums.add(6.2831853);
        nums.add(16.0);
        nums.add(57.2957795);
        nums.add(359.0);
        nums.add(399.0);
        nums.add(6399.0);
        nums.add(1e6);
 
        List<String> units = new ArrayList<>();
        units.add("d");
        units.add("g");
        units.add("m");
        units.add("r");
 
        for (int x = 0; x < nums.size(); x++) {
            for (int y = 0; y < units.size(); y++) {
                System.out.print("<p><b>" + nums.get(x) + "<sub>" + units.get(y) + "</sub></b><br>");
                for (int z = 0; z < units.size(); z++) {
                    System.out.print("= " + angleConv(nums.get(x), units.get(y), units.get(z)) + "<sub>" + units.get(z) + "</sub>");
                }
            }
        }
    }
 
    public static double angleConv(double deg, String inp, String out) {
        inp = inp.toLowerCase();
        out = out.toLowerCase();
        final double D = 360,
                G = 400,
                M = 6400,
                R = 2 * Math.PI;
        // normalazation
        boolean minus = (deg < 0);  // boolean
        deg = Math.abs(deg);
        switch (inp) {
            case "d":
                deg %= D;
                break;
            case "g":
                deg %= G;
                break;
            case "m":
                deg %= M;
                break;
            case "r":
                deg %= R;
        }
        // we use an internal conversion to Turns (full circle) here
        double t;
        switch (inp) {
            case "d":
                t = deg / D;
                break;
            case "g":
                t = deg / G;
                break;
            case "m":
                t = deg / M;
                break;
            case "r":
                t = deg / R;
        }
        // converting
        switch (out) {
            case "d":
                t *= D;
                break;
            case "g":
                t *= G;
                break;
            case "m":
                t *= M;
                break;
            case "r":
                t *= R;
        }
        if (minus) {
            return 0 - t;
        }
        return t;
    }
}

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.Arrays;
import java.util.stream.IntStream;
 
public class Entropy {
    public static void main(String[] args) {
        try {
            File file = new File(args[0]);
            FileInputStream stream = new FileInputStream(file);
            System.out.println("Entropy is " + entropy(stream));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
 
    public static float entropy(FileInputStream stream) {
        long[] histogram = new long[256];
        long len = 0;
 
        try {
            int b;
            while ((b = stream.read())!= -1) {
                histogram[b] += 1;
                len += 1;
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
 
        return (float) IntStream.of(histogram)
               .filter(h -> h > 0)
               .mapToDouble(h -> h / (double) len)
               .map(ratio -> -ratio * Math.log(ratio) / Math.log(2))
               .sum();
    }
}

