import java.io.*;
import java.util.*;
import java.text.*;
import java.math.*;
import java.util.regex.*;

public class Solution {

    static int check_isin(String a) {
        int i, j, k, v, s[] = new int[24];

        j = 0;
        for(i = 0; i < 12; i++) {
            k = a.charAt(i);
            if(k >= '0' && k <= '9') {
                if(i < 2) return 0;
                s[j++] = k - '0';
            } else if(k >= 'A' && k <= 'Z') {
                if(i == 11) return 0;
                k -= 'A' - 10;
                s[j++] = k / 10;
                s[j++] = k % 10;
            } else {
                return 0;
            }
        }

        if(a.charAt(i)!= 0) return 0;

        v = 0;
        for(i = j - 2; i >= 0; i -= 2) {
            k = 2 * s[i];
            v += k > 9? k - 9 : k;
        }

        for(i = j - 1; i >= 0; i -= 2) {
            v += s[i];
        }

        return v % 10 == 0;
    }

    public static void main(String[] args) {
        String[] test = {"US0378331005", "US0373831005", "U50378331005",
                         "US03378331005", "AU0000XVGZA3", "AU0000VXGZA3",
                         "FR0000988040"};
        int i;
        for(i = 0; i < 7; i++) System.out.print(check_isin(test[i])? 'T' : 'F');
        System.out.println();
    }
}

