public class Pendulum extends JPanel {
 
    private static final double PI = Math.PI;
    private static final int WIDTH = 640;
    private static final int HEIGHT = 480;
 
    private static final double ANCHOR_X = WIDTH / 2. - 12.;
    private static final double ANCHOR_Y = HEIGHT / 4.;
    private static final Ellipse2D ANCHOR_ELLIPSE = new Ellipse2D.Double(ANCHOR_X - 3., ANCHOR_Y - 3., 6., 6.);
 
    private static final double[] ROPE_ORIGIN = {ANCHOR_X, ANCHOR_Y};
    private static final double ROPE_LENGTH = 200.;
    private static final double ROPE_THICKNESS = 1.;
 
    private static final double DELTA = 0.05;
    private static final double STANDARD_GRAVITY_VALUE = -9.81;
 
    private double angle = PI / 2.;
    private double angularVel = 0.;
 
    public Pendulum() {
        setBackground(Color.WHITE);
    }
 
    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        Graphics2D g2d = (Graphics2D) g;
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
 
        double angleSin = Math.sin(angle);
        double angleCos = Math.cos(angle);
        double ballX = ANCHOR_X + angleSin * ROPE_LENGTH;
        double ballY = ANCHOR_Y + angleCos * ROPE_LENGTH;
 
        double angleAccel = STANDARD_GRAVITY_VALUE / ROPE_LENGTH * angleSin;
        angularVel += angleAccel * DELTA;
        angle += angularVel * DELTA;
        double[] ropeEnd = {ballX, ballY};
        Ellipse2D ballEllipse = new Ellipse2D.Double(ballX - 7., ballY - 7., 14., 14.);
 
        g2d.setColor(Color.BLACK);
        g2d.draw(new Line2D.Double(ROPE_ORIGIN[0], ROPE_ORIGIN[1], ropeEnd[0], ropeEnd[1]));
        g2d.setColor(Color.RED);
        g2d.fill(ANCHOR_ELLIPSE);
        g2d.setColor(Color.YELLOW);
        g2d.fill(ballEllipse);
    }
 
    public static void main(String[] args) {
        JFrame frame = new JFrame("Pendulum");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.add(new Pendulum());
        frame.setSize(WIDTH, HEIGHT);
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
 
        while (true) {
            frame.repaint();
            try {
                Thread.sleep(10);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
}

import java.util.Scanner;
import java.util.ArrayList;
import java.util.List;

public class BooleanExpression {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (true) {
            System.out.print("\ninput a boolean expression (e.g. 'a & b'): ");
            String expr = scanner.nextLine().toLowerCase();
            if (expr.isEmpty()) {
                break;
            }
            List<String> vars = new ArrayList<String>();
            for (String var : expr.split("\\p{Alpha}+")) {
                vars.add(var);
            }
            if (vars.isEmpty()) {
                System.out.println("no variables detected in your boolean expression");
                continue;
            }
            for (String var : vars) {
                System.out.print(var + "\t");
            }
            System.out.println("| " + expr);
            List<String> prefix = new ArrayList<String>();
            List<String> suffix = new ArrayList<String>();
            for (String var : vars) {
                prefix.add("for (boolean " + var + " : new boolean[] {false, true}) {");
                suffix.add("}");
            }
            String body = "System.out.print(";
            for (String var : vars) {
                body += var + " + \"\t\" + ";
            }
            body += "\"| \" + " + expr + ");";
            for (String line : prefix) {
                System.out.println(line);
            }
            System.out.println(body);
            for (String line : suffix) {
                System.out.println(line);
            }
        }
    }
}

