public class LongMult {
    public static void main(String[] args) {
        long n = 2L << 62;
        System.out.printf("         %d * %d = %d\n", n, n, n*n);
        System.out.printf("longmult(%d, %d) = %d\n", n, n, longmult(n,n));
    }

    public static long longmult(long x, long y) {
        int[] result = {0};
        int j = 0;
        for (long m : digits(y)) {
            int c = 0;
            int i = j;
            for (long d : digits(x)) {
                int v = result[i];
                if (v == 0) result = add(result, 0);
                int[] temp = add(c, mul(d, m));
                c = temp[0];
                v = temp[1];
                result[i] = v;
                i += 1;
            }
            result[i] += c;
            j += 1;
        }
        // calculate the answer from the result array of digits
        long sum = 0;
        for (int n : result) sum = 10*sum + n;
        return sum;
    }

    public static int[] add(int x, int y) {
        int[] result = {0, 0};
        int c = 0;
        int v = result[0];
        result[0] = 0;
        c = (v + c + x) / 10;
        v = (v + c + x) % 10;
        result[0] = v;
        v = result[1];
        result[1] = 0;
        c = (v + c + y) / 10;
        v = (v + c + y) % 10;
        result[1] = v;
        return result;
    }

    public static int[] add(int[] x, int y) {
        int[] result = {0, 0};
        int c = 0;
        int i = 0;
        for (int d : x) {
            int v = result[i];
            result[i] = 0;
            c = (v + c + d) / 10;
            v = (v + c + d) % 10;
            result[i] = v;
            i += 1;
        }
        result[i] += c;
        return result;
    }

    public static int[] mul(int x, int y) {
        int[] result = {0, 0};
        int c = 0;
        int v = result[0];
        result[0] = 0;
        c = (v + c + x*y) / 10;
        v = (v + c + x*y) % 10;
        result[0] = v;
        v = result[1];
        result[1] = 0;
        c = (v + c + x*y) / 10;
        v = (v + c + x*y) % 10;
        result[1] = v;
        return result;
    }

    public static Iterable<Long> digits(long x) {
        return new Iterable<Long>() {
            public Iterator<Long> iterator() {
                return new Iterator<Long>() {
                    long n = x;
                    public boolean hasNext() { return n > 0; }
                    public Long next() {
                        long d = n % 10;
                        n = n / 10;
                        return d;
                    }
                    public void remove() { throw new UnsupportedOperationException(); }
                };
            }
        };
    }
}

import java.util.Arrays;
 
public class UnrootedBinaryTrees {
 
    private static final int MAX_N = 500;
    private static final int BRANCH = 4;
 
    private static int[] ra;
    private static int[] unrooted;
 
    private static void tree(int br, int n, int l, int sum, int cnt) {
        for (int b = br + 1; b <= BRANCH; b++) {
            sum += n;
            if (sum >= MAX_N) {
                return;
            }
            // prevent unneeded long math
            if (l * 2 >= sum && b >= BRANCH) {
                return;
            }
            int c;
            if (b == br + 1) {
                c = ra[n] * cnt;
            } else {
                c = c * (ra[n] + (b - br - 1)) / (b - br);
            }
            if (l * 2 < sum) {
                unrooted[sum] += c;
            }
            if (b >= BRANCH) {
                continue;
            }
            ra[sum] += c;
            for (int m = 1; m < n; m++) {
                tree(b, m, l, sum, c);
            }
        }
    }
 
    private static void bicenter(int s) {
        if (s % 2!= 0) {
            return;
        }
        int aux = ra[s / 2];
        unrooted[s] += aux * (aux + 1) / 2;
    }
 
    public static void main(String[] args) {
        ra = new int[MAX_N];
        unrooted = new int[MAX_N];
 
        ra[0] = ra[1] = unrooted[0] = unrooted[1] = 1;
        for (int n = 1; n < MAX_N; n++) {
            tree(0, n, n, n, 1);
            bicenter(n);
            System.out.println(n + ": " + unrooted[n]);
        }
    }
}

import java.util.function.Predicate;
 
public class Set<TValue>
{
    public Set(Predicate<TValue> contains)
    {
        Contains = contains;
    }
 
    public Predicate<TValue> Contains
    {
        get;
        private set;
    }
 
    public Set<TValue> Union(Set<TValue> set)
    {
        return new Set<TValue>(value -> Contains(value) || set.Contains(value));
    }
 
    public Set<TValue> Intersection(Set<TValue> set)
    {
        return new Set<TValue>(value -> Contains(value) && set.Contains(value));
    }
 
    public Set<TValue> Difference(Set<TValue> set)
    {
        return new Set<TValue>(value -> Contains(value) &&!set.Contains(value));
    }
}

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class SayNumber {
    public static String sayNumber(int value) {
        String name = "";
        int quotient, remainder;
        List<String> units = Arrays.asList("zero", "one", "two", "three", "four", "five", "six", "seven",
                "eight", "nine", "ten", "eleven", "twelve", "thirteen", "fourteen",
                "fifteen", "sixteen", "seventeen", "eighteen", "nineteen");
        List<String> tens = Arrays.asList("", "", "twenty", "thirty", "forty", "fifty", "sixty",
                "seventy", "eighty", "ninety");
        List<String> big = Arrays.asList("", "thousand", "m", "b", "tr", "quadr", "quint",
                "sext", "sept", "oct", "non", "dec").stream().map(e -> e + "illion").collect(Collectors.toList());

        if (value < 0) {
            name = "negative " + sayNumber(-value);
        } else if (value < 20) {
            name = units.get(value);
        } else if (value < 100) {
            quotient = value / 10;
            remainder = value % 10;
            name = tens.get(quotient) + " " + units.get(remainder);
            name = name.replace(" zero", "");
        } else if (value < 1000) {
            quotient = value / 100;
            remainder = value % 100;
            name = sayNumber(quotient) + " hundred and " + sayNumber(remainder);
            name = name.replace(" and zero", "");
        } else {
            List<Integer> chunks = new ArrayList<>();
            List<String> text = new ArrayList<>();
            while (value!= 0) {
                value = value / 1000;
                remainder = value % 1000;
                chunks.add(remainder);
            }
            for (int i = 0; i < chunks.size(); i++) {
                int e = chunks.get(i);
                if (e > 0) {
                    text.add(sayNumber(e) + (i == 0? "" : " " + big.get(i)));
                    if (i == 0 && e < 100) {
                        text.add("and");
                    }
                }
            }
            name = String.join(", ", text.stream().collect(Collectors.toList()));
            name = name.replace(", and,", " and");
        }
        return name;
    }
}

