public class Main {
    public static double shoelaceArea(List<Point> v) {
        int n = v.size();
        double a = 0.0;
        for (int i = 0; i < n - 1; i++) {
            a += v.get(i).x * v.get(i + 1).y - v.get(i + 1).x * v.get(i).y;
        }
        return Math.abs(a + v.get(n - 1).x * v.get(0).y - v.get(0).x * v.get(n - 1).y) / 2.0;
    }
 
    public static void main(String[] args) {
        List<Point> v = Arrays.asList(
            new Point(3, 4), new Point(5, 11), new Point(12, 8), new Point(9, 5), new Point(5, 6)
        );
        double area = shoelaceArea(v);
        System.out.println("Given a polygon with vertices at " + v + ",");
        System.out.println("its area is " + area);
    }
}

package com.example.dragon;

import java.awt.geom.Point2D;
import java.util.ArrayList;
import java.util.List;

import org.apache.batik.dom.svg.SVGDOMImplementation;
import org.apache.batik.svggen.SVGGraphics2D;
import org.w3c.dom.DOMImplementation;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.svg.SVGDocument;

public class Dragon {

    public static void main(String[] args) {
        Dragon dragon = new Dragon();
        dragon.fractalMakeDragon(1000, new Point2D.Double(100, 100), new Point2D.Double(200, 200), 10, true, 100);
    }

    // MATRIX MATH
    // -----------

    private Point2D mult(Point2D m, Point2D v) {
        return new Point2D.Double(m.getX() * v.getX() + m.getY() * v.getY(), m.getX() * v.getX() + m.getY() * v.getY());
    }

    private Point2D minus(Point2D a, Point2D b) {
        return new Point2D.Double(a.getX() - b.getX(), a.getY() - b.getY());
    }

    private Point2D plus(Point2D a, Point2D b) {
        return new Point2D.Double(a.getX() + b.getX(), a.getY() + b.getY());
    }

    // SVG STUFF
    // ---------

    // Turn a pair of points into an SVG path like "M1 1L2 2".
    private String toSVGpath(Point2D a, Point2D b) {
        return "M" + a.getX() + " " + a.getY() + "L" + b.getX() + " " + b.getY();
    }

    // DRAGON MAKING
    // -------------

    // Make a dragon with a better fractal algorithm
    private void fractalMakeDragon(int state, Point2D ptA, Point2D ptC, boolean lr, int interval) {

        // make a new <path>
        DOMImplementation domImpl = SVGDOMImplementation.getDOMImplementation();
        String svgNS = "http://www.w3.org/2000/svg";
        SVGDocument svgDoc = (SVGDocument) domImpl.createDocument(svgNS, "svg", null);
        Element path = svgDoc.createElementNS(svgNS, "path");
        path.setAttribute("class", "dragon");
        path.setAttribute("d", toSVGpath(ptA, ptC));

        // append the new path to the existing <svg>
        SVGGraphics2D svg = new SVGGraphics2D(svgDoc);
        svg.getRoot().appendChild(path);

        // if we have more iterations to go...
        if (state > 1) {

            // make a new point, either to the left or right
            Point2D growNewPoint(Point2D ptA, Point2D ptC, boolean lr) {
                Point2D left = new Point2D.Double(1 / 2, -1 / 2);
                Point2D right = new Point2D.Double(1 / 2, 1 / 2);

                return plus(ptA, mult(lr? left : right, minus(ptC, ptA)));
            }

            Point2D ptB = growNewPoint(ptA, ptC, lr);

            // then recurse using each new line, one left, one right
            Runnable recurse = new Runnable() {
                @Override
                public void run() {
                    // when recursing deeper, delete this svg path
                    svg.getRoot().removeChild(path);

                    // then invoke again for new pair, decrementing the state
                    fractalMakeDragon(state - 1, ptB, ptA, lr, interval);
                    fractalMakeDragon(state - 1, ptB, ptC, lr, interval);
                }
            };

            Thread thread = new Thread(recurse);
            thread.start();
        }
    }
}

