public class ListNode {
  private int value;
  private ListNode succ;
 
  public ListNode(int value, ListNode succ) {
    this.value = value;
    this.succ = succ;
  }
 
  public void each(Consumer<ListNode> b) {
    b.accept(this);
    if (succ!= null) succ.each(b);
  }
 
  public static ListNode fromArray(int[] ary) {
    ListNode head = new ListNode(ary[0], null);
    ListNode prev = head;
    for (int i = 1; i < ary.length; i++) {
      ListNode node = new ListNode(ary[i], null);
      prev.succ = node;
      prev = node;
    }
    return head;
  }
}

