import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
 
public class Cumulative {
 
    public static void cumu(int n, List<List<BigInteger>> cache) {
        for (int l = cache.size(); l <= n; l++) {
            List<BigInteger> r = new ArrayList<>();
            r.add(BigInteger.ZERO);
            for (int x = 1; x <= l; x++) {
                BigInteger prev = r.get(r.size() - 1);
                r.add(prev.add(cache.get(l - x).get(Math.min(x, l - x))));
            }
            cache.add(r);
        }
    }
 
    public static List<BigInteger> row(int n, List<List<BigInteger>> cache) {
        cumu(n, cache);
        List<BigInteger> r = cache.get(n);
        List<BigInteger> v = new ArrayList<>();
 
        for (int i = 0; i < n; i++) {
            v.add(r.get(i + 1).subtract(r.get(i)));
        }
        return v;
    }
 
    public static void main(String[] args) {
        List<List<BigInteger>> cache = new ArrayList<>();
        cache.add(new ArrayList<>());
        cache.get(0).add(BigInteger.ONE);
 
        System.out.println("rows:");
        for (int x = 1; x <= 25; x++) {
            List<BigInteger> v = row(x, cache);
            StringBuilder sb = new StringBuilder();
            for (BigInteger e : v) {
                sb.append(e).append(" ");
            }
            System.out.println(x + ": " + sb.toString().trim());
        }
 
        System.out.println("sums:");
        for (int x : new int[]{23, 123, 1234, 12345}) {
            cumu(x, cache);
            List<BigInteger> v = cache.get(x);
            System.out.println(x + ": " + v.get(v.size() - 1));
        }
    }
}

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class LookAndSay {
 
    public static String lookandsay(String number) {
        StringBuilder result = new StringBuilder();
 
        char repeat = number.charAt(0);
        number = number.substring(1, number.length()) + " ";
        int times = 1;
 
        for (char actual : number.toCharArray()) {
            if (actual!= repeat) {
                result.append(times).append(repeat);
                times = 1;
                repeat = actual;
            } else {
                times += 1;
            }
        }
        return result.toString();
    }
 
    public static void main(String[] args) {
        String num = "1";
 
        IntStream.range(1, 11).forEach(i -> {
            System.out.println(num);
            num = lookandsay(num);
        });
    }
}

