import java.lang.Math;
import java.lang.System;
 
public class RungeKutta4 {
    public static void main(String[] args) {
        System.out.println("  T        RK4        Exact      Error");
        System.out.println("----  ----------  ----------  ---------");
        Y y = new Y() {
            public double invoke(double t) {
                double x = t * t + 4.0;
                return x * x / 16.0;
            }
        };
        Yd yd = new Yd() {
            public double invoke(double t, double yt) {
                return t * Math.sqrt(yt);
            }
        };
        rungeKutta4(0.0, 10.0, 0.1, y, yd);
    }
 
    public static void rungeKutta4(double t0, double tz, double dt, Y y, Yd yd) {
        double tn = t0;
        double yn = y.invoke(tn);
        int z = (int) ((tz - t0) / dt);
        for (int i = 0; i <= z; i++) {
            if (i % 10 == 0) {
                double exact = y.invoke(tn);
                double error = yn - exact;
                System.out.format("%4.1f  %10f  %10f  %9f%n", tn, yn, exact, error);
            }
            if (i == z) break;
            double dy1 = dt * yd.invoke(tn, yn);
            double dy2 = dt * yd.invoke(tn + 0.5 * dt, yn + 0.5 * dy1);
            double dy3 = dt * yd.invoke(tn + 0.5 * dt, yn + 0.5 * dy2);
            double dy4 = dt * yd.invoke(tn + dt, yn + dy3);
            yn += (dy1 + 2.0 * dy2 + 2.0 * dy3 + dy4) / 6.0;
            tn += dt;
        }
    }
}

