public class Squares {
    public static void main(String[] args) {
        for (int n = 1; n <= 22; n++) {
            System.out.println(n + " " + f(n));
        }
        int[] nonSquares = new int[1_000_000];
        for (int n = 0; n < nonSquares.length; n++) {
            nonSquares[n] = f(n + 1);
        }
        int[] squares = new int[1001];
        for (int n = 0; n < squares.length; n++) {
            squares[n] = n * n;
        }
        for (int n : squares) {
            if (n > nonSquares[nonSquares.length - 1]) {
                break;
            }
            int index = Arrays.binarySearch(nonSquares, n);
            if (index >= 0) {
                System.out.println("Oops, found a square f(" + index + ") = " + n);
            }
        }
    }
    public static int f(int n) {
        return n + (int) Math.floor(0.5 + Math.sqrt(n));
    }
}

public class A004290 {
    public static int getA004290(int n) {
        if (n < 2) {
            return 1;
        }
        int[][] arr = new int[n][n];
        arr[0][0] = 1;
        arr[0][1] = 1;
        int m = 0;
        while (true) {
            m++;
            if (arr[m - 1][(int) (Math.pow(10, m) % n)] == 1) {
                break;
            }
            arr[m][0] = 1;
            for (int k = 1; k < n; k++) {
                arr[m][k] = Math.max(arr[m - 1][k], arr[m - 1][(int) ((k - Math.pow(10, m)) % n)]);
            }
        }
        int r = (int) Math.pow(10, m);
        int k = (int) ((r - Math.pow(10, m)) % n);
        for (int j = m - 1; j > 0; j--) {
            if (arr[j - 1][k] == 0) {
                r += (int) Math.pow(10, j);
                k = (int) ((k - Math.pow(10, j)) % n);
            }
        }
        if (k == 1) {
            r++;
        }
        return r;
    }
 
    public static void main(String[] args) {
        for (int n = 1; n < 11; n++) {
            int result = getA004290(n);
            System.out.println("A004290(" + n + ") = " + result + " = " + n + " * " + result / n);
        }
        for (int n = 95; n < 106; n++) {
            int result = getA004290(n);
            System.out.println("A004290(" + n + ") = " + result + " = " + n + " * " + result / n);
        }
        for (int n : new int[]{297, 576, 594, 891, 909, 999, 1998, 2079, 2251, 2277, 2439, 2997, 4878}) {
            int result = getA004290(n);
            System.out.println("A004290(" + n + ") = " + result + " = " + n + " * " + result / n);
        }
    }
}

import java.util.HashMap;
import java.util.Map;
 
public class Enigma {
 
    private static class Wheel {
 
        private String seq;
        private int len;
        private int pos;
 
        public Wheel(String seq) {
            this.seq = seq;
            this.len = seq.length();
            this.pos = 0;
        }
 
        public char cycle() {
            char c = seq.charAt(pos);
            pos = (pos + 1) % len;
            return c;
        }
    }
 
    private static class Map {
 
        private Wheel v;
        private Map next;
        private char k;
 
        public Map(char k, Wheel v, Map next) {
            this.k = k;
            this.v = v;
            this.next = next;
        }
 
        public Wheel find(char k) {
            Map ptr = this;
 
            while (ptr!= null) {
                if (ptr.k == k) {
                    return ptr.v;
                }
                ptr = ptr.next;
            }
 
            return null;
        }
    }
 
    private static void printOne(char k, Map m) {
        Wheel w = m.find(k);
        char c;
 
        if (w == null) {
            System.out.println("Missing the wheel for: " + k);
            System.exit(1);
        }
 
        c = w.cycle();
        if ('0' <= c && c <= '9') {
            System.out.print(" " + c);
        } else {
            printOne(c, m);
        }
    }
 
    private static void exec(char start, Map m) {
        Wheel w;
        int i;
 
        if (m == null) {
            System.out.println("Unable to proceed.");
            return;
        }
 
        for (i = 0; i < 20; i++) {
            printOne(start, m);
        }
        System.out.println();
    }
 
    private static void group1() {
        Wheel a = new Wheel("123");
 
        Map m = new Map('A', a, null);
 
        exec('A', m);
    }
 
    private static void group2() {
        Wheel a = new Wheel("1B2");
        Wheel b = new Wheel("34");
 
        Map m = new Map('A', a, null);
        m = new Map('B', b, m);
 
        exec('A', m);
    }
 
    private static void group3() {
        Wheel a = new Wheel("1DD");
        Wheel d = new Wheel("678");
 
        Map m = new Map('A', a, null);
        m = new Map('D', d, m);
 
        exec('A', m);
    }
 
    private static void group4() {
        Wheel a = new Wheel("1BC");
        Wheel b = new Wheel("34");
        Wheel c = new Wheel("5B");
 
        Map m = new Map('A', a, null);
        m = new Map('B', b, m);
        m = new Map('C', c, m);
 
        exec('A', m);
    }
 
    public static void main(String[] args) {
        group1();
        group2();
        group3();
        group4();
    }
}

public class GnomeSort {
    public static void main(String[] args) {
        int[] ary = {7,6,5,9,8,4,3,1,2,0};
        gnomesort(ary);
        for (int i = 0; i < ary.length; i++) {
            System.out.print(ary[i] + " ");
        }
        System.out.println();
    }

    public static void gnomesort(int[] ary) {
        int i = 1;
        int j = 2;
        while (i < ary.length) {
            if (ary[i-1] <= ary[i]) {
                i = j;
                j = j + 1;
            } else {
                int tmp = ary[i-1];
                ary[i-1] = ary[i];
                ary[i] = tmp;
                i = i - 1;
                if (i == 0) {
                    i = j;
                    j = j + 1;
                }
            }
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class Zumkeller {

    public static void main(String[] args) {
        System.out.println("The first 220 Zumkeller numbers are:");
        for (int i = 2, count = 0; count < 220; i++) {
            if (isZumkeller(i)) {
                System.out.printf("%3d ", i);
                count++;
                if (count % 20 == 0) {
                    System.out.println();
                }
            }
        }
        System.out.println("\nThe first 40 odd Zumkeller numbers are:");
        for (int i = 3, count = 0; count < 40; i += 2) {
            if (isZumkeller(i)) {
                System.out.printf("%5d ", i);
                count++;
                if (count % 10 == 0) {
                    System.out.println();
                }
            }
        }
        System.out.println("\nThe first 40 odd Zumkeller numbers which don't end in 5 are:");
        for (int i = 3, count = 0; count < 40; i += 2) {
            if (i % 10!= 5 && isZumkeller(i)) {
                System.out.printf("%7d ", i);
                count++;
                if (count % 8 == 0) {
                    System.out.println();
                }
            }
        }
        System.out.println();
    }

    private static boolean isZumkeller(int n) {
        List<Integer> divs = getDivisors(n);
        int sum = sum(divs);
        // if sum is odd can't be split into two partitions with equal sums
        if (sum % 2 == 1) {
            return false;
        }
        // if n is odd use 'abundant odd number' optimization
        if (n % 2 == 1) {
            int abundance = sum - 2 * n;
            return abundance > 0 && abundance % 2 == 0;
        }
        // if n and sum are both even check if there's a partition which totals sum / 2
        return isPartSum(divs, sum / 2);
    }

    private static boolean isPartSum(List<Integer> divs, int sum) {
        if (sum == 0) {
            return true;
        }
        int le = divs.size();
        if (le == 0) {
            return false;
        }
        int last = divs.get(le - 1);
        divs.remove(le - 1);
        if (last > sum) {
            return isPartSum(divs, sum);
        }
        return isPartSum(divs, sum) || isPartSum(divs, sum - last);
    }

    private static int sum(List<Integer> divs) {
        int sum = 0;
        for (int div : divs) {
            sum += div;
        }
        return sum;
    }

    private static List<Integer> getDivisors(int n) {
        List<Integer> divs = new ArrayList<>();
        divs.add(1);
        divs.add(n);
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                int j = n / i;
                divs.add(i);
                if (i!= j) {
                    divs.add(j);
                }
            }
        }
        return divs;
    }
}

import java.util.stream.IntStream;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        for (int m = 1; m <= 10; m++) {
            System.out.println(String.format("%2d: %s", m, IntStream.range(1, 11)
                   .mapToObj(n -> String.valueOf(mfac(n, m)))
                   .collect(Collectors.joining(", ", "[", "]"))));
        }
    }

    private static int mfac(int n, int m) {
        return IntStream.range(n, 0, -m).reduce(1, (a, b) -> a * b);
    }
}

