import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Supplier;

public class History {
    public static void main(String[] args) {
        // enable history variable support appropriate for single goroutine.
        Supplier<Long> ts = newTimestamper();
        // define a history variable
        History h = new History(ts);
        // assign three values.  (timestamps kept for future reference.)
        List<Long> ref = new ArrayList<>();
        ref.add(h.set(3));
        ref.add(h.set(1));
        ref.add(h.set(4));
        // non-destructively display history
        System.out.println("History of variable h:");
        h.dump();
        // recall the three values.  (this is non-destructive as well, but
        // different than the dump in that values are recalled by time.)
        System.out.println("Recalling values:");
        for (Long t : ref) {
            System.out.println(h.recall(t));
        }
    }

    private static Supplier<Long> newTimestamper() {
        return new AtomicLong();
    }

    private static Supplier<Long> newProtectedTimestamper() {
        return new AtomicLong();
    }

    private final Supplier<Long> timestamp;
    private final List<Hset> hs;

    public History(Supplier<Long> timestamp) {
        this.timestamp = timestamp;
        this.hs = new ArrayList<>();
        this.hs.add(new Hset(0, timestamp.get()));
    }

    public int int_() {
        return this.hs.get(this.hs.size() - 1).int_;
    }

    public long set(int x) {
        long t = this.timestamp.get();
        this.hs.add(new Hset(x, t));
        return t;
    }

    public void dump() {
        for (Hset hs : this.hs) {
            System.out.println(hs.t + " " + hs.int_);
        }
    }

    public int recall(long t) {
        int i = Collections.binarySearch(this.hs, new Hset(0, t), new Comparator<Hset>() {
            @Override
            public int compare(Hset o1, Hset o2) {
                return Long.compare(o1.t, o2.t);
            }
        });
        if (i > 0) {
            return this.hs.get(i - 1).int_;
        }
        return 0;
    }

    private static class Hset {
        public final int int_;
        public final long t;

        public Hset(int int_, long t) {
            this.int_ = int_;
            this.t = t;
        }
    }
}

public class IntegerOrdinalize {
    public static void main(String[] args) {
        for (int i = 0; i < 26; i++) {
            System.out.print(ordinalize(i) + ", ");
        }
        System.out.println();
        for (int i = 250; i < 266; i++) {
            System.out.print(ordinalize(i) + ", ");
        }
        System.out.println();
        for (int i = 1000; i < 1026; i++) {
            System.out.print(ordinalize(i) + ", ");
        }
        System.out.println();
    }
    public static String ordinalize(int num) {
        int abs = Math.abs(num);
        String ordinal = "";
        if ((abs % 100 >= 11) && (abs % 100 <= 13)) {
            ordinal = "th";
        } else {
            switch (abs % 10) {
                case 1:
                    ordinal = "st";
                    break;
                case 2:
                    ordinal = "nd";
                    break;
                case 3:
                    ordinal = "rd";
                    break;
                default:
                    ordinal = "th";
            }
        }
        return num + ordinal;
    }
}

#include <iostream>
 
int main() {
    int n, b, d;
    unsigned long long i, j, sum, fact[12];
    // cache factorials from 0 to 11
    fact[0] = 1;
    for (n = 1; n < 12; ++n) {
        fact[n] = fact[n-1] * n;
    }
 
    for (b = 9; b <= 12; ++b) {
        std::cout << "The factorions for base " << b << " are:\n";
        for (i = 1; i < 1500000; ++i) {
            sum = 0;
            j = i;
            while (j > 0) {
                d = j % b;
                sum += fact[d];
                j /= b;
            }
            if (sum == i) std::cout << i <<'';
        }
        std::cout << "\n\n";
    }
    return 0;
}

import java.util.ArrayList;
import java.util.List;
 
public class EgyptianDivmod {
 
    public static void main(String[] args) {
        int[] result = egyptianDivmod(580, 34);
        System.out.println("Quotient = " + result[0] + " Remainder = " + result[1]);
    }
 
    public static int[] egyptianDivmod(int dividend, int divisor) {
        List<int[]> table = new ArrayList<>();
        table.add(new int[]{1, divisor});
        while (table.get(table.size() - 1)[0] * 2 <= dividend) {
            int[] last = table.get(table.size() - 1);
            table.add(new int[]{last[0] * 2, last[1] * 2});
        }
        int answer = 0, accumulator = 0;
        for (int i = table.size() - 1; i >= 0; i--) {
            int[] powDouble = table.get(i);
            if (accumulator + powDouble[1] <= dividend) {
                accumulator += powDouble[1];
                answer += powDouble[0];
            }
        }
        return new int[]{answer, dividend - accumulator};
    }
}

