import java.util.Arrays;
 
public class ZigZagMatrix {
    public static void main(String[] args) {
        printMatrix(zigzagMatrix(5));
        printMatrix(zigzagMatrix(10));
    }
    public static void printMatrix(int[][] m) {
        for (int i = 0; i < m.length; i++) {
            for (int j = 0; j < m.length; j++) System.out.printf("%2d ", m[i][j]);
            System.out.println();
        }
        System.out.println();
    }
    public static int[][] zigzagMatrix(int n) {
        int[][] result = new int[n][n];
        boolean down = false;
        int count = 0;
        for (int col = 0; col < n; col++) {
            if (down)
                for (int row = 0; row <= col; row++) result[row][col - row] = count++;
            else
                for (int row = col; row >= 0; row--) result[row][col - row] = count++;
            down =!down;
        }
        for (int row = 1; row < n; row++) {
            if (down)
                for (int col = n - 1; col >= row; col--) result[row + n - 1 - col][col] = count++;
            else
                for (int col = row; col < n; col++) result[row + n - 1 - col][col] = count++;
            down =!down;
        }
        return result;
    }
}

