import java.util.Scanner;
 
public class RosettaVampireNumber {
 
    public static void main(String[] args) {
        int i, j, n;
        long x;
        long[] f = new long[16];
        long[] bigs = new long[]{16758243290880L, 24959017348650L, 14593825548650L, 0};
        long[] tens = new long[20];
        tens[0] = 1;
        for (i = 1; i < 20; i++)
            tens[i] = tens[i - 1] * 10;
 
        for (x = 1, n = 0; n < 25; x++) {
            if ((j = fangs(x, f, tens)) == 0)
                continue;
            System.out.print(++n + ": ");
            show_fangs(x, f, j);
        }
 
        System.out.println();
        for (i = 0; bigs[i] > 0; i++) {
            if ((j = fangs(bigs[i], f, tens)) > 0)
                show_fangs(bigs[i], f, j);
            else
                System.out.println(bigs[i] + " is not vampiric.");
        }
    }
 
    private static void show_fangs(long x, long[] f, int cnt) {
        System.out.print(x);
        int i;
        for (i = 0; i < cnt; i++)
            System.out.print(" = " + f[i] + " * " + (x / f[i]));
        System.out.println();
    }
 
    private static int fangs(long x, long[] f, long[] tens) {
        int n = 0;
        int nd = ndigits(x);
        if ((nd & 1) > 0)
            return 0;
        nd /= 2;
 
        long lo, hi;
        lo = Math.max(tens[nd - 1], (x + tens[nd] - 2) / (tens[nd] - 1));
        hi = Math.min(x / lo, (long) Math.sqrt(x));
 
        long a, b, t = dtally(x);
        for (a = lo; a <= hi; a++) {
            b = x / a;
            if (a * b == x && ((a % 10) > 0 || (b % 10) > 0) && t == dtally(a) + dtally(b))
                f[n++] = a;
        }
 
        return n;
    }
 
    private static long dtally(long x) {
        long t = 0;
        while (x > 0) {
            t += 1L << (int) ((x % 10) * 6);
            x /= 10;
        }
 
        return t;
    }
 
    private static int ndigits(long x) {
        int n = 0;
        while (x > 0) {
            n++;
            x /= 10;
        }
        return n;
    }
}

