import java.util.stream.IntStream;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        System.out.println(main());
    }

    private static String main() {
        return unlines(map(
            x -> x.toString() + (
                isCube(x)? (
                    " (cube of " + cubeRootInt(x) + " and square of " +
                            Math.pow(x, 1/2) +
                    ")"
                ) : ""
            ),
            map(x -> x * x, enumFromTo(1, 33))
        ));
    }

    // isCube :: Int -> Bool
    private static boolean isCube(int n) {
        return n == Math.pow(cubeRootInt(n), 3);
    }

    // cubeRootInt :: Int -> Int
    private static int cubeRootInt(int n) {
        return (int) Math.round(Math.pow(n, 1 / 3));
    }


    // GENERIC FUNCTIONS ----------------------------------

    // enumFromTo :: Int -> Int -> [Int]
    private static int[] enumFromTo(int m, int n) {
        return iterateUntil(
            x -> n <= x,
            x -> 1 + x,
            m
        );
    }

    // iterateUntil :: (a -> Bool) -> (a -> a) -> a -> [a]
    private static int[] iterateUntil(IntPredicate p, IntUnaryOperator f, int x) {
        return IntStream.iterate(x, f)
           .takeWhile(p)
           .toArray();
    }

    // map :: (a -> b) -> [a] -> [b]
    private static <A, B> B[] map(IntUnaryOperator f, A[] xs) {
        return IntStream.range(0, xs.length)
           .map(i -> f.applyAsInt(xs[i]))
           .toArray();
    }

    // unlines :: [String] -> String
    private static String unlines(String[] xs) {
        return String.join("\n", xs);
    }
}

