    public static boolean canMakeWord(String word, List<String> blockCollection) {
        if (word.length() == 0) {
            return false;
        }
 
        List<String> blocksRemaining = new ArrayList<String>(blockCollection);
        for (int i = 0; i < word.length(); i++) {
            String charStr = word.substring(i, i + 1);
            for (String block : blocksRemaining) {
                if (block.contains(charStr)) {
                    blocksRemaining.remove(block);
                    break;
                }
            }
            if (blocksRemaining.size() == blockCollection.size()) {
                return false;
            }
        }
        return true;
    }
}

import java.util.Scanner;

public class Brainfuck {
    public static void main(String[] args) {
        // example program is current Brain**** solution to
        // Hello world/Text task.  only requires 10 bytes of data store!
        bf(10, "++++++++++[>+>+++>++++>+++++++>++++++++>+++++++++>++" +
                "++++++++>+++++++++++>++++++++++++<<<<<<<<<-]>>>>+.>>>" +
                ">+..<.<++++++++.>>>+.<<+.<<<<++++.<++.>>>+++++++.>>>.+++" +
                ".<+++++++.--------.<<<<<+.<+++.---.");
    }

    public static void bf(int dLen, String is) {
        byte[] ds = new byte[dLen]; // data store
        int dp = 0;                 // data pointer
        for (int ip = 0; ip < is.length(); ip++) {
            switch (is.charAt(ip)) {
                case '>':
                    dp++;
                    break;
                case '<':
                    dp--;
                    break;
                case '+':
                    ds[dp]++;
                    break;
                case '-':
                    ds[dp]--;
                    break;
                case '.':
                    System.out.printf("%c", ds[dp]);
                    break;
                case ',':
                    Scanner scanner = new Scanner(System.in);
                    ds[dp] = scanner.next().charAt(0);
                    break;
                case '[':
                    if (ds[dp] == 0) {
                        int nc = 1;
                        while (nc > 0) {
                            ip++;
                            if (is.charAt(ip) == '[') {
                                nc++;
                            } else if (is.charAt(ip) == ']') {
                                nc--;
                            }
                        }
                    }
                    break;
                case ']':
                    if (ds[dp]!= 0) {
                        int nc = 1;
                        while (nc > 0) {
                            ip--;
                            if (is.charAt(ip) == ']') {
                                nc++;
                            } else if (is.charAt(ip) == '[') {
                                nc--;
                            }
                        }
                    }
                    break;
            }
        }
    }
}

import java.math.BigInteger;

public class IsPrime {

    public static boolean isPrime(BigInteger n) {
        if (n.compareTo(BigInteger.valueOf(2)) == -1) {
            return false;
        }
        if (n.compareTo(BigInteger.valueOf(2)) == 0) {
            return true;
        }
        if (n.mod(BigInteger.valueOf(2)).compareTo(BigInteger.ZERO) == 0) {
            return false;
        }
        for (BigInteger i = BigInteger.valueOf(3); i.compareTo(n)!= 1; i = i.add(BigInteger.valueOf(2))) {
            if (n.mod(i).compareTo(BigInteger.ZERO) == 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int[] vals = {
                1 << 31,
                1234567,
                333333,
                987653,
                2 * 3 * 5 * 7 * 11 * 13 * 17,
        };
        for (int v : vals) {
            System.out.println(v + " -> " + isPrime(BigInteger.valueOf(v)));
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.function.Function;
 
public class Main {
 
    public static void main(String[] args) throws IOException {
        InputStream in = System.in;
        OutputStream out = System.out;
        PrintWriter pw = new PrintWriter(out);
        boolean e = false;
        while (e? odd(in, pw) : even(in, pw)) {
            e =!e;
        }
        pw.flush();
    }
 
    private static boolean odd(InputStream in, PrintWriter pw) throws IOException {
        Function<Void, Void> prev = () -> null;
        while (true) {
            int c = in.read();
            if (!Character.isLetter(c)) {
                prev.apply(null);
                pw.print((char) c);
                return c!= '.';
            }
            prev = () -> {
                pw.print((char) c);
                prev.apply(null);
                return null;
            };
        }
    }
 
    private static boolean even(InputStream in, PrintWriter pw) throws IOException {
        while (true) {
            int c = in.read();
            pw.print((char) c);
            if (!Character.isLetter(c)) {
                return c!= '.';
            }
        }
    }
}

