import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class Go {
    public static void main(String[] args) {
        System.out.println(render("Go", lean));
        System.out.println(render("Go", smallKeyboard));
    }
 
    private static String render(String s, Font f) {
        String[] rows = new String[f.height];
        if (f.slant!= 0) {
            int start = 0;
            if (f.slant > 0) {
                start = f.height;
            }
            for (int i = 0; i < rows.length; i++) {
                rows[i] = " ".repeat(Math.max(0, (start - i) * f.slant));
            }
        }
        if (f.spacing >= 0) {
            String spacing = " ".repeat(Math.max(0, f.spacing));
            for (int j = 0; j < s.length(); j++) {
                char c = s.charAt(j);
                for (int i = 0; i < f.height; i++) {
                    String r = f.m.get(c)[i];
                    if (j > 0) {
                        r = spacing + r;
                    }
                    rows[i] += r;
                }
            }
        } else {
            int overlap = -f.spacing;
            for (int j = 0; j < s.length(); j++) {
                char c = s.charAt(j);
                for (int i = 0; i < f.height; i++) {
                    String r = f.m.get(c)[i];
                    if (j > 0) {
                        r = r.substring(overlap);
                    }
                    rows[i] += r;
                }
            }
        }
        return String.join("\n", rows);
    }
 
    private static final Font lean = new Font(5, 1, 2, Map.of(
            'G', new String[]{
                    "  _/_/_/",
                    "_/      ",
                    "_/  _/_/",
                    "_/    _/",
                    "  _/_/_/",
            },
            'o', new String[]{
                    "        ",
                    "  _/_/  ",
                    "_/    _/",
                    "_/    _/",
                    "  _/_/  ",
            }));
 
    private static final Font smallKeyboard = new Font(4, 0, -1, Map.of(
            'G', new String[]{
                    " ____ ",
                    "||G ||",
                    "||__||",
                    "|/__\\|",
            },
            'o', new String[]{
                    " ____ ",
                    "||o ||",
                    "||__||",
                    "|/__\\|",
            }));
 
    private static class Font {
        private final int height;
        private final int slant;
        private final int spacing;
        private final Map<Character, String[]> m;
 
        private Font(int height, int slant, int spacing, Map<Character, String[]> m) {
            this.height = height;
            this.slant = slant;
            this.spacing = spacing;
            this.m = m;
        }
    }
}

