import java.math.BigInteger;
import java.util.Scanner;
 
public class IntegerSquareRoot {
 
    public static BigInteger isqrt(BigInteger x) {
        BigInteger q = BigInteger.ONE;
        while (q.compareTo(x) <= 0)
            q = q.shiftLeft(2);
        BigInteger r = BigInteger.ZERO;
        while (q.compareTo(BigInteger.ONE) > 0) {
            q = q.shiftRight(2);
            BigInteger t = x.subtract(r).subtract(q);
            r = r.shiftRight(1);
            if (t.compareTo(BigInteger.ZERO) >= 0) {
                x = t;
                r = r.add(q);
            }
        }
        return r;
    }
 
    public static String commatize(BigInteger n) {
        String str = n.toString();
        StringBuilder result = new StringBuilder(4 * str.length() / 3);
        for (int i = 0; i < str.length(); ++i) {
            if (i > 0 && i % 3 == str.length() % 3)
                result.append(',');
            result.append(str.charAt(i));
        }
        return result.toString();
    }
 
    public static void main(String[] args) {
        System.out.println("Integer square root for numbers 0 to 65:");
        for (int n = 0; n <= 65; ++n)
            System.out.print(isqrt(BigInteger.valueOf(n)) + " ");
        System.out.println("\n");
 
        System.out.println("Integer square roots of odd powers of 7 from 1 to 73:");
        final int power_width = 83, isqrt_width = 42;
        System.out.printf("%2s |%-" + power_width + "s |%-" + isqrt_width + "s\n", "n", "7 ^ n", "isqrt(7 ^ n)");
        System.out.println(new String(6 + power_width + isqrt_width, '-'));
        BigInteger p = BigInteger.valueOf(7);
        for (int n = 1; n <= 73; n += 2, p = p.multiply(BigInteger.valueOf(49))) {
            System.out.printf("%2d |%-" + power_width + "s |%-" + isqrt_width + "s\n", n, commatize(p), commatize(isqrt(p)));
        }
    }
}

