    public static void walkDirectory(File dir, Pattern re_pattern) {
        System.out.println("Files in " + dir.getName() + " matching '" + re_pattern + "':");
        walkDirectoryFilter(dir.listFiles(), re_pattern);
 
        System.out.println("Folders in " + dir.getName() + " matching '" + re_pattern + "':");
        walkDirectoryFilter(dir.listFiles(), re_pattern);
    }
 
