        for (File item : items) {
            if (item.getName().matches(re_pattern.pattern()))
                System.out.println(item.getName());
        }
    }
}

import java.util.Arrays;
 
public class QuickSort {
 
  public static void main(String[] args) {
    int[] a = {4, 65, 2, -31, 0, 99, 2, 83, 782, 1};
    int n = a.length;
 
    System.out.println(Arrays.toString(a));
 
    quicksort(a, n);
 
    System.out.println(Arrays.toString(a));
  }
 
  public static void quicksort(int[] A, int len) {
    if (len < 2) return;
 
    int pivot = A[len / 2];
 
    int i, j;
    for (i = 0, j = len - 1; ; i++, j--) {
      while (A[i] < pivot) i++;
      while (A[j] > pivot) j--;
 
      if (i >= j) break;
 
      int temp = A[i];
      A[i]     = A[j];
      A[j]     = temp;
    }
 
    quicksort(A, i);
    quicksort(A, len - i);
  }
}

import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.util.Random;
 
public class HtmlTable {
 
    public static void main(String[] args) {
        char[] chars = { 'X', 'Y', 'Z' };
        int headgap = 3;
        int bodygap = 3;
        int tablegap = 6;
        int rowgap = 9;
        String tabletext = "<html>\n";
        makeGap(headgap, tabletext);
        tabletext += "<head></head>\n";
        makeGap(bodygap, tabletext);
        tabletext += "<body>\n";
        makeGap(tablegap, tabletext);
        tabletext += "<table>\n";
        makeGap(tablegap + 1, tabletext);
        tabletext += "<thead align=\"right\">\n";
        makeGap(tablegap, tabletext);
        tabletext += "<tr><th></th>";
        for (int i = 0; i < 3; i++) {
            tabletext += "<td>";
            tabletext += chars[i];
            tabletext += "</td>";
        }
        tabletext += "</tr>\n";
        makeGap(tablegap + 1, tabletext);
        tabletext += "</thead>";
        makeGap(tablegap + 1, tabletext);
        tabletext += "<tbody align=\"right\">\n";
        Random rand = new Random();
        for (int row = 0; row < 5; row++) {
            makeGap(rowgap, tabletext);
            tabletext += "<tr><td>";
            tabletext += row;
            for (int col = 0; col < 3; col++) {
                tabletext += "<td>";
                int randnumber = rand.nextInt(10000);
                tabletext += randnumber;
                tabletext += "</td>";
            }
            tabletext += "</tr>\n";
        }
        makeGap(tablegap + 1, tabletext);
        tabletext += "</tbody>\n";
        makeGap(tablegap, tabletext);
        tabletext += "</table>\n";
        makeGap(bodygap, tabletext);
        tabletext += "</body>\n";
        tabletext += "</html>\n";
        try {
            Writer htmltable = new OutputStreamWriter(new FileOutputStream("testtable.html"), "UTF-8");
            htmltable.write(tabletext);
            htmltable.close();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
 
    public static void makeGap(int gap, String text) {
        for (int i = 0; i < gap; i++) {
            text += " ";
        }
    }
}

