import java.io.*;
import java.util.*;
 
public class Brazillian {
    public static boolean sameDigits(int n, int b) {
        int f = n % b;
        while ((n /= b) > 0) {
            if (n % b!= f) {
                return false;
            }
        }
        return true;
    }
 
    public static boolean isBrazilian(int n) {
        if (n < 7) return false;
        if (n % 2 == 0)return true;
        for (int b = 2; b < n - 1; b++) {
            if (sameDigits(n, b)) {
                return true;
            }
        }
        return false;
    }
 
    public static boolean isPrime(int n) {
        if (n < 2)return false;
        if (n % 2 == 0)return n == 2;
        if (n % 3 == 0)return n == 3;
        int d = 5;
        while (d * d <= n) {
            if (n % d == 0)return false;
            d += 2;
            if (n % d == 0)return false;
            d += 4;
        }
        return true;
    }
 
    public static void main(String[] args) {
        for (String kind : new String[] { "", "odd ", "prime " }) {
            boolean quiet = false;
            int BigLim = 99999;
            int limit = 20;
            System.out.println("First " + limit +'' + kind + "Brazillian numbers:");
            int c = 0;
            int n = 7;
            while (c < BigLim) {
                if (isBrazilian(n)) {
                    if (!quiet)System.out.print(n +'');
                    if (++c == limit) {
                        System.out.println("\n\n");
                        quiet = true;
                    }
                }
                if (quiet && kind!= "") continue;
                if (kind == "") {
                    n++;
                }
                else if (kind == "odd ") {
                    n += 2;
                }
                else if (kind == "prime ") {
                    while (true) {
                        n += 2;
                        if (isPrime(n)) break;
                    }
                } else {
                    throw new RuntimeException("Unexpected");
                }
            }
            if (kind == "") {
                System.out.println("The " + (BigLim + 1) + "th Brazillian number is: " + n + "\n\n");
            }
        }
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class Program {
    public static void main(String[] args) {
        for (String s : "a!===b=!=c".multisplit(true, "==", "!=", "=")) {
            System.out.print(s);
        }
        System.out.println();
    }
 
    public static List<String> multisplit(String s, boolean returnSeparators, String... delimiters) {
        StringBuilder currentString = new StringBuilder();
        int index = 0;
 
        while (index < s.length()) {
            String foundDelimiter = null;
            for (String delimiter : delimiters) {
                if (s.length() >= index + delimiter.length() && s.substring(index, index + delimiter.length()).equals(delimiter)) {
                    foundDelimiter = delimiter;
                    break;
                }
            }
 
            if (foundDelimiter!= null) {
                List<String> result = new ArrayList<String>();
                result.add(currentString.toString());
                if (returnSeparators) {
                    result.add(String.format("{%s, (%d, %d)}", foundDelimiter, index, index + foundDelimiter.length()));
                }
                currentString.setLength(0);
                index += foundDelimiter.length();
                return result;
            } else {
                currentString.append(s.charAt(index++));
            }
        }
 
        if (currentString.length() > 0) {
            List<String> result = new ArrayList<String>();
            result.add(currentString.toString());
            return result;
        }
 
        return new ArrayList<String>();
    }
}

