import java.util.Random;
 
public class RandomCircle {
 
	public static void main(String[] args) {
		int i, x, y, r2;
		long buf[] = new long[31];
		Random rand = new Random();
		for (i = 0; i < 100; ) {
			x = randn(31, rand) - 15;
			y = randn(31, rand) - 15;
			r2 = x * x + y * y;
			if (r2 >= 100 && r2 <= 225) {
				buf[15 + y] |= 1 << (x + 15);
				i++;
			}
		}
		for (y = 0; y < 31; y++) {
			for (x = 0; x < 31; x++)
				System.out.print((buf[y] & 1 << x)? ". " : "  ");
			System.out.println();
		}
	}
 
	public static int randn(int m, Random rand) {
		int rand_max = rand.nextInt();
		int r;
		while ((r = rand.nextInt()) > rand_max);
		return r / (rand_max / m);
	}
}

