import java.net.ServerSocket;
import java.net.Socket;
 
public class EchoServer {
    public static void main(String[] args) throws IOException {
        int port = 12321;
        ServerSocket server = new ServerSocket(port);
        System.out.println("server listening on " + server.getInetAddress() + ":" + server.getLocalPort());
        while (true) {
            Socket client = server.accept();
            new EchoRequestHandler(client).start();
        }
    }
}
 
class EchoRequestHandler extends Thread {
    private Socket client;
    public EchoRequestHandler(Socket client) {
        this.client = client;
    }
    public void run() {
        try {
            BufferedReader in = new BufferedReader(new InputStreamReader(client.getInputStream()));
            PrintWriter out = new PrintWriter(client.getOutputStream(), true);
            String line;
            while ((line = in.readLine())!= null) {
                System.out.println(client.getInetAddress() + " wrote: " + line);
                out.println(line);
            }
            System.out.println(client.getInetAddress() + " disconnected");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;
 
public class NQueens {
 
    public static void main(String[] args) {
        int n = 8;
        int[] cols = IntStream.range(0, n).toArray();
        List<int[]> combs = combinations(cols, 2);
        List<int[]> solved = IntStream.of(cols)
               .boxed()
               .sorted()
               .map(i -> i.toArray())
               .filter(v -> combs.stream().allMatch(c -> Math.abs(v[c[0]] - v[c[1]])!= Math.abs(c[0] - c[1])))
               .collect(Collectors.toList());
 
        System.out.println(n + "-queens has " + solved.size() + " solutions");
        System.out.println("Position is row, value is column:-");
        String first = Arrays.toString(solved.get(0));
        System.out.println("First Solution: " + first);
    }
 
    //Helpers 
    public static List<int[]> permutations(int[] values) {
        if (values.length == 1) {
            return Arrays.asList(values);
        }
 
        List<int[]> result = new ArrayList<>();
        for (int i = 0; i < values.length; i++) {
            int[] v = new int[]{values[i]};
            for (int[] p : permutations(Arrays.copyOfRange(values, 0, i)
                   .concat(Arrays.copyOfRange(values, i + 1, values.length)))) {
                result.add(concat(v, p));
            }
        }
        return result;
    }
 
    public static List<int[]> combinations(int[] seq, int numItems) {
        List<int[]> result = new ArrayList<>();
        for (int i = 0; i < seq.length; i++) {
            int[] v = new int[]{seq[i]};
            for (int[] p : combinations(Arrays.copyOfRange(seq, 0, i)
                   .concat(Arrays.copyOfRange(seq, i + 1, seq.length)), numItems - 1)) {
                result.add(concat(v, p));
            }
        }
        return result;
    }
 
    public static int[] concat(int[] a, int[] b) {
        int[] result = new int[a.length + b.length];
        System.arraycopy(a, 0, result, 0, a.length);
        System.arraycopy(b, 0, result, a.length, b.length);
        return result;
    }
}

public class RomanNumerals {
    private static class RomanNumeral {
        String symbol;
        int value;

        RomanNumeral(String symbol, int value) {
            this.symbol = symbol;
            this.value = value;
        }
    }

    private static final RomanNumeral[] NUMERALS = {
            new RomanNumeral("M", 1000),
            new RomanNumeral("CM", 900),
            new RomanNumeral("D", 500),
            new RomanNumeral("CD", 400),
            new RomanNumeral("C", 100),
            new RomanNumeral("XC", 90),
            new RomanNumeral("L", 50),
            new RomanNumeral("XL", 40),
            new RomanNumeral("X", 10),
            new RomanNumeral("IX", 9),
            new RomanNumeral("V", 5),
            new RomanNumeral("IV", 4),
            new RomanNumeral("I", 1)
    };

    public static int toHindu(String roman) {
        for (RomanNumeral num : NUMERALS) {
            if (roman.startsWith(num.symbol)) {
                return num.value + toHindu(roman.substring(num.symbol.length()));
            }
        }
        return 0;
    }

    public static void main(String[] args) {
        String[] roms = {"MMXIV", "MCMXCIX", "XXV", "MDCLXVI", "MMMDCCCLXXXVIII"};
        for (String r : roms) {
            System.out.printf("%15s = %d%n", r, toHindu(r));
        }
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class Hailstone {
 
    public static List<Integer> hailstone(int n) {
        List<Integer> seq = new ArrayList<Integer>();
        seq.add(n);
        while (n > 1) {
            n = (n & 1) == 1? 3 * n + 1 : n / 2;
            seq.add(n);
        }
        return seq;
    }
 
    public static void main(String[] args) {
        List<Integer> h = hailstone(27);
        assert h.size() == 112 && h.subList(0, 4).equals(Arrays.asList(27, 82, 41, 124)) && h.subList(h.size() - 4, h.size()).equals(Arrays.asList(8, 4, 2, 1));
        System.out.println("Maximum length " + max(i -> hailstone(i).size(), 1, 100000) + " was found for hailstone(" + max(i -> hailstone(i).size(), 1, 100000) + ") for numbers <100,000");
    }
 
    public static <T> T max(Function<Integer, T> f, int start, int end) {
        T max = f.apply(start);
        for (int i = start + 1; i < end; i++) {
            T value = f.apply(i);
            if (value.compareTo(max) > 0) {
                max = value;
            }
        }
        return max;
    }
 
    @FunctionalInterface
    public interface Function<T, R> {
        R apply(T t);
    }
}

