import java.util.Arrays;
 
public class SelfNumbers {
    private static final int MC = 103 * 1000 * 10000 + 11 * 9 + 1;
    private static final boolean[] SV = new boolean[MC + 1];
    
    private static void sieve() {
        int[] dS = new int[10000];
        for (int a = 9, i = 9999; a >= 0; a--) {
            for (int b = 9; b >= 0; b--) {
                for (int c = 9, s = a + b; c >= 0; c--) {
                    for (int d = 9, t = s + c; d >= 0; d--) {
                        dS[i--] = t + d;
                    }
                }
            }
        }
        for (int a = 0, n = 0; a < 103; a++) {
            for (int b = 0, d = dS[a]; b < 1000; b++) {
                for (int c = 0, s = d + dS[b] + n; c < 10000; c++) {
                    SV[dS[c] + s++] = true;
                }
            }
            n += 10000;
        }
    }
    
    public static void main(String[] args) {
        sieve();
        System.out.println("The first 50 self numbers are:");
        for (int i = 0, count = 0; count <= 50; i++) {
            if (!SV[i]) {
                count++;
                if (count <= 50) {
                    System.out.print(i + " ");
                } else {
                    System.out.println();
                    System.out.println();
                    System.out.println("       Index     Self number");
                }
            }
        }
        for (int i = 0, limit = 1, count = 0; i < MC; i++) {
            if (!SV[i]) {
                if (++count == limit) {
                    System.out.printf("%,12d   %,13d%n", count, i);
                    limit *= 10;
                }
            }
        }
    }
}

import java.io.*;
import java.util.*;
import java.lang.*;
 
public class Substring
{
 
    /*
     * Put no more than m characters from string to standard output.
     *
     * It is worth noting that printf("%*s",width,string) does not limit the number
     * of characters to be printed.
     *
     * @param string null terminated string
     * @param m      number of characters to display
     */
    public static void putm(String string, int m)
    {
        for(int i = 0; i < m && i < string.length(); i++)
            System.out.print(string.charAt(i));
    }
 
    public static void main(String[] args)
    {
 
        String string = 
            "Programs for other encodings (such as 8-bit ASCII, or EUC-JP).";
 
        int n = 3;
        int m = 4;
        char knownCharacter = '(';
        String knownSubstring = "encodings";
 
        putm(string.substring(n-1, n-1+m), m );                       System.out.println();
        System.out.println(string.substring(n+1));                    System.out.println();
        putm(string.substring(0, string.length()-1), string.length()-1); System.out.println();
        putm(string.substring(string.indexOf(knownCharacter), string.indexOf(knownCharacter)+m), m );   System.out.println();
        putm(string.substring(string.indexOf(knownSubstring), string.indexOf(knownSubstring)+m), m );   System.out.println();
 
    }
}

import java.math.BigInteger;
import java.math.BigDecimal;
import java.math.MathContext;
import java.util.Arrays;
 
public class Faulhaber {
 
    public static BigInteger binomial(int n, int k) {
        if (n < 0 || k < 0 || n < k) {
            return BigInteger.valueOf(-1);
        }
        if (n == 0 || k == 0) {
            return BigInteger.valueOf(1);
        }
 
        BigInteger num = BigInteger.valueOf(1);
        for (int i = k + 1; i <= n; i++) {
            num = num.multiply(BigInteger.valueOf(i));
        }
 
        BigInteger denom = BigInteger.valueOf(1);
        for (int i = 2; i <= n - k; i++) {
            denom = denom.multiply(BigInteger.valueOf(i));
        }
 
        return num.divide(denom);
    }
 
    public static BigDecimal bernoulli(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n cannot be less than zero");
        }
 
        BigDecimal[] a = new BigDecimal[16];
        Arrays.fill(a, BigDecimal.ZERO);
        a[n] = BigDecimal.ONE.divide(BigDecimal.valueOf(n + 1), MathContext.DECIMAL128);
        for (int m = n; m > 0; m--) {
            for (int j = m; j > 0; j--) {
                a[j - 1] = a[j - 1].subtract(a[j]).multiply(BigDecimal.valueOf(j));
            }
        }
 
        if (n!= 1) {
            return a[0];
        }
        return a[0].negate();
    }
 
    public static void faulhaber(int p) {
        System.out.printf("%d : ", p);
        BigDecimal q = BigDecimal.ONE.divide(BigDecimal.valueOf(p + 1), MathContext.DECIMAL128);
        int sign = -1;
        for (int j = 0; j <= p; j++) {
            sign = -1 * sign;
            BigDecimal coeff = q.multiply(BigDecimal.valueOf(sign)).multiply(BigDecimal.valueOf(binomial(p + 1, j))).multiply(bernoulli(j));
            if (coeff.equals(BigDecimal.ZERO)) {
                continue;
            }
            if (j == 0) {
                if (!coeff.equals(BigDecimal.ONE)) {
                    if (coeff.equals(BigDecimal.valueOf(-1))) {
                        System.out.print("-");
                    } else {
                        System.out.print(coeff);
                    }
                }
            } else {
                if (coeff.equals(BigDecimal.ONE)) {
                    System.out.print(" + ");
                } else if (coeff.equals(BigDecimal.valueOf(-1))) {
                    System.out.print(" - ");
                } else if (coeff.compareTo(BigDecimal.ZERO) > 0) {
                    System.out.print(" + ");
                    System.out.print(coeff);
                } else {
                    System.out.print(" - ");
                    System.out.print(coeff.negate());
                }
            }
            int pwr = p + 1 - j;
            if (pwr > 1) {
                System.out.printf("n^%d", pwr);
            } else {
                System.out.print("n");
            }
        }
        System.out.println();
    }
 
    public static void main(String[] args) {
        for (int i = 0; i <= 9; i++) {
            faulhaber(i);
        }
    }
}

