public static List<String> ncsub(String seq, int s) {
    if (seq.length() > 0) {
        String x = seq.substring(0, 1);
        String xs = seq.substring(1);
        int p2 = s % 2;
        int p1 = 1 - p2;
        return concat(map(y -> x + y, ncsub(xs, s + p1)), ncsub(xs, s + p2));
    } else {
        return s >= 3? Collections.singletonList("") : Collections.emptyList();
    }
}

