// Sample classes for reflection
public class Super {
    public String name;
    public Super(String name) {
        this.name = name;
    }
    public String superOwn() { return "super owned"; }
    public String toString() { return "Super(" + this.name + ")"; }
    public String doSup() { return "did super stuff"; }
}
 
public class Sub extends Super {
    public List<Object> rest;
    public Sub(String name, Object... rest) {
        super(name);
        this.rest = Arrays.asList(rest);
    }
    public String subOwn() { return "sub owned"; }
    public String toString() { return "Sub(" + this.name + ")"; }
    public String doSub() { return "did sub stuff"; }
    public String shush() { return " non-enumerable"; }
    public String quiet() { return "sub owned non-enumerable"; }
}
 
