import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
 
public class Textonyms {
 
    private static final Map<Character, Character> textMap = new HashMap<>();
 
    static {
        textMap.put('a', '2');
        textMap.put('b', '2');
        textMap.put('c', '2');
        textMap.put('d', '3');
        textMap.put('e', '3');
        textMap.put('f', '3');
        textMap.put('g', '4');
        textMap.put('h', '4');
        textMap.put('i', '4');
        textMap.put('j', '5');
        textMap.put('k', '5');
        textMap.put('l', '5');
        textMap.put('m', '6');
        textMap.put('n', '6');
        textMap.put('o', '6');
        textMap.put('p', '7');
        textMap.put('q', '7');
        textMap.put('r', '7');
        textMap.put('s', '7');
        textMap.put('t', '8');
        textMap.put('u', '8');
        textMap.put('v', '8');
        textMap.put('w', '9');
        textMap.put('x', '9');
        textMap.put('y', '9');
        textMap.put('z', '9');
    }
 
    private static String textString(String s) {
        StringBuilder text = new StringBuilder();
        for (char c : s.toCharArray()) {
            Character t = textMap.get(c);
            if (t == null) {
                return null;
            }
            text.append(t);
        }
        return text.toString();
    }
 
    private static void printTopWords(List<Map.Entry<String, List<String>>> textonyms, int top) {
        for (Map.Entry<String, List<String>> entry : textonyms.subList(0, top)) {
            System.out.println(entry.getKey() + " = " + String.join(", ", entry.getValue()));
        }
    }
 
    private static void findTextonyms(String filename) throws IOException {
        Map<String, List<String>> table = new HashMap<>();
        int count = 0;
 
        try (BufferedReader reader = new BufferedReader(new FileReader(filename))) {
            String line;
            while ((line = reader.readLine())!= null) {
                String word = line.toLowerCase();
                String text = textString(word);
                if (text!= null) {
                    List<String> words = table.computeIfAbsent(text, k -> new ArrayList<>());
                    words.add(word);
                    count++;
                }
            }
        }
 
        List<Map.Entry<String, List<String>>> textonyms = new ArrayList<>(table.entrySet());
 
        System.out.printf("There are %d words in '%s' which can be represented by the digit key mapping.%n", count, filename);
        System.out.printf("They require %d digit combinations to represent them.%n", table.size());
        System.out.printf("%d digit combinations represent Textonyms.%n", textonyms.size());
 
        int top = Math.min(5, textonyms.size());
        textonyms.sort(Comparator.comparingInt(e -> -e.getValue().size()).thenComparing(Map.Entry::getKey));
        System.out.printf("%nTop %d by number of words:%n", top);
        printTopWords(textonyms, top);
 
        textonyms.sort(Comparator.comparingInt(e -> -e.getKey().length()).thenComparing(Map.Entry::getKey));
        System.out.printf("%nTop %d by length:%n", top);
        printTopWords(textonyms, top);
    }
 
    public static void main(String[] args) throws IOException {
        if (args.length!= 1) {
            System.err.println("usage: " + Textonyms.class.getSimpleName() + " word-list");
            System.exit(1);
        }
        findTextonyms(args[0]);
    }
}

public static <T extends Comparable<T>> void merge(T[] x1, T[] x2, T[] y) {
	assert x1.length + x2.length == y.length;
	int i = 0;
	int j = 0;
	int k = 0;
	while (i < x1.length && j < x2.length) {
		if (x1[i].compareTo(x2[j]) < 0) {
			y[k] = x1[i];
			k += 1;
			i += 1;
		} else {
			y[k] = x2[j];
			k += 1;
			j += 1;
		}
	}
	if (i < x1.length) {
		System.arraycopy(x1, i, y, k, x1.length - i);
	}
	if (j < x2.length) {
		System.arraycopy(x2, j, y, k, x2.length - j);
	}
}

// version 1.1.3
 
import java.util.Random;
 
public class Flip {
    private static final Random rand = new Random();
    private static final int[][] target = new int[3][3];
    private static final int[][] board = new int[3][3];
 
    private static void flipRow(int r) {
        for (int c = 0; c < 3; c++) {
            board[r][c] = (board[r][c] == 0)? 1 : 0;
        }
    }
 
    private static void flipCol(int c) {
        for (int r = 0; r < 3; r++) {
            board[r][c] = (board[r][c] == 0)? 1 : 0;
        }
    }
 
    /** starting from the target we make 9 random row or column flips */
    private static void initBoard() {
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                board[i][j] = target[i][j];
            }
        }
        for (int i = 0; i < 9; i++) {
            int rc = rand.nextInt(2);
            if (rc == 0) {
                flipRow(rand.nextInt(3));
            } else {
                flipCol(rand.nextInt(3));
            }
        }
    }
 
    private static void printBoard(String label, boolean isTarget) {
        int[][] a = isTarget? target : board;
        System.out.println(label + ":");
        System.out.println("  | a b c");
        System.out.println("---------");
        for (int r = 0; r < 3; r++) {
            System.out.print((r + 1) + " |");
            for (int c = 0; c < 3; c++) {
                System.out.print(" " + a[r][c]);
            }
            System.out.println();
        }
        System.out.println();
    }
 
    private static boolean gameOver() {
        for (int r = 0; r < 3; r++) {
            for (int c = 0; c < 3; c++) {
                if (board[r][c]!= target[r][c]) {
                    return false;
                }
            }
        }
        return true;
    }
 
    public static void main(String[] args) {
        // initialize board and ensure it differs from the target i.e. game not already over!
        do {
            initBoard();
        }
        while (gameOver());
 
        printBoard("TARGET", true);
        printBoard("OPENING BOARD", false);
        int flips = 0;
 
        do {
            boolean isRow = true;
            int n = -1;
            do {
                System.out.print("Enter row number or column letter to be flipped: ");
                String input = System.console().readLine();
                char ch = (input.length() > 0)? Character.toLowerCase(input.charAt(0)) : '0';
                if (ch < '1' || ch > '3' && ch < 'a' || ch > 'c') {
                    System.out.println("Must be 1, 2, 3, a, b or c");
                    continue;
                }
                if (ch >= '1' && ch <= '3') {
                    n = ch - 49;
                } else {
                    isRow = false;
                    n = ch - 97;
                }
            }
            while (n == -1);
 
            flips++;
            if (isRow) {
                flipRow(n);
            } else {
                flipCol(n);
            }
            String plural = (flips == 1)? "" : "S";
            printBoard("\nBOARD AFTER " + flips + " FLIP" + plural, false);
        }
        while (!gameOver());
 
        String plural = (flips == 1)? "" : "s";
        System.out.println("You've succeeded in " + flips + " flip" + plural);
    }
}

import java.awt.Toolkit;
import java.util.HashMap;
import java.util.Map;
 
public class MorseCode {
 
    private static final Map<Character, String> MORSE = new HashMap<Character, String>();
    private static final int T_UNIT = 75; // ms
    private static final int FREQ = 700;
    private static final int DIT = 1 * T_UNIT;
    private static final int DAH = 3 * T_UNIT;
    private static final int CHARGAP = 1 * T_UNIT;
    private static final int WORDGAP = 7 * T_UNIT;
 
    static {
        MORSE.put('!', "---.");
        MORSE.put('"', ".-..-.");
        MORSE.put('$', "...-..-");
        MORSE.put('\'', ".----.");
        MORSE.put('(', "-.--.");
        MORSE.put(')', "-.--.-");
        MORSE.put('+', ".-.-.");
        MORSE.put(',', "--..--");
        MORSE.put('-', "-....-");
        MORSE.put('.', ".-.-.-");
        MORSE.put('/', "-..-.");
        MORSE.put('0', "-----");
        MORSE.put('1', ".----");
        MORSE.put('2', "..---");
        MORSE.put('3', "...--");
        MORSE.put('4', "....-");
        MORSE.put('5', ".....");
