        MORSE.put('7', "--...");
        MORSE.put('8', "---..");
        MORSE.put('9', "----.");
        MORSE.put(':', "---...");
        MORSE.put(';', "-.-.-.");
        MORSE.put('=', "-...-");
        MORSE.put('?', "..--..");
        MORSE.put('@', ".--.-.");
        MORSE.put('A', ".-");
        MORSE.put('B', "-...");
        MORSE.put('C', "-.-.");
        MORSE.put('D', "-..");
        MORSE.put('E', ".");
        MORSE.put('F', "..-.");
        MORSE.put('G', "--.");
        MORSE.put('H', "....");
        MORSE.put('I', "..");
        MORSE.put('J', ".---");
        MORSE.put('K', "-.-");
        MORSE.put('L', ".-..");
