        MORSE.put('S', "...");
        MORSE.put('T', "-");
        MORSE.put('U', "..-");
        MORSE.put('V', "...-");
        MORSE.put('W', ".--");
        MORSE.put('X', "-..-");
        MORSE.put('Y', "-.--");
        MORSE.put('Z', "--..");
        MORSE.put('[', "-.--.");
        MORSE.put(']', "-.--.-");
        MORSE.put('_', "..--.-");
    }
 
    private String message;
 
    public MorseCode(String message) {
        this.message = message;
        System.out.println("your message is " + message);
    }
 
    public void send() {
        for (String word : message.trim().toUpperCase().split(" ")) {
            for (char c : word.toCharArray()) {
                sendChar(c);
                pause(CHARGAP);
                System.out.print(" ");
            }
            pause(WORDGAP);
            System.out.println("");
        }
    }
 
    private void sendChar(char c) {
        for (char code : MORSE.get(c).toCharArray()) {
            switch (code) {
                case '.':
                    beep(DIT);
                    break;
                case '-':
                    beep(DAH);
                    break;
            }
            pause(CHARGAP);
            System.out.print(code);
        }
    }
 
    private void beep(int ms) {
        Toolkit.getDefaultToolkit().beep();
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
 
    private void pause(int ms) {
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
 
    public static void main(String[] args) {
        new MorseCode("sos").send();
        new MorseCode("this is a test.").send();
    }
}

import java.io.*;
import java.util.*;
import java.lang.*;
import java.math.*;
 
public class Fusc {
 
    private static final int n = 61;
    private static List<Integer> l = new ArrayList<Integer>(Arrays.asList(0, 1));
 
    private static int fusc(int n) {
        if (n < l.size()) {
            return l.get(n);
        }
        int f = (n & 1) == 0? l.get(n >> 1) : l.get((n - 1) >> 1) + l.get((n + 1) >> 1);
        l.add(f);
        return f;
    }
 
    public static void main(String[] args) {
        boolean lst = true;
        int w = -1;
        int c = 0;
        int t;
        String res = "";
        System.out.println("First " + n + " numbers in the fusc sequence:");
        for (int i = 0; i < Integer.MAX_VALUE; i++) {
            int f = fusc(i);
            if (lst) {
                if (i < 61) {
                    System.out.print(f + " ");
                } else {
                    lst = false;
                    System.out.println("\nPoints in the sequence where an item has more digits than any previous items:");
                    System.out.println(String.format("%11s", "Index\\") + "  " + String.format("%9s", "/Value"));
                    System.out.println(res);
                    res = "";
                }
            }
            t = String.valueOf(f).length();
            if (t > w) {
                w = t;
                res += (res == ""? "" : "\n");
                res += String.format("%11d", i) + "  " + String.format("%9d", f);
                if (!lst) {
                    System.out.println(res);
                    res = "";
                }
                if (++c > 5) {
                    break;
                }
            }
        }
    }
}

