            System.out.println("not a is " + (~a));
            System.out.println("a lshift b is " + (a << b));
            System.out.println("a arshift b is " + (a >> b)); // When the left operand of the >> operator is of a signed integral type, 
                                                             // the operator performs an arithmetic shift right
            int c = a;
            System.out.println("c rshift b is " + (c >> b)); // When the left operand of the >> operator is of an unsigned integral type, 
                                                            // the operator performs a logical shift right
            // there are no rotation operators in C#
        }

import java.io.*;
import java.util.*;

public class Magnanimous {
    public static boolean is_prime(int n) {
        if (n < 2)
            return false;
        if (n % 2 == 0)
            return n == 2;
        if (n % 3 == 0)
            return n == 3;
        for (int p = 5; p * p <= n; p += 4) {
            if (n % p == 0)
                return false;
            p += 2;
            if (n % p == 0)
                return false;
        }
        return true;
    }

    public static boolean is_magnanimous(int n) {
        for (int p = 10; n >= p; p *= 10) {
            if (!is_prime(n % p + n / p))
                return false;
        }
        return true;
    }

    public static void main(String[] args) {
        int count = 0, n = 0;
        System.out.println("First 45 magnanimous numbers:");
        for (; count < 45; ++n) {
            if (is_magnanimous(n)) {
                if (count > 0)
                    System.out.print((count % 15 == 0? "\n" : ", "));
                System.out.printf("%3d", n);
                ++count;
            }
        }
        System.out.println("\n\n241st through 250th magnanimous numbers:");
        for (int i = 0; count < 250; ++n) {
            if (is_magnanimous(n)) {
                if (count++ >= 240) {
                    if (i++ > 0)
                        System.out.print(", ");
                    System.out.print(n);
                }
            }
        }
        System.out.println("\n\n391st through 400th magnanimous numbers:");
        for (int i = 0; count < 400; ++n) {
            if (is_magnanimous(n)) {
                if (count++ >= 390) {
                    if (i++ > 0)
                        System.out.print(", ");
                    System.out.print(n);
                }
            }
        }
        System.out.println();
    }
}

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JFrame;
import javax.swing.JPanel;
 
public class ChessBoard extends JPanel {
    private static final long serialVersionUID = 1L;
    private int width = 640;
    private int height = 400;
    private int columnCount = 8;    // number of columns 
    private int rowCount = 4;    // number of rows
    private int direction = 1;    // 1 = from left to right, 0 = from right to left
    private int blackLeft = 1;    // black is left: 1 = true, 0 = false
    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        Graphics2D g2d = (Graphics2D) g;
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        for(int j = 0; j < rowCount; j++){  
            for(int i = 0; i < columnCount; i++){
                g2d.setColor(new Color(0,0,0,(blackLeft-(1/(columnCount-1)*i))*direction));
                g2d.fillRect(
                    (width/columnCount)*i,(height/rowCount)*j,
                    (width/columnCount),(height/rowCount)
                    ); 
                }
            columnCount *= 2; 
            direction *= -1; 
            blackLeft = blackLeft == 1? 0 : 1;
            }
        }
    public static void main(String[] args) {
        JFrame frame = new JFrame("ChessBoard");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.add(new ChessBoard());
        frame.pack();
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
        }
    }

