class BinaryTree<T> {
    T value;
    BinaryTree<T> left;
    BinaryTree<T> right;
 
    BinaryTree(T value) {
        this.value = value;
    }
 
    <U> BinaryTree<U> map(Function<T, U> f) {
        BinaryTree<U> tree = new BinaryTree<U>(f.apply(value));
        if (left!= null) tree.left = left.map(f);
        if (right!= null) tree.right = right.map(f);
        return tree;
    }
 
    String showTopThree() {
        return "(" + (left == null? "null" : left.value) + ", " + value + ", " + (right == null? "null" : right.value) + ")";
    }
}
 
public class Main {
    public static void main(String[] args) {
        BinaryTree<Integer> b = new BinaryTree<Integer>(6);
        b.left = new BinaryTree<Integer>(5);
        b.right = new BinaryTree<Integer>(7);
        System.out.println(b.showTopThree());
        BinaryTree<Double> b2 = b.map(new Function<Integer, Double>() {
            public Double apply(Integer it) {
                return it * 10.0;
            }
        });
        System.out.println(b2.showTopThree());
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class Main {
 
    public static void main(String[] args) {
        String pokemon_names = "audino bagon baltoy banette bidoof braviary bronzor carracosta charmeleon\n" +
                "cresselia croagunk darmanitan deino emboar emolga exeggcute gabite\n" +
                "girafarig gulpin haxorus heatmor heatran ivysaur jellicent jumpluff kangaskhan\n" +
                "kricketune landorus ledyba loudred lumineon lunatone machamp magnezone mamoswine\n" +
                "nosepass petilil pidgeotto pikachu pinsir poliwrath poochyena porygon2\n" +
                "porygonz registeel relicanth remoraid rufflet sableye scolipede scrafty seaking\n" +
                "sealeo silcoon simisear snivy snorlax spoink starly tirtouga trapinch treecko\n" +
                "tyrogue vigoroth vulpix wailord wartortle whismur wingull yamask";
 
        String[] pokemon = pokemon_names.split(" |\n");
        List<String> chain = new ArrayList<>(pokemon.length);
 
        for (int i = 0; i < pokemon.length; i++) {
            swap(pokemon, 0, i);
            search(pokemon, chain, 1);
            swap(pokemon, 0, i);
        }
 
        for (String s : chain) {
            System.out.println(s);
        }
    }
 
    private static void search(String[] pokemon, List<String> longest_chain, int len) {
        if (len > longest_chain.size()) {
            longest_chain.clear();
            for (int i = 0; i < len; i++) {
                longest_chain.add(pokemon[i]);
            }
        }
 
        char lastchar = pokemon[len - 1].charAt(pokemon[len - 1].length() - 1);
        for (int i = len; i < pokemon.length; i++) {
            if (pokemon[i].charAt(0) == lastchar) {
                swap(pokemon, i, len);
                search(pokemon, longest_chain, len + 1);
                swap(pokemon, i, len);
            }
        }
    }
 
    private static void swap(String[] pokemon, int i, int j) {
        String tmp = pokemon[i];
        pokemon[i] = pokemon[j];
        pokemon[j] = tmp;
    }
}

import java.util.stream.IntStream;
 
public class MapRange {
    public static void main(String[] args) {
        IntStream.range(0, 11).forEach(i -> System.out.println(i + " maps to " + Map(0, 10, -1, 0, i)));
    }
 
    static double Map(double a1, double a2, double b1, double b2, double s) {
        return b1 + (s - a1) * (b2 - b1) / (a2 - a1);
    }
}

task_description:
Task

Write a program that prints the integers from   1   to   100   (inclusive).



But:

   for multiples of three,   print   Fizz     (instead of the number)
   for multiples of five,   print   Buzz     (instead of the number)
   for multiples of both three and five,   print   FizzBuzz     (instead of the number) 


The   FizzBuzz   problem was presented as the lowest level of comprehension required to illustrate adequacy.



Also see

   (a blog)   dont-overthink-fizzbuzz
   (a blog)   fizzbuzz-the-programmers-stairway-to-heaven

code:
public class FizzBuzz {
    public static void main(String[] args) {
        int i = 0;
        char[] B = new char[88];
        while (i++ < 100) {
            if (i % 3 == 0) {
                B = "Fizz".toCharArray();
            }
            if (i % 5 == 0) {
                B = "Buzz".toCharArray();
            }
            if (i % 3!= 0 && i % 5!= 0) {
                B = String.valueOf(i).toCharArray();
            }
            System.out.print(", " + new String(B));
        }
    }
}

import java.io.*;
import java.util.*;
 
public class Main {
    public static void main(String[] args) {
        for (int i = 98764321; i > 0; i--) {
            if (checkDec(i)) {
                System.out.println(i);
                break;
            }
        }
    }
 
    public static boolean checkDec(int num) {
        Set<Integer> set = new HashSet<>();
 
        String str = Integer.toString(num);
 
        for (int i = 0; i < str.length(); ++i) {
            char c = str.charAt(i);
            int d = c - '0';
            if (d == 0) return false;
            if (num % d!= 0) return false;
            if (set.contains(d)) {
                return false;
            }
            set.add(d);
        }
 
        return true;
    }
}

