import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import java.util.Scanner;
 
public class PigGame {
 
    private static class Player {
        private String name;
        private int safescore;
        private int score;
 
        public Player(String name, int safescore, int score) {
            this.name = name;
            this.safescore = safescore;
            this.score = score;
        }
 
        public void bust() {
            this.score = safescore;
        }
 
        public void stay() {
            this.safescore = score;
        }
 
        @Override
        public String toString() {
            return name + " (" + safescore + ", " + score + ")";
        }
    }
 
    private List<Player> rotation;
    private int maxscore;
    private int die_sides;
    private Random random;
    private Scanner scanner;
 
    public PigGame(String[] names, int maxscore, int die_sides) {
        this.maxscore = maxscore;
        this.die_sides = die_sides;
        this.random = new Random();
        this.scanner = new Scanner(System.in);
        rotation = new ArrayList<Player>();
        for (String name : names) {
            rotation.add(new Player(name, 0, 0));
        }
 
        for (Player player : rotation) {
            while (true) {
                if (wants_to_roll(player)) {
                    int roll = roll_dice();
                    System.out.println("Rolled: " + roll);
                    if (bust(roll)) {
                        System.out.println("Busted!");
                        player.bust();
                        break;
                    } else {
                        player.score += roll;
                        if (player.score >= maxscore) {
                            System.out.println(player.name + " wins!");
                            return;
                        }
                    }
                } else {
                    player.stay();
                    System.out.println("Staying with " + player.safescore + "!");
                    break;
                }
            }
        }
    }
 
    private int roll_dice() {
        return random.nextInt(die_sides) + 1;
    }
 
    private boolean bust(int roll) {
        return roll == 1;
    }
 
    private boolean wants_to_roll(Player player) {
        System.out.print(player + ": Roll? (Y) ");
        String input = scanner.nextLine();
        return input.equals("Y") || input.equals("y") || input.equals("");
    }
 
    public static void main(String[] args) {
        new PigGame(new String[] { "Samuel", "Elizabeth" }, 100, 6);
    }
}

