public class DotProduct {
    public static double dot_product(double[] ary1, double[] ary2) {
        if (ary1.length!= ary2.length)
            throw new RuntimeException("can't find dot product: arrays have different lengths");
        double dotprod = 0;
        for (int i = 0; i < ary1.length; i++)
            dotprod += ary1[i] * ary2[i];
        return dotprod;
    }

    public static void main(String[] args) {
        System.out.println(dot_product(new double[]{1,3,-5}, new double[]{4,-2,-1}));
        try {
            System.out.println(dot_product(new double[]{1,3,-5}, new double[]{4,-2,-1,0}));
        } catch (RuntimeException e) {
            System.out.println(e.getMessage());
        }
    }
}

