public class Main {
    public static List<String> getTitlesFromCategory(String category, URL url) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));
        String content = "";
        String line;
 
        while ((line = reader.readLine())!= null) {
            content += line;
        }
 
        reader.close();
 
        List<String> titles = new ArrayList<String>();
        Pattern pattern = Pattern.compile("\"title\":\"(.+?)\"");
        Matcher matcher = pattern.matcher(content);
 
        while (matcher.find()) {
            titles.add(matcher.group(1).replace("\\/", "/"));
        }
 
        return titles;
    }
 
    public static String getSourceCodeFromPage(String page, URL url) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));
        String content = "";
        String line;
 
        while ((line = reader.readLine())!= null) {
            content += line;
        }
 
        reader.close();
 
        return content;
    }
 
    public static void main(String[] args) throws MalformedURLException, IOException {
        URL url = new URL("http://www.rosettacode.org/w/api.php?action=query&list=categorymembers&cmtitle=Category:Programming_Tasks&cmlimit=500&format=json");
        List<Task> tasks = new ArrayList<Task>();
        List<String> tasknames = getTitlesFromCategory("Programming_Tasks", url);
 
        for (String task : tasknames) {
            String content = getSourceCodeFromPage(task, url);
            int count = Pattern.compile("=={{header", Pattern.CASE_INSENSITIVE).matcher(content).results().count();
            Task t = new Task(task, count);
 
            System.out.println(t);
            tasks.add(t);
        }
 
        System.out.println("\nTotal: " + tasks.stream().mapToInt(x -> x.getExamples()).sum() + " examples.");
    }
}

public class MRG32k3a {
    private static final int M1 = (1 << 32) - 209;
    private static final int M2 = (1 << 32) - 22853;
    private static final int D = M1 + 1;
    private static final int[] A1 = {0, 1403580, -810728};
    private static final int[] A2 = {527612, 0, -1370589};
    private int[] x1 = {0, 0, 0};
    private int[] x2 = {0, 0, 0};
    private static int mod(int x, int y) {
        int m = x % y;
        if (m < 0) {
            if (y < 0) {
                return m - y;
            } else {
                return m + y;
            }
        }
        return m;
    }
    public void seed(int seed_state) {
        x1[0] = seed_state;
        x2[0] = seed_state;
    }
    public int nextInt() {
        int x1i = mod(A1[0] * x1[0] + A1[1] * x1[1] + A1[2] * x1[2], M1);
        int x2i = mod(A2[0] * x2[0] + A2[1] * x2[1] + A2[2] * x2[2], M2);
        int z = mod(x1i - x2i, M1);
        x1[0] = x1i;
        x1[1] = x1[0];
        x1[2] = x1[1];
        x2[0] = x2i;
        x2[1] = x2[0];
        x2[2] = x2[1];
        return z + 1;
    }
    public double nextFloat() {
        return 1.0 * nextInt() / D;
    }
    public static void main(String[] args) {
        MRG32k3a mrg = new MRG32k3a();
        mrg.seed(1234567);
        System.out.println(mrg.nextInt());
        System.out.println(mrg.nextInt());
        System.out.println(mrg.nextInt());
        System.out.println(mrg.nextInt());
        System.out.println(mrg.nextInt());
        System.out.println();
        int[] counts = new int[5];
        mrg.seed(987654321);
        for (int i = 0; i < 100000; i++) {
            int value = (int) (mrg.nextFloat() * 5.0);
            counts[value]++;
        }
        for (int i = 0; i < 5; i++) {
            System.out.println(i + ": " + counts[i]);
        }
    }
}

